import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Ustawienia środowiska wykonawczego ACP umożliwiające włączanie przekazywania zadań, wybór backendów, ograniczanie dozwolonych agentów docelowych i wybór sposobu prezentacji strumieniowanych tur.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Dozwoleni agenci ACP`},help:{"v1-f2mw0d-3a":`Lista identyfikatorów docelowych agentów ACP dozwolonych w sesjach środowiska wykonawczego ACP. Pusta lista oznacza brak dodatkowych ograniczeń.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`Backend ACP`},help:{"v1-1s1l6bz-2v":`Identyfikator domyślnego backendu środowiska wykonawczego ACP (na przykład: acpx). Musi odpowiadać backendowi zarejestrowanej wtyczki środowiska wykonawczego ACP.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Domyślny agent ACP`},help:{"v1-7donnu-2c":`Zapasowy identyfikator docelowego agenta ACP używany, gdy przy uruchamianiu ACP nie określono jawnie agenta docelowego.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`Przekazywanie zadań ACP włączone`},help:{"v1-1ug9t9m-3w":`Niezależny przełącznik przekazywania zadań dla tur sesji ACP (domyślnie: true). Ustaw false, aby zachować dostępność poleceń ACP, jednocześnie blokując wykonywanie tur ACP.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP włączone`},help:{"v1-1uonl1v-2a":`Globalny przełącznik funkcji ACP. Pozostaw wyłączony, dopóki nie zostaną skonfigurowane środowisko wykonawcze ACP i zasady.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`Zapasowe backendy ACP`},help:{"v1-1wvdifq-5m":`Uporządkowana lista identyfikatorów zapasowych backendów ACP, wypróbowywanych, gdy główny backend zgłosi błąd UNAVAILABLE (na przykład z powodu limitu żądań lub wyczerpania limitu użycia). Każdy wpis musi odpowiadać zarejestrowanemu backendowi wtyczki środowiska wykonawczego ACP.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Polecenie instalacji środowiska wykonawczego ACP`},help:{"v1-1jjuv9m-39":"Opcjonalne polecenie instalacji lub konfiguracji dla operatora, wyświetlane przez `/acp install` i `/acp doctor`, gdy brakuje konfiguracji połączenia z backendem ACP."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`Strumień ACP`},help:{"v1-1bka5p-2v":`Ustawienia prezentacji strumienia ACP: rozmiar fragmentów, widoczność metadanych i sposób dostarczania bez duplikatów.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Tryb dostarczania strumienia ACP`},help:{"v1-19gdmx1-3s":`Sposób dostarczania ACP: live przesyła prezentowane dane wyjściowe przyrostowo, a final_only buforuje wszystkie prezentowane dane wyjściowe ACP do momentu wystąpienia zdarzeń kończących turę.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Pomijanie powtórzeń w strumieniu ACP`},help:{"v1-manh32-3d":`Gdy ustawiono true (domyślnie), pomija powtarzające się wiersze prezentujące statusy lub narzędzia ACP w obrębie tury, pozostawiając surowe zdarzenia ACP bez zmian.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Widoczność tagów strumienia ACP`},help:{"v1-1ybhx22-34":`Nadpisania widoczności prezentacji ACP dla poszczególnych typów sessionUpdate (na przykład usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agenci`},help:{"v1-2rc4v8-55":`Główna sekcja konfiguracji środowiska wykonawczego agentów. Sekcje równorzędne na najwyższym poziomie odpowiadają za infrastrukturę i ustawienia domyślne wspólne dla agentów; agents.defaults odpowiada za działanie pętli agenta; wpisy poszczególnych agentów mogą nadpisywać oba rodzaje ustawień tam, gdzie jest to obsługiwane.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Domyślne ustawienia agenta`},help:{"v1-1af7k5b-5a":`Wspólne ustawienia domyślne dziedziczone przez agentów, o ile nie zostaną nadpisane w poszczególnych wpisach w agents.entries. Używaj ustawień domyślnych, aby zapewnić spójne podstawowe działanie i ograniczyć powielanie konfiguracji poszczególnych agentów.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Cel dziedziczenia uwierzytelniania`},help:{"v1-2d16wl-2x":`Właściciel dziedziczonego magazynu poświadczeń zapewniający zgodność podczas aktualizacji, dopóki poświadczenia nie zostaną przeniesione do magazynów poszczególnych agentów.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Właściciel dziedziczenia uwierzytelniania`},help:{"v1-1a1s7nm-4s":`Agent, którego dotychczasowy magazyn poświadczeń pozostaje źródłem dziedziczenia po wycofaniu znacznika domyślnego. Zapisywany automatycznie podczas aktualizacji, jeśli poprzednim właścicielem nie był main.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Maksymalna liczba znaków pliku inicjalizacyjnego`},help:{"v1-drlo3i-37":`Maksymalna liczba znaków każdego pliku inicjalizacyjnego obszaru roboczego wstawianego do promptu systemowego przed przycięciem (domyślnie: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Maksymalna łączna liczba znaków plików inicjalizacyjnych`},help:{"v1-1evwsjb-2c":`Maksymalna łączna liczba znaków we wszystkich wstawianych plikach inicjalizacyjnych obszaru roboczego (domyślnie: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Kompaktowanie`},help:{"v1-1qxdwz8-5p":`Działanie kompaktowania, gdy kontekst zbliża się do limitu tokenów, w tym strategia i sposób zapisywania pamięci przed kompaktowaniem. Używaj tego ustawienia, gdy długotrwałe sesje wymagają stabilnej ciągłości przy małych oknach kontekstu.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Wbudowane automatyczne kompaktowanie`},help:{"v1-1et7vwu-5l":`Włącz wbudowaną proaktywną automatyczną kompaktację (domyślnie: true). Ustaw false, aby zatrzymać wbudowaną kompaktację uruchamianą po przekroczeniu progu, zachowując odzyskiwanie po przepełnieniu w OpenClaw, kompaktację wstępną i ręczne polecenie /compact.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Zasady zachowywania identyfikatorów podczas kompaktacji`},help:{"v1-hby01l-4l":`Zasady zachowywania identyfikatorów w podsumowaniach kompaktacji: "strict" dodaje na początku wbudowane wskazówki dotyczące zachowywania nieprzezroczystych identyfikatorów (domyślnie), a "off" wyłącza ten prefiks.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Zachowywanie ostatnich tokenów podczas kompaktacji`},help:{"v1-tgysub-5h":`Minimalny budżet tokenów zachowywanych z najnowszego okna rozmowy podczas kompaktacji. Użyj wyższych wartości, aby chronić ciągłość bieżącego kontekstu, lub niższych, aby zachować więcej starszej historii.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Próg rozmiaru aktywnego transkryptu dla kompaktacji`},help:{"v1-u715n1-90":`Próg w bajtach uruchamiający standardową wstępną kompaktację lokalną, gdy okno transkryptu widoczne dla modelu (od ostatniej kompaktacji lub resetu) osiągnie ten rozmiar (bajty lub ciągi takie jak "20mb"). Ustaw 0 lub pozostaw bez wartości, aby wyłączyć. Ogranicza również rozmiar natywnych transkryptów przebiegu w Codex app-server; zbyt duże natywne wątki są uruchamiane od nowa.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Utrwalanie pamięci przed kompaktacją`},help:{"v1-18q0ve9-55":`Ustawienia utrwalania pamięci przed kompaktacją, które uruchamiają zapis pamięci przez agenta przed intensywną kompaktacją. Pozostaw włączone w przypadku długich sesji, aby istotny kontekst został utrwalony przed agresywnym przycinaniem.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Zapis pamięci przed kompaktowaniem włączony`},help:{"v1-9xllgp-5o":`Włącza zapis pamięci przed kompaktowaniem, zanim środowisko wykonawcze przeprowadzi intensywniejszą redukcję historii po zbliżeniu się do limitów tokenów. Pozostaw tę opcję włączoną, chyba że celowo wyłączasz operacje zapisu pamięci w środowiskach z ograniczonymi zasobami.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Próg rozmiaru transkrypcji dla zapisu pamięci przed kompaktowaniem`},help:{"v1-1rzov1e-93":`Wymusza zapis pamięci przed kompaktowaniem, gdy okno transkrypcji widoczne dla modelu osiągnie ten próg (w bajtach lub jako ciąg znaków, np. "2mb"). Po kompaktowaniu obejmuje ono zachowaną końcówkę i kolejne tury, a nie odrzuconą historię. Użyj tej opcji, aby zapobiec zawieszaniu się długich sesji nawet wtedy, gdy liczniki tokenów są nieaktualne. Ustaw 0, aby wyłączyć.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Zastąpienie modelu dla zapisu pamięci przed kompaktowaniem`},help:{"v1-1r3ctyu-7w":`Opcjonalne zastąpienie dostawcy/modelu używane wyłącznie w turach zapisu pamięci przed kompaktowaniem. Ustaw lokalny model, np. ollama/qwen3:8b, jeśli wyodrębnianie informacji do trwałej pamięci nie powinno korzystać z płatnego modelu aktywnej sesji. Używany jest dokładnie wskazany model, bez dziedziczenia łańcucha modeli zapasowych aktywnego modelu.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Miękki próg zapisu pamięci przed kompaktowaniem`},help:{"v1-1dqo2l1-5c":`Progowa odległość od kompaktowania (w tokenach), która uruchamia zapis pamięci przed kompaktowaniem. Ustaw próg z większym wyprzedzeniem, aby zwiększyć bezpieczeństwo utrwalania danych, lub bliżej kompaktowania, aby zmniejszyć częstotliwość zapisu.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Wstępna kontrola kompaktowania w trakcie tury`},help:{"v1-am6gbh-6x":`Opcjonalna wstępna kontrola we wbudowanej pętli narzędzi OpenClaw, która wykrywa zbliżanie się do limitu kontekstu po dołączeniu wyniku narzędzia, a przed kolejnym wywołaniem modelu. Po jej włączeniu OpenClaw wykorzystuje istniejące mechanizmy naprawcze kontroli wstępnej do obcięcia wyników narzędzi lub skompaktowania kontekstu przed ponowną próbą.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Włącz wstępną kontrolę kompaktowania w trakcie tury`},help:{"v1-engbwe-5u":`Włącz ustrukturyzowane kontrole zbliżania się do limitu kontekstu w trakcie tury we wbudowanych pętlach narzędzi OpenClaw. Domyślnie: false. Pozostaw wyłączone, chyba że długie sesje intensywnie korzystające z narzędzi przekraczają limit kontekstu, zanim uruchomi się standardowe kompaktowanie na końcu tury.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Tryb kompaktowania`},help:{"v1-1unahwc-76":`Tryb strategii kompaktowania: "safeguard" (stosowany domyślnie, gdy nie ustawiono wartości) używa zabezpieczeń, aby zachować najnowszy kontekst, natomiast "default" stosuje podstawowe podsumowywanie bez tych zabezpieczeń. Ustaw "default" tylko wtedy, gdy podsumowywanie w trybie safeguard powoduje problemy u Twojego dostawcy.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Nadpisanie modelu do kompaktowania`},help:{"v1-cfeys9-6q":`Opcjonalny identyfikator dostawcy/modelu lub skonfigurowany samodzielny alias używany wyłącznie do podsumowywania podczas kompaktowania. Samodzielne aliasy są rozpoznawane przed wysłaniem żądania; skonfigurowany dosłowny identyfikator modelu ma pierwszeństwo w przypadku konfliktu z aliasem. Pozostaw nieustawione, aby nadal używać głównego modelu agenta.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Powiadamiaj użytkownika o kompaktowaniu`},help:{"v1-lvymm8-bv":`Po włączeniu wysyła użytkownikowi krótkie powiadomienia o utrzymaniu kontekstu: gdy kompaktowanie się rozpoczyna i kończy (na przykład „🧹 Kompaktowanie kontekstu...” i „🧹 Kompaktowanie zakończone”) oraz gdy wyczerpią się próby zapisania pamięci przed kompaktowaniem, przez co generowanie odpowiedzi jest kontynuowane w trybie ograniczonym (na przykład „⚠️ Utrzymanie pamięci chwilowo się nie powiodło; kontynuuję odpowiedź.”). Domyślnie wyłączone, aby utrzymanie kontekstu odbywało się cicho i nie zakłócało pracy.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Sekcje kontekstu po kompaktowaniu`},help:{"v1-1n0ln2u-5f":`Nazwy opcjonalnych sekcji H2/H3 w AGENTS.md, które mają być ponownie wstawiane po kompaktowaniu. Pozostaw nieustawione lub ustaw [], aby wyłączyć ponowne wstawianie. Ustaw jawnie ["Session Startup", "Red Lines"], aby włączyć dawną domyślną parę.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Synchronizacja indeksu po kompaktowaniu`},help:{"v1-ekpjeq-6l":`Określa tryb ponownego indeksowania pamięci sesji po kompaktowaniu: "off", "async" lub "await" (domyślnie: "async"). Użyj "await", aby zapewnić największą aktualność, "async", aby zmniejszyć opóźnienie kompaktowania, a "off" tylko wtedy, gdy synchronizacja pamięci sesji jest obsługiwana w innym miejscu.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Dostawca kompaktowania`},help:{"v1-kiwk91-86":`Identyfikator zarejestrowanej wtyczki dostawcy kompaktowania używanej do tworzenia podsumowań. Gdy jest ustawiony, a dostawca jest zarejestrowany, wywoływana jest jego metoda summarize() zamiast wbudowanego potoku summarizeInStages. W razie awarii dostawcy używany jest mechanizm wbudowany. Pozostaw nieustawione, aby korzystać z domyślnego wbudowanego mechanizmu podsumowywania.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Kontrola jakości kompaktowania`},help:{"v1-u9ognp-4k":`Ustawienia ponownych prób audytu jakości podsumowań kompakcji w trybie safeguard. W trybie safeguard ta funkcja jest domyślnie włączona; ustaw enabled: false, aby pominąć audyty podsumowań i ich ponowne generowanie.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Włączona kontrola jakości kompakcji`},help:{"v1-1xk2vt3-36":`Włącza audyty jakości podsumowań i ponowne próby generowania w kompakcji w trybie safeguard. Domyślnie: true w trybie safeguard.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Maksymalna liczba ponownych prób kontroli jakości kompakcji`},help:{"v1-n7l46y-3y":`Maksymalna liczba ponownych prób generowania po nieudanym audycie jakości podsumowania w trybie safeguard. Używaj małych wartości, aby ograniczyć dodatkowe opóźnienia i koszty tokenów.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Zachowywanie ostatnich tur podczas kompakcji`},help:{"v1-y34ihi-5k":`Liczba ostatnich tur użytkownika/asystenta zachowywanych dosłownie, bez uwzględniania ich w podsumowaniu w trybie safeguard (domyślnie: 3). Zwiększ tę wartość, aby zachować dokładny kontekst ostatniej rozmowy, lub zmniejsz ją, aby zmaksymalizować oszczędności wynikające z kompakcji.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Poziom rozumowania podczas kompakcji`},help:{"v1-1vafgaw-g1":`Poziom rozumowania używany wyłącznie do podsumowań w ramach wbudowanej kompaktacji OpenClaw: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" lub "inherit". Domyślnie używana jest preferencja dostawcy dotycząca kompaktacji, a w razie jej braku — "low"; natywna lokalna integracja Ollama preferuje "off". Ustaw "inherit", aby użyć poziomu sesji. Jawne ustawienia zastępują wartości domyślne dostawcy, a wybrany poziom jest ograniczany do zakresu obsługiwanego przez faktyczny model i środowisko wykonawcze kompaktacji. Natywna kompaktacja Codex app-server ignoruje to ustawienie, ponieważ jej żądanie kompaktacji nie pozwala na nadpisanie poziomu rozumowania dla pojedynczej operacji; OpenClaw zapisuje wtedy ostrzeżenie w dzienniku.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Limit czasu kompaktacji (sekundy)`},help:{"v1-2bhn29-7m":`Przedział czasu bezpieczeństwa w sekundach dla każdego żądania do modelu w ramach wbudowanej kompaktacji (domyślnie: 180). Kompaktacja wieloetapowa odnawia ten przedział przy rozpoczęciu każdego kolejnego żądania, więc cały proces może trwać dłużej; kompaktacja obsługiwana przez wtyczkę otrzymuje jeden przedział na całą operację.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Wstawianie kontekstu`},help:{"v1-u18x0-7u":`Steruje dołączaniem plików inicjalizacyjnych obszaru roboczego we wbudowanym środowisku wykonawczym: "always" stosuje standardowe dołączanie (domyślnie), "continuation-skip" pomija kwalifikujące się tury kontynuacji po zarejestrowanej turze z pełną inicjalizacją, a "never" wyłącza dołączanie. Nie steruje przygotowaniem promptów za pośrednictwem CLI.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Domyślne limity kontekstu`},help:{"v1-1coeez8-5d":`Domyślne limity budżetu kontekstu każdego agenta dla wybranych obszernych fragmentów i wstawianych bloków promptu. Pozwalają dostosować ograniczone rozmiary odczytu i wstawiania bez ponownego udostępniania ścieżek wywołań bez limitów.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Domyślna maksymalna liczba znaków memory_get`},help:{"v1-1qb40qv-4v":`Domyślna maksymalna liczba znaków zwracanych przez memory_get przed dodaniem metadanych obcięcia i informacji o kontynuacji. Zwiększ tę wartość, aby uzyskać fragmenty o długości zbliżonej do wcześniejszych, dłuższych fragmentów, ale zachowaj rozsądny limit.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Domyślna maksymalna liczba znaków po kompaktowaniu`},help:{"v1-64qo8g-5r":`Domyślna maksymalna liczba znaków z AGENTS.md zachowywanych przy wstawianiu odświeżonego kontekstu po kompaktowaniu. Zmniejsz tę wartość, aby obniżyć koszt odtwarzania po kompaktowaniu, lub zwiększ ją dla agentów wymagających dłuższych instrukcji początkowych.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Katalog roboczy`},help:{"v1-1y8wlxn-6a":`Katalog roboczy używany podczas generowania odpowiedzi agenta, niezależny od plików inicjalizacji obszaru roboczego i pamięci. Pierwszeństwo mają cwd konkretnego agenta oraz cwd ustawiony przy uruchamianiu sesji. Obsługuje ~ i ścieżki względne; odrębny cwd wymaga uruchomienia poza piaskownicą.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Model decyzyjny`},help:{"v1-7nd7ze-64":`Opcjonalny dostawca/model do wyborów o określonym typie, ocen i prawdopodobieństw wartości logicznych. Brak ustawienia lub pusta wartość wyłącza wywołania decyzyjne. Obsługujące tę funkcję wtyczki wysyłają do tego dostawcy ograniczony zestaw danych zadania stanowiących podstawę decyzji; modele czatu i modele pomocnicze pozostają bez zmian.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`Wbudowany OpenClaw`},help:{"v1-1keek32-3k":`Ustawienia zwiększające bezpieczeństwo wbudowanego mechanizmu uruchamiania OpenClaw, określające sposób uznawania za zaufane i stosowania lokalnych ustawień agenta z obszaru roboczego w sesjach OpenClaw.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Przełączanie awaryjne przy odmowach wynikających z zasad cyberbezpieczeństwa`},help:{"v1-xvv6wl-2r":`Automatyczna eskalacja do Daybreak w przypadku odmów OpenAI wynikających z zasad cyberbezpieczeństwa, dla których ponowienie jest bezpieczne, we wbudowanym środowisku wykonawczym.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Okres oczekiwania przełączania awaryjnego przy odmowach wynikających z zasad cyberbezpieczeństwa`},help:{"v1-16smtrl-25":`Czas pomijania niedostępnego celu eskalacji w bieżącej sesji.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Tryb przełączania awaryjnego przy odmowach wynikających z zasad cyberbezpieczeństwa`},help:{"v1-rzsd2b-2h":`Włącz automatyczną eskalację ("auto", domyślnie) lub pozostaw odmowy dostawcy jako ostateczne ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Model przełączania awaryjnego przy odmowach wynikających z zasad cyberbezpieczeństwa`},help:{"v1-1aaj8nn-1t":`Docelowy dostawca/model używany do automatycznej eskalacji w przypadku odmów wynikających z zasad cyberbezpieczeństwa.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Kontrakt wykonywania wbudowanego OpenClaw`},help:{"v1-1fch2ig-66":`Kontrakt wykonywania wbudowanego OpenClaw: "default" zachowuje standardowe działanie mechanizmu uruchamiania, a "strict-agentic" włącza ustrukturyzowane śledzenie planu i niewidoczne dla użytkownika odtwarzanie tur podczas obsługiwanych uruchomień modeli z rodziny GPT-5 w OpenAI/OpenAI Codex.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Zasady ustawień projektu wbudowanego OpenClaw`},help:{"v1-fdyy04-65":'Sposób, w jaki osadzony OpenClaw obsługuje plik `.openclaw/settings.json` w lokalnym obszarze roboczym: "sanitize" (domyślnie) usuwa shellPath/shellCommandPrefix, "ignore" całkowicie wyłącza ustawienia projektu, a "trusted" stosuje ustawienia projektu bez zmian.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Eksperymentalne flagi agenta`},help:{"v1-cvv5cl-2w":`Eksperymentalne flagi domyślne agenta. Pozostaw je wyłączone, chyba że świadomie testujesz funkcje w wersji zapoznawczej.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Włącz uproszczony tryb modelu lokalnego (eksperymentalny)`},help:{"v1-gj06u6-7b":`Zaawansowane ustawienie diagnostyczne ograniczające opcjonalne narzędzia, takie jak browser, automations i message. Domyślnie wyłączone; obsługiwane lokalne środowiska uruchomieniowe korzystają z automatycznego Tool Search bez tego ograniczenia. Jawne zezwolenia na narzędzia i wymagane narzędzia do dostarczania wiadomości pozostają zachowane.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Domyślny tryb szybki agenta`},help:{"v1-zv4y98-2z":`Domyślna zasada trybu szybkiego dla pętli agenta ("auto", true lub false). Wpisy poszczególnych agentów ją zastępują.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Agent cyklicznych wywołań`},help:{"v1-1jynxej-3w":`Agent odpowiedzialny za cykliczne wywołania w tle, gdy nie istnieje konfiguracja takich wywołań dla poszczególnych agentów. Pozostaw nieustawione, aby zachować skonfigurowany routing domyślny.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Zasada dostarczania cyklicznych wywołań do czatów prywatnych`},help:{"v1-nhyxa9-41":`Określa, czy wyniki cyklicznych wywołań mogą być dostarczane do czatów bezpośrednich/prywatnych: "allow" (domyślnie) zezwala na dostarczanie do czatów prywatnych, a "block" blokuje wysyłanie do odbiorców bezpośrednich.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Limit czasu cyklu kontrolnego (sekundy)`},help:{"v1-1se21py-5f":`Maksymalny czas w sekundach na turę agenta w cyklu kontrolnym przed jej przerwaniem. Pozostaw bez wartości, aby użyć agents.defaults.timeoutSeconds, jeśli ustawiono tę opcję; w przeciwnym razie zostanie użyty interwał cyklu kontrolnego, nie większy niż 600 sekund.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Maksymalne opóźnienie naśladujące człowieka (ms)`},help:{"v1-vnmvli-1m":`Maksymalne opóźnienie w ms dla niestandardowego ustawienia humanDelay (domyślnie: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Minimalne opóźnienie naśladujące człowieka (ms)`},help:{"v1-5nrtr5-1l":`Minimalne opóźnienie w ms dla niestandardowego ustawienia humanDelay (domyślnie: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Tryb opóźnienia naśladującego człowieka`},help:{"v1-k7hyg3-1n":`Styl opóźnienia odpowiedzi wysyłanych w blokach ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Maksymalny wymiar obrazu (px)`},help:{"v1-vju8x-2u":`Maksymalna długość boku obrazu w pikselach podczas oczyszczania danych obrazów w transkrypcjach i wynikach narzędzi (domyślnie: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Modele zapasowe do obsługi obrazów`},help:{"v1-1kgx5i9-1b":`Uporządkowana lista modeli zapasowych do obsługi obrazów (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Model do obsługi obrazów`},help:{"v1-dstqyh-2c":`Opcjonalny model do obsługi obrazów (provider/model), używany, gdy model główny nie obsługuje obrazów wejściowych.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Jakość obrazu`},help:{"v1-1uyxc5s-6u":`Preferencja kompresji multimediów w narzędziu do obrazów: "auto" dostosowuje kompresję do limitów dostawcy/modelu i liczby obrazów, "efficient" oszczędza tokeny i bajty, "balanced" zachowuje obecny kompromis, a "high" zachowuje więcej szczegółów na zrzutach ekranu i obrazach dokumentów.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Zapasowe modele generowania obrazów`},help:{"v1-oljfk4-1m":`Zapasowe modele generowania obrazów w kolejności użycia (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Model generowania obrazów`},help:{"v1-g4yw0h-2o":`Opcjonalny model generowania obrazów (provider/model) używany przez współdzieloną funkcję generowania obrazów.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Limit czasu generowania obrazów (ms)`},help:{"v1-9yesfj-31":`Domyślny limit czasu żądania do dostawcy w milisekundach dla wywołań image_generate. Wartość timeoutMs ustawiona dla danego wywołania zastępuje ten limit.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Zapasowe modele generowania muzyki`},help:{"v1-wyg9xe-1m":`Zapasowe modele generowania muzyki w kolejności użycia (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Model generowania muzyki`},help:{"v1-xs1e2h-2o":`Opcjonalny model generowania muzyki (provider/model) używany przez współdzieloną funkcję generowania muzyki.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Zapasowe modele generowania wideo`},help:{"v1-wpbf1e-1m":`Uporządkowana lista modeli zapasowych do generowania wideo (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Model generowania wideo`},help:{"v1-hfmlbl-2o":`Opcjonalny model generowania wideo (provider/model) używany przez współdzieloną funkcję generowania wideo.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Limit czasu generowania wideo (ms)`},help:{"v1-1bqj80s-4i":`Domyślny limit czasu żądania do dostawcy w milisekundach dla wywołań video_generate. Parametr timeoutMs ustawiony dla danego wywołania ma pierwszeństwo przed tą wartością, a ta wartość ma pierwszeństwo przed ustawieniami domyślnymi dostawcy.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Modele zapasowe`},help:{"v1-t4djq2-24":`Uporządkowana lista modeli zapasowych (provider/model). Używane w razie awarii modelu głównego.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Model główny`},help:{"v1-1i8a1v4-v":`Model główny (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Zasady wyboru modeli`},help:{"v1-z0txb7-2e":`Jawne zasady zmiany modelu. Pomiń je lub pozostaw allow puste, aby zezwolić na dowolny model.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Dozwolone modele`},help:{"v1-1fqace-3x":`Dozwolone identyfikatory przy zmianie modelu. Akceptuje aliasy, pełne identyfikatory „provider/model” oraz wzorce dostawców, takie jak „openai/*”. Pusta lista zezwala na dowolny model.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Modele`},help:{"v1-13cvq23-4i":`Skonfigurowany katalog modeli i ustawienia poszczególnych modeli. Wpisy zawierają aliasy, parametry, metadane środowiska wykonawczego i ustawienia nadpisujące trybu kodu; nie ograniczają możliwości zmiany modelu.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Środowisko wykonawcze modelu domyślnego agenta`},help:{"v1-6km9kx-41":`Opcjonalna polityka środowiska wykonawczego dla poszczególnych modeli domyślnego agenta. Użyj jej do definiowania wyjątków dla konkretnych modeli zamiast ustawiania środowiska wykonawczego dla całego agenta.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`Identyfikator środowiska wykonawczego modelu domyślnego agenta`},help:{"v1-1co96w7-4a":`Identyfikator środowiska wykonawczego modelu domyślnego agenta: "openclaw", "auto", zarejestrowany identyfikator warstwy wykonawczej wtyczki, np. "codex", lub obsługiwany alias backendu CLI, np. "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Tryb kodu`},help:{"v1-rsdl5o-6x":`Tryb kodu OpenClaw dla tej konkretnej pary dostawca/model: Włączony wymusza jego włączenie, Wyłączony go wyłącza, a Domyślny dziedziczy ustawienie tools.codeMode.enabled. Ustawienia aktywacji dla konkretnego agenta mają pierwszeństwo. Nie zmienia to wybranego środowiska wykonawczego ani natywnego trybu kodu Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Zakres wyboru modelu`},help:{"v1-sj8owq-bl":`Zakres poleceń czatu i aktualizacji modelu sesji Gateway bez jawnie określonego zakresu: "session" (domyślnie) zmienia tylko bieżącą sesję, "agent" aktualizuje również model główny danego agenta, a "global" aktualizuje również współdzielony model rezerwowy agents.defaults.model. Jawne flagi zakresu mają pierwszeństwo; zapis zmian skonfigurowanych wartości domyślnych wymaga uprawnień właściciela lub administratora. Selektory wywołań zwrotnych Telegram i wbudowany lokalny interfejs TUI nadal działają wyłącznie w zakresie sesji.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Maksymalny rozmiar PDF (MB)`},help:{"v1-1uig1dr-1u":`Maksymalny rozmiar pliku PDF w megabajtach dla narzędzia PDF (domyślnie: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Maksymalna liczba stron PDF`},help:{"v1-11na7hp-1y":`Maksymalna liczba stron PDF do przetworzenia przez narzędzie PDF (domyślnie: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Zapasowe modele PDF`},help:{"v1-89ebd8-19":`Uporządkowana lista zapasowych modeli PDF (provider/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`Model PDF`},help:{"v1-2ktkxt-2y":`Opcjonalny model PDF (provider/model) dla narzędzia do analizy PDF. Domyślnie używany jest imageModel, a następnie model sesji.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Katalog główny repozytorium`},help:{"v1-j3sh74-2h":`Opcjonalny katalog główny repozytorium wyświetlany w wierszu informacji o środowisku wykonawczym w instrukcji systemowej (zastępuje automatyczne wykrywanie).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Zakres portów źródłowych CDP przeglądarki w piaskownicy`},help:{"v1-1jkowdc-2b":`Opcjonalna lista dozwolonych zakresów CIDR dla ruchu przychodzącego CDP na granicy kontenera (na przykład 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Sieć przeglądarki w piaskownicy`},help:{"v1-8m74ud-5w":`Sieć Docker dla kontenerów przeglądarki w piaskownicy (domyślnie: openclaw-sandbox-browser). Użyj dedykowanej sieci domyślnej lub niestandardowej sieci mostkowej; tryb "none" nie jest obsługiwany, ponieważ sterowanie przeglądarką wymaga opublikowanych portów CDP.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Zezwalaj na dołączanie do przestrzeni nazw kontenera Docker w piaskownicy`},help:{"v1-qm39de-4c":`NIEBEZPIECZNE awaryjne obejście zabezpieczeń, które zezwala na tryb sieci Docker container:<id> w piaskownicy. Powoduje dołączenie do przestrzeni nazw innego kontenera i osłabia izolację piaskownicy.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`Procesory GPU platformy Docker w piaskownicy`},help:{"v1-jj0yhw-4k":`Opcjonalna wartość udostępniania GPU w Docker przekazywana do --gpus, na przykład "all" lub "device=GPU-uuid". Wymaga zgodnego środowiska uruchomieniowego na hoście, takiego jak NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Cel starszego magazynu sesji`},help:{"v1-1xkej6i-2g":`Właściciel wycofanych rekordów main-agent i starszych magazynów sesji o stałej lokalizacji, zapewniający zgodność podczas aktualizacji.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Właściciel starszego magazynu sesji`},help:{"v1-ommm7e-5w":`Agent będący właścicielem wycofanych rekordów main-agent lub rekordów bez przypisanego zakresu w starszym magazynie sesji o stałej lokalizacji po wycofaniu znacznika domyślnego. Zapisywany automatycznie podczas aktualizacji, gdy poprzedni właściciel nie był agentem main ani jedynym agentem.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Opcjonalna domyślna lista dozwolonych umiejętności dziedziczona przez agentów, którzy nie mają ustawienia agents.entries.*.skills. Pomiń ją, aby nie ograniczać umiejętności, lub ustaw [], aby agenci dziedziczący nie mieli żadnych umiejętności. Pamiętaj, że jawne ustawienie agents.entries.*.skills zastępuje tę wartość domyślną, zamiast się z nią łączyć.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Pomiń tworzenie plików inicjalizacyjnych obszaru roboczego`},help:{"v1-kbstgw-5v":`Pomija automatyczne tworzenie plików inicjalizacyjnych obszaru roboczego, ale nie dołączanie istniejących plików. W przypadku wbudowanego środowiska wykonawczego ustaw agents.defaults.contextInjection na "never", aby wyłączyć dołączanie, chyba że ustawienie zostanie nadpisane dla konkretnego agenta.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Pomijane opcjonalne pliki inicjalizacyjne`},help:{"v1-1j2z4yj-4c":`Opcjonalne pliki inicjalizacyjne, które nie powinny być tworzone w obszarach roboczych agentów. Prawidłowe wartości: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md jest akceptowany, ale nie ma żadnego efektu).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Kontekst uruchomienia`},help:{"v1-1ugsihy-5o":`Wstęp do pierwszej tury, zarządzany przez środowisko wykonawcze, dla poleceń "/new" i "/reset" bez argumentów. Użyj tego ustawienia, aby określić, czy ostatnie dzienne pliki pamięci mają być wstępnie ładowane do pierwszego promptu, zamiast pozostawiać modelowi decyzję o tym, co odczytać.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Polecenia z kontekstem początkowym`},help:{"v1-wav4a5-36":`Określa, które polecenia resetowania bez argumentów otrzymują kontekst początkowy: uwzględnij "new", "reset" lub oba (domyślnie: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Liczba dni pamięci w kontekście początkowym`},help:{"v1-4i5xcm-3p":`Liczba datowanych plików pamięci do załadowania, licząc wstecz od dzisiaj w skonfigurowanej strefie czasowej użytkownika (domyślnie: 2, czyli dziś + wczoraj).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Włącz kontekst początkowy`},help:{"v1-1d5vz2u-4i":`Włącz wstęp z kontekstem początkowym przy resetowaniu sesji poleceniami bez argumentów (domyślnie: true). Wyłącz tę opcję, aby powrócić do działania opartego wyłącznie na prompcie, bez dziennej pamięci ładowanej przez środowisko wykonawcze.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Maksymalna liczba bajtów pliku w kontekście początkowym`},help:{"v1-11cbian-41":`Maksymalna dozwolona liczba bajtów na dzienny plik pamięci podczas tworzenia kontekstu początkowego (domyślnie: 16384). Pliki przekraczające ten limit bezpiecznego odczytu są pomijane.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Maksymalna liczba znaków pliku w kontekście początkowym`},help:{"v1-10z53s-2u":`Maksymalna liczba znaków zachowywanych z każdego załadowanego dziennego pliku pamięci we wstępie początkowym (domyślnie: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Maksymalna łączna liczba znaków kontekstu startowego`},help:{"v1-sf676u-54":`Maksymalna łączna liczba znaków zachowywanych ze wszystkich wczytanych dziennych plików pamięci we wstępie startowym (domyślnie: 2800). Po osiągnięciu tego limitu dodatkowe pliki są przycinane we wstępie.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Tryb delegowania do podagentów`},help:{"v1-pqewbk-5o":`Siła zalecenia delegowania do podagentów, określana wyłącznie w prompcie. Domyślnie "prefer" w głównej sesji każdego agenta i "suggest" w pozostałych; "prefer" zdecydowanie nakazuje agentowi delegowanie bardziej złożonych zadań przez sessions_spawn.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Cel agenta systemowego`},help:{"v1-1wwimo9-34":`Ustawienia docelowe dla wnioskowania agenta systemowego OpenClaw i Custodian działających w tle oraz wybranych odczytów operatora bez określonego zakresu.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Właściciel agenta systemowego`},help:{"v1-15rvt92-8c":`Agent, którego model i dane uwierzytelniające są używane do konsultacji agenta systemowego i Custodian działających w tle. Używany także wtedy, gdy models.list, models.authStatus, skills.status, doctor.memory.status lub polecenie CLI infer ustalające model lub stan uwierzytelniania należący do agenta pomija agentId lub --agent; agentId podany jawnie w żądaniu zawsze ma pierwszeństwo.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Interwał wskaźnika pisania (sekundy)`},help:{"v1-1y701ox-42":`Określa odstęp w sekundach między odświeżeniami podtrzymującymi wskaźnik pisania dla każdego agenta. Zwiększ tę wartość, aby zmniejszyć częstotliwość aktualizacji we wszystkich kanałach obsługujących wskaźnik pisania.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Tryb wskaźnika pisania`},help:{"v1-m2hvpw-3m":`Określa, kiedy agenci zaczynają sygnalizować pisanie: "never", "instant", "thinking" lub "message". Ustawienie typingMode dla konkretnego agenta zastępuje tę wartość domyślną.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Model pomocniczy`},help:{"v1-1wg7h1a-7s":`Opcjonalny tańszy model (provider/model lub alias) do krótkich zadań wewnętrznych, takich jak generowanie tytułów i opisywanie postępu. Jeśli nie ustawiono wartości, używany jest mały model zadeklarowany przez głównego dostawcę, o ile jest dostępny (w przeciwnym razie model główny). Ustaw pusty ciąg znaków, aby wyłączyć kierowanie zadań do modelu pomocniczego.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Zapasowe modele głosowe`},help:{"v1-faazv4-1b":`Zapasowe modele głosowe w kolejności użycia (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Model głosowy`},help:{"v1-1yeh3h4-2t":`Opcjonalny model głosowy (provider/model) używany przez funkcje mowy, transkrypcji i komunikacji głosowej w czasie rzeczywistym.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Limit czasu operacji głosowych (ms)`},help:{"v1-1sbergs-32":`Domyślny limit czasu żądania do dostawcy w milisekundach dla operacji modelu głosowego, gdy wywołujący obsługuje limity czasu.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Obszar roboczy`},help:{"v1-1lssx8l-5w":`Domyślny obszar roboczy agenta na pliki inicjalizacyjne i pliki pamięci. Używany również jako katalog roboczy, gdy agents.defaults.cwd nie jest ustawione. Ustaw tę wartość jawnie podczas uruchamiania przez skrypty opakowujące, aby rozwiązywanie ścieżek pozostawało deterministyczne.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Lista agentów`},help:{"v1-yurood-5l":`Jawna lista skonfigurowanych agentów z identyfikatorami i opcjonalnymi nadpisaniami ustawień modelu, narzędzi, tożsamości oraz obszaru roboczego. Zachowuj stałe identyfikatory, aby powiązania, zatwierdzenia i kierowanie sesji pozostawały deterministyczne.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Starsze środowisko wykonawcze agenta`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`Identyfikator starszego środowiska wykonawczego agenta`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Maksymalna liczba znaków w pliku inicjalizacyjnym agenta`},help:{"v1-rsf1es-4j":`Nadpisanie dla danego agenta maksymalnej liczby znaków każdego pliku inicjalizacyjnego obszaru roboczego wstawianego do jego promptu systemowego. Pomiń, aby odziedziczyć agents.defaults.bootstrapMaxChars.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Maksymalna łączna liczba znaków w plikach inicjalizacyjnych agenta`},help:{"v1-1bal68p-4y":`Nadpisanie dla danego agenta maksymalnej łącznej liczby znaków we wszystkich plikach inicjalizacyjnych obszaru roboczego wstawianych do jego promptu systemowego. Pomiń, aby odziedziczyć agents.defaults.bootstrapTotalMaxChars.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Wstawianie kontekstu agenta`},help:{"v1-1j68ys8-50":`Ustawienie wstrzykiwania plików inicjalizacyjnych obszaru roboczego w osadzonym środowisku wykonawczym, nadpisywane dla konkretnego agenta. Pomiń, aby odziedziczyć agents.defaults.contextInjection. Nie steruje przygotowywaniem promptów za pośrednictwem CLI.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Limity kontekstu agenta`},help:{"v1-f1qxq8-3c":`Opcjonalne nadpisania dla danego agenta wybranych ustawień budżetu kontekstu. Pominięte pola dziedziczą wartości z agents.defaults.contextLimits.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Maksymalna liczba znaków memory_get agenta`},help:{"v1-12hlmsv-1v":`Nadpisanie dla danego agenta domyślnego maksymalnego budżetu znaków memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Maksymalna liczba znaków agenta po kompaktowaniu`},help:{"v1-15s0npd-1w":`Nadpisanie limitu długości fragmentu AGENTS.md po kompaktowaniu dla danego agenta.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Katalog roboczy agenta`},help:{"v1-mv43ak-6a":`Katalog roboczy używany podczas generowania odpowiedzi przez tego agenta. Nadpisuje agents.defaults.cwd, ale nie cwd ustawiony przy tworzeniu sesji; pliki inicjalizacyjne i pliki pamięci pozostają w obszarze roboczym. Obsługuje ~ i ścieżki względne; odrębny cwd wymaga uruchomienia poza piaskownicą.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Model decyzyjny agenta`},help:{"v1-1mih8bf-3j":`Model decyzyjny dla konkretnego agenta. Brak ustawienia powoduje dziedziczenie agents.defaults.decisionModel; pusty ciąg znaków wyłącza wywołania decyzyjne dla tego agenta.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`Wbudowany OpenClaw agenta`},help:{"v1-uoomza-4b":`Opcjonalne nadpisania ustawień wbudowanego OpenClaw dla danego agenta. Pozwalają włączyć bardziej rygorystyczne zachowanie wykonawcze GPT-5 dla wybranych agentów bez zmiany globalnego ustawienia domyślnego.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Kontrakt wykonania wbudowanego OpenClaw agenta`},help:{"v1-1d1jaoi-7k":`Opcjonalne nadpisanie kontraktu wykonania wbudowanego OpenClaw dla danego agenta. Ustaw "strict-agentic", aby włączyć ustrukturyzowane śledzenie planu i niewidoczne dla użytkownika odzyskiwanie tur dla tego agenta podczas obsługiwanych uruchomień modeli z rodziny GPT-5 w OpenAI/OpenAI Codex, lub "default", aby dziedziczyć standardowe zachowanie mechanizmu wykonawczego.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Flagi eksperymentalne agenta`},help:{"v1-1r06jov-2a":`Flagi eksperymentalne dla danego agenta. Pominięte pola dziedziczą wartości z agents.defaults.experimental.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Tryb uproszczony modelu lokalnego agenta`},help:{"v1-5o3tgx-58":`Ustawienie diagnostyczne uproszczonego trybu modelu lokalnego dla poszczególnych agentów. Włączaj je tylko wtedy, gdy ograniczenie opcjonalnych narzędzi rozwiązuje potwierdzony problem z modelem, bez ograniczania narzędzi wszystkim agentom.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Domyślny tryb szybki agenta`},help:{"v1-1ujydjc-3o":`Opcjonalne ustawienie domyślne trybu szybkiego dla agenta ("auto", true lub false). Obowiązuje, gdy tryb szybki nie został nadpisany dla wiadomości ani sesji.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Zasady bezpośredniego dostarczania sygnałów aktywności`},help:{"v1-11gl9l0-41":`Nadpisanie zasad dostarczania sygnałów aktywności bezpośrednio lub w wiadomościach prywatnych dla danego agenta; użyj "block" dla agentów, którzy powinni wysyłać alerty aktywności wyłącznie do miejsc docelowych innych niż wiadomości prywatne.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Limit czasu sygnału aktywności (sekundy)`},help:{"v1-kdetv4-6s":`Maksymalny czas w sekundach na turę agenta obsługującą sygnał aktywności, po którym zostanie ona przerwana. Ustawiany osobno dla każdego agenta. Pozostaw nieustawione, aby odziedziczyć limit czasu z połączonej konfiguracji sygnałów aktywności, następnie wartość agents.defaults.timeoutSeconds, jeśli jest ustawiona, a w przeciwnym razie interwał sygnałów aktywności ograniczony do 600 sekund.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Awatar tożsamości`},help:{"v1-pzp9gr-1t":`Awatar agenta (ścieżka względem obszaru roboczego, adres URL http(s) lub identyfikator URI danych).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Zasady wyboru modelu agenta`},help:{"v1-17d5je8-2r":`Zasady nadpisywania modelu dla danego agenta. Jawna lista dozwolonych modeli zastępuje domyślne zasady dla tego agenta.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Dozwolone modele agenta`},help:{"v1-v1ueke-5b":`Dozwolone odwołania do modeli używanych do nadpisania modelu tego agenta. Akceptuje aliasy, pełne odwołania "provider/model" oraz wzorce prefiksów zakończone symbolem wieloznacznym, takie jak "provider/*" lub "provider/namespace/*"; pusta lista zezwala na dowolny model.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Nadpisania modeli agenta`},help:{"v1-nld1vq-1v":`Nadpisania katalogu modeli dla poszczególnych agentów, indeksowane pełnymi identyfikatorami dostawcy/modelu.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Środowisko wykonawcze modelu agenta`},help:{"v1-7b59y-3s":`Opcjonalna polityka środowiska wykonawczego dla poszczególnych modeli tego agenta. Użyj jej do definiowania wyjątków modeli specyficznych dla agenta zamiast ustawiania środowiska wykonawczego dla całego agenta.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`Identyfikator środowiska wykonawczego modelu agenta`},help:{"v1-1ckfc39-46":`Identyfikator środowiska wykonawczego modelu dla danego agenta: "openclaw", "auto", zarejestrowany identyfikator warstwy wykonawczej wtyczki, np. "codex", lub obsługiwany alias backendu CLI, np. "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Tryb kodu`},help:{"v1-91zu7f-7m":`Tryb kodu OpenClaw dla tego agenta i konkretnego dostawcy/modelu: Włączony wymusza jego włączenie, Wyłączony go wyłącza, a Domyślny dziedziczy ustawienie aktywacji agenta, następnie wspólne nadpisanie modelu, a na końcu tools.codeMode.enabled. Nie zmienia to wybranego środowiska wykonawczego ani natywnego trybu kodu Codex.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Domyślna widoczność rozumowania agenta`},help:{"v1-13ly0xf-3m":`Opcjonalna domyślna widoczność rozumowania dla danego agenta (on|off|stream). Obowiązuje, gdy nie ustawiono nadpisania rozumowania dla wiadomości ani sesji.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Środowisko wykonawcze agenta`},help:{"v1-avjgkf-3l":`Opcjonalny deskryptor środowiska wykonawczego tego agenta. Użyj embedded do domyślnego wykonywania w OpenClaw lub acp do ustawień domyślnych zewnętrznej warstwy wykonawczej ACP.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Środowisko wykonawcze ACP agenta`},help:{"v1-91zvdk-3i":`Domyślne ustawienia środowiska uruchomieniowego ACP dla tego agenta, gdy runtime.type=acp. Ustawienia ACP na poziomie powiązania nadal mają pierwszeństwo w poszczególnych rozmowach.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Agent warstwy wykonawczej ACP dla agenta`},help:{"v1-1pm98vp-37":`Opcjonalny identyfikator agenta warstwy wykonawczej ACP używanego przez tego agenta OpenClaw (na przykład codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Backend ACP agenta`},help:{"v1-1u3cdsg-2n":`Opcjonalne nadpisanie backendu ACP dla sesji ACP tego agenta (domyślnie używane jest globalne ustawienie acp.backend).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Katalog roboczy ACP agenta`},help:{"v1-d9p9rf-1t":`Opcjonalny domyślny katalog roboczy dla sesji ACP tego agenta.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Tryb ACP agenta`},help:{"v1-yatuk4-21":`Opcjonalny domyślny tryb sesji ACP dla tego agenta (persistent lub oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Typ środowiska uruchomieniowego agenta`},help:{"v1-139fbk6-2r":`Typ środowiska uruchomieniowego tego agenta: "embedded" (domyślne środowisko uruchomieniowe OpenClaw) lub "acp" (domyślne ustawienia warstwy wykonawczej ACP).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Zakres adresów źródłowych CDP przeglądarki w piaskownicy agenta`},help:{"v1-1q1qyso-1d":`Nadpisanie listy dozwolonych źródłowych zakresów CIDR dla CDP na poziomie agenta.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Sieć przeglądarki w piaskownicy agenta`},help:{"v1-13bdfww-4c":`Nadpisanie sieci Docker przeglądarki w piaskownicy dla konkretnego agenta. Użyj sieci typu bridge; "none" nie jest obsługiwane, ponieważ sterowanie przeglądarką wymaga opublikowanych portów CDP.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Zezwalaj na dołączanie do przestrzeni nazw kontenera Docker w piaskownicy agenta`},help:{"v1-1xtnseb-2i":`NIEBEZPIECZNE nadpisanie ustawienia dołączania do przestrzeni nazw kontenera w trybie sieciowym Docker piaskownicy dla konkretnego agenta.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`Procesory GPU kontenerów Docker w piaskownicy agenta`},help:{"v1-1kek1n2-1t":`Nadpisanie ustawienia przekazywania GPU do kontenerów Docker w piaskownicy dla konkretnego agenta.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Filtr umiejętności agenta`},help:{"v1-igchue-6v":`Opcjonalna lista dozwolonych umiejętności dla tego agenta. Jeśli ją pominięto, agent dziedziczy agents.defaults.skills, o ile je ustawiono; w przeciwnym razie umiejętności pozostają nieograniczone. Ustaw [], aby wyłączyć wszystkie umiejętności. Jawnie podana lista całkowicie zastępuje odziedziczone ustawienia domyślne zamiast się z nimi łączyć.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Limity Skills agenta`},help:{"v1-1sv10v9-4y":`Opcjonalne nadpisania limitów podsystemu umiejętności dla konkretnego agenta. Użyj tej opcji, gdy agent potrzebuje innego limitu promptu umiejętności bez wprowadzania drugiej ogólnej ścieżki konfiguracji limitów kontekstu.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Maksymalna liczba znaków promptu Skills agenta`},help:{"v1-dys63y-52":`Nadpisanie limitu znaków promptu umiejętności dla danego agenta. Rozszerza istniejącą ścieżkę skills.limits.maxSkillsPromptChars zamiast przekazywać ten sam limit przez contextLimits.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Tryb delegowania do subagentów`},help:{"v1-1rkgh6p-4s":`Nadpisanie siły preferencji delegowania do subagentów dla danego agenta. Pomiń, aby używać "prefer" w głównej sesji tego agenta i "suggest" w pozostałych przypadkach; jawnie ustawione "prefer" lub "suggest" zawsze ma pierwszeństwo.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Domyślny poziom myślenia agenta`},help:{"v1-173q7vy-43":`Opcjonalny domyślny poziom myślenia dla danego agenta. Nadpisuje agents.defaults.thinkingDefault dla tego agenta, gdy nie ustawiono nadpisania dla wiadomości ani sesji.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Dodatki do listy dozwolonych narzędzi agenta`},help:{"v1-1550ui9-46":`Dodatkowa lista dozwolonych narzędzi dla danego agenta, rozszerzająca zasady globalne i zasady profilu. Ogranicz jej zakres, aby uniknąć przypadkowego rozszerzenia uprawnień wyspecjalizowanych agentów.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Zasady narzędzi agenta według dostawcy`},help:{"v1-mthxv9-4t":`Nadpisania zasad narzędzi dla danego agenta i dostawcy, umożliwiające kontrolę dostępnych funkcji w obrębie kanału. Użyj, gdy pojedynczy agent wymaga bardziej rygorystycznych ograniczeń u jednego dostawcy niż u pozostałych.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Tryb kodu agenta`},help:{"v1-118t8u5-65":`Opcje trybu kodu dla poszczególnych agentów. Jawne ustawienie enabled zastępuje domyślne ustawienia aktywacji wspólnego modelu i ustawienia globalne; pierwszeństwo ma nadpisanie codeMode modelu dla konkretnego agenta. Pozostałe opcje są scalane z tools.codeMode, nadpisując jego wartości bez zmiany aktywacji.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Limit czasu wykonywania agenta (sekundy)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Nadpisanie tożsamości GitHub CLI agenta`},help:{"v1-mjwdh4-38":`Pełne nadpisanie zarządzanej tożsamości GitHub CLI i autora Git dla tego agenta. Pomiń, aby odziedziczyć tożsamość systemową.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Adres e-mail autora Git agenta`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Nazwa autora Git agenta`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Typ poświadczeń GitHub agenta`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Wersja profilu GitHub agenta`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Lista dozwolonych działań na wiadomościach dla agenta`},help:{"v1-1g5gov3-67":`Lista dozwolonych działań na wiadomościach dla poszczególnych agentów w narzędziu message. Dla agentów publicznych działających w piaskownicy ustaw minimalną listę, taką jak ["send"], aby odczytywanie, edytowanie, usuwanie, reagowanie i inne działania na wiadomościach specyficzne dla dostawcy pozostały ukryte i zablokowane.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Przesyłanie wiadomości między kontekstami przez agenta (między dostawcami)`},help:{"v1-pehesn-49":`Nadpisanie ustawienia wysyłania między dostawcami dla konkretnego agenta. Dziedziczy ustawienie globalne (domyślnie: true). Ustaw false, aby zablokować temu agentowi wysyłanie wiadomości między dostawcami.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Wiadomości agenta między kontekstami (ten sam dostawca)`},help:{"v1-s9u09h-4t":`Zabezpieczenie wysyłania wiadomości do innych rozmów u tego samego dostawcy, ustawiane osobno dla każdego agenta. W przypadku publicznych agentów, którzy mają działać wyłącznie w bieżącej rozmowie, ustaw zarówno tę opcję, jak i allowAcrossProviders na false.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Profil narzędzi agenta`},help:{"v1-1du76ix-57":`Indywidualne ustawienie profilu narzędzi agenta, które zastępuje ustawienie domyślne, gdy agent potrzebuje innego podstawowego zestawu możliwości. Korzystaj z niego oszczędnie, aby różnice w zasadach między agentami pozostawały zamierzone i możliwe do zweryfikowania.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Rój agenta`},help:{"v1-420ljs-2c":`Indywidualne ustawienia roju dla agenta. Wartości są scalane z konfiguracją tools.swarm najwyższego poziomu i mają przed nią pierwszeństwo.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Tryb sygnalizowania pisania agenta`},help:{"v1-oxir52-2e":`Zastępuje domyślną zasadę rozpoczynania sygnalizowania pisania dla jednego agenta bez zmiany ustawień pozostałych agentów.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Model pomocniczy agenta`},help:{"v1-1v9oskz-2z":`Opcjonalne indywidualne ustawienie modelu pomocniczego agenta do krótkich zadań wewnętrznych. Zastępuje agents.defaults.utilityModel.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Generacja przypisania właścicieli agentów`},help:{"v1-m2hp61-8g":`Trwały znacznik generacji przypisania właścicieli w środowisku wielu agentów. "explicit" oznacza, że kanały działające w tle, heartbeat, konsultacje z agentem systemowym, Talk, cron oraz bezpośrednie operacje CLI muszą ustalić właściciela właściwego dla danego obszaru działania albo zostać zablokowane. OpenClaw ustawia ten znacznik automatycznie podczas tworzenia lub migracji floty; pomiń go w przypadku pojedynczego agenta.`}},approvals:{label:{"v1-1m405m7-9":`Zatwierdzenia`},help:{"v1-4y3in-5w":`Ustawienia routingu zatwierdzeń służące do przekazywania próśb o zatwierdzenie exec i wtyczek do miejsc docelowych czatu poza sesją źródłową. Pozostaw je wyłączone, chyba że operatorzy potrzebują wglądu w zatwierdzenia poza pierwotnym kanałem.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Przekazywanie zatwierdzeń exec`},help:{"v1-1r2mozk-5v":`Grupuje ustawienia przekazywania zatwierdzeń exec, w tym włączenie funkcji, tryb routingu, filtry i jawnie wskazane miejsca docelowe. Skonfiguruj je tutaj, gdy prośby o zatwierdzenie muszą trafiać do kanałów operacyjnych, a nie tylko do wątku źródłowego.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Filtr agentów dla zatwierdzeń`},help:{"v1-xbuhd3-5i":'Opcjonalna lista dozwolonych identyfikatorów agentów, których zatwierdzenia mogą być przekazywane, na przykład `["primary", "ops-agent"]`. Użyj jej, aby ograniczyć zasięg przekazywania i uniknąć wysyłania do kanałów powiadomień dotyczących niepowiązanych agentów.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Przekazuj zatwierdzenia exec`},help:{"v1-1t0whe8-5s":`Włącza przekazywanie próśb o zatwierdzenie exec do skonfigurowanych miejsc docelowych (domyślnie: false). Pozostaw wyłączone w konfiguracjach o niskim ryzyku i włączaj tylko wtedy, gdy osoby udzielające zatwierdzeń potrzebują próśb widocznych w kanałach.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Tryb przekazywania zatwierdzeń`},help:{"v1-1dedfo4-69":`Określa, gdzie wysyłane są prośby o zatwierdzenie: "session" używa czatu źródłowego, "targets" używa skonfigurowanych miejsc docelowych, a "both" wysyła obiema ścieżkami. Używaj "session" jako ustawienia podstawowego i rozszerzaj zakres tylko wtedy, gdy proces operacyjny wymaga nadmiarowości.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Filtr sesji dla zatwierdzeń`},help:{"v1-smeg8e-5u":'Opcjonalne filtry kluczy sesji dopasowywane jako podciągi lub wzorce w stylu wyrażeń regularnych, na przykład `["discord:", "^agent:ops:"]`. Używaj precyzyjnych wzorców, aby do współdzielonych miejsc docelowych przekazywane były tylko zamierzone konteksty zatwierdzania.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Cele przekazywania próśb o zatwierdzenie`},help:{"v1-17ah848-5u":`Jawnie określone cele dostarczania używane, gdy tryb przekazywania obejmuje cele. Każdy z nich zawiera szczegóły kanału i miejsca docelowego. Ograniczaj listy celów zgodnie z zasadą najmniejszych uprawnień i sprawdzaj każde miejsce docelowe przed włączeniem przekazywania na szeroką skalę.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`Identyfikator konta docelowego próśb o zatwierdzenie`},help:{"v1-16zopng-5e":`Opcjonalny selektor konta dla konfiguracji kanałów z wieloma kontami, gdy prośby o zatwierdzenie muszą być kierowane przez kontekst określonego konta. Używaj go tylko wtedy, gdy kanał docelowy ma wiele skonfigurowanych tożsamości.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Kanał docelowy próśb o zatwierdzenie`},help:{"v1-ji1igl-59":`Identyfikator kanału lub dostawcy używany do dostarczania przekazywanych próśb o zatwierdzenie, taki jak discord, slack lub identyfikator kanału wtyczki. Używaj wyłącznie prawidłowych identyfikatorów kanałów, aby nieznane trasy nie powodowały niepowodzeń dostarczania bez powiadomienia.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`Identyfikator wątku docelowego próśb o zatwierdzenie`},help:{"v1-1axynw7-59":`Opcjonalny wątek lub temat docelowy dla kanałów obsługujących dostarczanie przekazywanych próśb o zatwierdzenie do wątków. Używaj go, aby utrzymywać ruch związany z zatwierdzaniem w wątkach operacyjnych zamiast w kanałach głównych.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Miejsce docelowe próśb o zatwierdzenie`},help:{"v1-1ijng7e-5n":`Identyfikator miejsca docelowego w kanale docelowym (identyfikator kanału, identyfikator użytkownika lub początek wątku, zależnie od dostawcy). Sprawdź jego znaczenie u danego dostawcy, ponieważ format miejsca docelowego różni się w zależności od integracji kanału.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Przekazywanie próśb o zatwierdzenie wtyczek`},help:{"v1-1m6pzxv-6b":`Grupuje ustawienia przekazywania próśb o zatwierdzenie wtyczek, w tym włączanie, tryb kierowania, filtry i jawnie określone miejsca docelowe. Działa niezależnie od przekazywania próśb o zatwierdzenie wykonania. Skonfiguruj tutaj, gdy prośby o zatwierdzenie wtyczek mają trafiać do kanałów operacyjnych.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Filtr agentów dla zatwierdzeń wtyczek`},help:{"v1-jb1bra-4b":'Opcjonalna lista dozwolonych identyfikatorów agentów, dla których można przekazywać prośby o zatwierdzenie wtyczek, na przykład `["primary", "ops-agent"]`. Użyj jej, aby ograniczyć zakres przekazywania.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Przekazuj prośby o zatwierdzenie wtyczek`},help:{"v1-1ntctaf-3v":`Włącza przekazywanie próśb o zatwierdzenie wtyczek do skonfigurowanych miejsc docelowych (domyślnie: false). Działa niezależnie od approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Tryb przekazywania próśb o zatwierdzenie wtyczek`},help:{"v1-1h62vy4-3z":`Określa, dokąd wysyłane są prośby o zatwierdzenie wtyczek: "session" używa czatu źródłowego, "targets" używa skonfigurowanych miejsc docelowych, a "both" wysyła obiema ścieżkami.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Filtr sesji dla zatwierdzeń wtyczek`},help:{"v1-1eppxmt-57":'Opcjonalne filtry kluczy sesji dopasowywane jako podciągi lub wzorce wyrażeń regularnych, na przykład `["discord:", "^agent:ops:"]`. Używaj precyzyjnych wzorców, aby przekazywać prośby o zatwierdzenie tylko z zamierzonych kontekstów.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Cele przekazywania próśb o zatwierdzenie wtyczek`},help:{"v1-o92qze-3k":`Jawnie określone cele dostarczania używane, gdy tryb przekazywania próśb o zatwierdzenie wtyczek obejmuje cele. Każdy cel zawiera szczegóły kanału i miejsca docelowego.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`Identyfikator konta docelowego dla próśb o zatwierdzenie wtyczek`},help:{"v1-1wf3lqn-3j":`Opcjonalny selektor konta dla konfiguracji kanałów z wieloma kontami, gdy prośby o zatwierdzenie wtyczek muszą być kierowane przez określone konto.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Kanał docelowy dla próśb o zatwierdzenie wtyczek`},help:{"v1-1mzhzi9-34":`Identyfikator kanału lub dostawcy używany do dostarczania przekazywanych próśb o zatwierdzenie wtyczek, np. discord, slack lub identyfikator kanału wtyczki.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`Identyfikator wątku docelowego dla próśb o zatwierdzenie wtyczek`},help:{"v1-1scaw9c-2v":`Opcjonalny wątek lub temat docelowy dla kanałów obsługujących dostarczanie przekazywanych próśb o zatwierdzenie wtyczek w wątkach.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Miejsce docelowe dla próśb o zatwierdzenie wtyczek`},help:{"v1-sh5te1-31":`Identyfikator miejsca docelowego w kanale docelowym (identyfikator kanału, identyfikator użytkownika lub wiadomość początkowa wątku, zależnie od dostawcy).`}},attachments:{label:{"v1-8925gh-b":`Załączniki`},help:{"v1-1xvgkss-40":`Ogólne zasady przechowywania wspólne dla dostawców i narzędzi zapisujących multimedia. Użyj ttlHours, aby ograniczyć czas przechowywania tymczasowych multimediów przed ich usunięciem.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`Czas przechowywania załączników TTL (godziny)`},help:{"v1-1g90day-9e":`Opcjonalny okres przechowywania w godzinach dla zapisanych multimediów objętych ogólnym czyszczeniem na podstawie mtime. Pozostaw bez wartości, aby wyłączyć to czyszczenie, lub ustaw wartość taką jak 24 (1 dzień) albo 168 (7 dni), aby okresowo usuwać starsze multimedia z obszaru tymczasowego. Zarządzane multimedia wychodzące (załączniki generowane na czacie) są wyłączone z tego mechanizmu i podlegają własnym zasadom przechowywania uwzględniającym SQLite oraz transkrypcje.`}},audio:{label:{"v1-11wczsp-5":`Dźwięk`}},auth:{label:{"v1-5xz433-4":`Uwierzytelnianie`},help:{"v1-1eu3aud-5c":`Główna sekcja profili uwierzytelniania służąca do obsługi danych uwierzytelniających dostawców w wielu profilach oraz kolejności przełączania awaryjnego opartej na okresach oczekiwania. Utrzymuj minimalną i jednoznaczną konfigurację profili, aby można było kontrolować działanie automatycznego przełączania awaryjnego.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Kolejność profili uwierzytelniania`},help:{"v1-1x6kknp-1w":`Uporządkowane identyfikatory profili uwierzytelniania dla każdego dostawcy (używane do automatycznego przełączania awaryjnego).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Profile uwierzytelniania`},help:{"v1-kzoqcn-1j":`Nazwane profile uwierzytelniania (dostawca + tryb + opcjonalny adres e-mail).`}},bindings:{label:{"v1-1hcih9f-8":`Przypisania`},help:{"v1-y7hrzb-4i":`Reguły powiązań najwyższego poziomu dotyczące routingu i trwałego przypisania rozmów ACP. Użyj type=route do zwykłego routingu, a type=acp do trwałych powiązań ze środowiskiem wykonawczym ACP.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Nadpisania ustawień powiązania ACP`},help:{"v1-1t4lisi-44":`Opcjonalne nadpisania ustawień ACP dla poszczególnych powiązań z bindings[].type=acp. Ta warstwa nadpisuje wartości domyślne agents.entries.*.runtime.acp dla pasującej rozmowy.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Backend powiązania ACP`},help:{"v1-rsrbkp-2x":`Nadpisanie backendu ACP dla tego powiązania (w razie braku używany jest backend ACP środowiska wykonawczego agenta, a następnie globalne ustawienie acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Katalog roboczy powiązania ACP`},help:{"v1-ngpkj0-1y":`Nadpisanie katalogu roboczego dla sesji ACP tworzonych na podstawie tego powiązania.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Etykieta powiązania ACP`},help:{"v1-azce82-23":`Czytelna etykieta statusu i diagnostyki ACP w tej powiązanej rozmowie.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Tryb powiązania ACP`},help:{"v1-cgq8xv-1v":`Nadpisanie trybu sesji ACP dla tego powiązania (persistent lub oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`Identyfikator agenta powiązania`},help:{"v1-17ra0cl-4m":`Identyfikator docelowego agenta, do którego trafia ruch po spełnieniu odpowiedniej reguły dopasowania powiązania. Używaj wyłącznie prawidłowych identyfikatorów skonfigurowanych agentów, aby uniknąć błędów routingu podczas działania.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Reguła dopasowania powiązania`},help:{"v1-sc1w2e-51":`Obiekt reguły dopasowania określający, kiedy powiązanie ma zastosowanie, uwzględniający kanał i opcjonalne ograniczenia dotyczące konta lub rozmówcy. Stosuj precyzyjne reguły, aby uniknąć przypadkowego przejęcia obsługi przez agenta w innych kontekstach.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`Identyfikator konta powiązania`},help:{"v1-1d209g7-56":`Opcjonalny selektor konta dla konfiguracji kanałów z wieloma kontami, dzięki któremu powiązanie dotyczy tylko jednej tożsamości. Użyj go, gdy trasa wymaga ograniczenia do konkretnego konta; w przeciwnym razie pozostaw bez ustawienia.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Kanał powiązania`},help:{"v1-d22m5-54":"Identyfikator kanału lub dostawcy, którego dotyczy to powiązanie, np. `telegram`, `discord` lub identyfikator kanału wtyczki. Użyj dokładnie takiego klucza kanału, jaki jest w konfiguracji, aby ocena powiązania działała niezawodnie."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`Identyfikator serwera powiązania`},help:{"v1-jzzfj1-4x":`Opcjonalne ograniczenie identyfikatora gildii/serwera w stylu Discord, stosowane przy ocenie powiązań we wdrożeniach wieloserwerowych. Użyj go, gdy te same identyfikatory rozmów mogą występować w różnych gildiach.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Dopasowanie rozmowy w powiązaniu`},help:{"v1-gcjxff-4i":`Opcjonalne kryterium dopasowania konkretnych rozmów, obejmujące typ i identyfikator rozmowy. Użyj go, gdy do agenta ma być przypisana tylko jedna rozmowa bezpośrednia, grupa lub kanał.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`Identyfikator rozmowy w powiązaniu`},help:{"v1-86fbh7-4b":`Identyfikator używany do dopasowywania rozmów, np. identyfikator czatu, kanału lub grupy od dostawcy. Podaj go dokładnie, aby uniknąć braku dopasowania bez powiadomienia.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Typ rozmowy w powiązaniu`},help:{"v1-uufscp-4x":`Typ rozmowy: "direct", "group", "channel" lub starszy "dm" (przestarzały alias dla direct). W nowych konfiguracjach używaj "direct" i dbaj o zgodność typu z semantyką kanału.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Role w powiązaniu`},help:{"v1-6s891m-4k":`Opcjonalna lista filtrów opartych na rolach, używana przez dostawców dołączających role do kontekstu czatu. Użyj jej, aby kierować ruch związany z rolami uprzywilejowanymi lub operacyjnymi do wyspecjalizowanych agentów.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`Identyfikator zespołu w powiązaniu`},help:{"v1-hh9ps2-48":`Opcjonalne ograniczenie identyfikatora zespołu/obszaru roboczego, używane przez dostawców organizujących czaty w ramach zespołów. Dodaj je, gdy chcesz ograniczyć powiązania do kontekstu jednego obszaru roboczego.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Sesja powiązania`},help:{"v1-x325l2-4v":`Opcjonalne nadpisania ustawień sesji dla rozmów pasujących do tego powiązania. Użyj ich, gdy szczegółowa trasa powinna zachować tego samego agenta, ale inaczej izolować ciągłość sesji.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Zakres sesji wiadomości bezpośrednich w powiązaniu`},help:{"v1-10sg3xw-4s":`Opcjonalne nadpisanie zakresu sesji wiadomości bezpośrednich dla tego powiązania trasy. Na przykład możesz zachować globalne ustawienie session.dmScope="main", a jednocześnie używać "per-account-channel-peer" dla wybranych rozmówców w wiadomościach bezpośrednich.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Zakres sesji grupowych w powiązaniu`},help:{"v1-1ys2u7k-6n":`Opcjonalne nadpisanie zakresu sesji grup lub kanałów dla tego powiązania trasy. "per-group" zachowuje rozdzielenie pasujących pokojów i zapewnia ich obserwowanie w tle przez główną sesję agenta niezależnie od dmScope; "main" scala ich kontekst z sesją główną i nie wymaga obserwowania.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Typ powiązania`},help:{"v1-172mhtk-3o":`Rodzaj powiązania. Użyj "route" (lub pomiń w przypadku starszych wpisów tras) dla zwykłego routingu, a "acp" dla trwałych powiązań rozmów ACP.`}},broadcast:{label:{"v1-awqjh0-j":`Wątki grup agentów`},help:{"v1-1tz72sr-6b":`Użyj wątków grup agentów, aby uruchomić kilku skonfigurowanych agentów w jednej rozmowie przychodzącej, każdego we własnej sesji. Wpisy z identyfikatorem kanału obsługują ograniczoną liczbę kolejnych rund; starsze tablice rozmówców WhatsApp zachowują działanie jednoprzebiegowe.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Uczestnicy i opcje grupy agentów`},help:{"v1-1b63zmt-7d":`Użyj identyfikatora rozmówcy z prefiksem kanału (na przykład "telegram:-100123"), aby skonfigurować tablicę identyfikatorów agentów lub obiekt o ścisłym schemacie z polami agents, mentionGating, maxRounds i maxTurns. Wpisy z prefiksem kanału mają pierwszeństwo przed starszymi kluczami rozmówców WhatsApp i dopuszczają maksymalnie 16 agentów.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Uczestnicy grupy agentów`},help:{"v1-g5o0ky-43":`Identyfikatory agentów uczestniczących z agents.entries (maksymalnie: 16). Każdy uczestnik korzysta z własnej sesji dla danego kanału, konta, rozmowy i wątku.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Maksymalna liczba rund grupy agentów`},help:{"v1-i6v4jc-5a":`Maksymalna liczba rund na wiadomość przychodzącą, wliczając rundę początkową (liczba całkowita: 1–4, domyślnie: 1). W kolejnych rundach udostępniane są odpowiedzi innych uczestników, w ograniczonym zakresie i z oznaczeniem autorów. Rundy kończą się, gdy wszyscy uczestnicy zrezygnują z odpowiedzi.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Maksymalna liczba tur grupy agentów`},help:{"v1-1kiv8dy-72":`Maksymalna liczba tur uczestników na wiadomość przychodzącą we wszystkich rundach (liczba całkowita: 1–32, domyślnie: agents.length). Miejsca są rezerwowane przed równoległym uruchomieniem; limit dotyczy tur agentów, a nie faktycznych fragmentów wiadomości ani wysyłek przez narzędzia. Budżety nie są wznawiane po ponownym uruchomieniu.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Wybór uczestników grupy agentów na podstawie wzmianek`},help:{"v1-uay9zu-5u":`Wybieraj tylko uczestników wskazanych bezpośrednio przez @wzmianki, jeśli znaleziono dopasowania; w przeciwnym razie uruchamiaj wszystkich uczestników (domyślnie: true). Same nazwy lub emoji nie powodują wyboru uczestników. Listy dozwolonych kanałów i reguły dopuszczania nadal obowiązują.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Strategia grupy agentów`},help:{"v1-p4k9hu-4q":`Kolejność uruchamiania uczestników: "parallel" (domyślnie) uruchamia agentów równolegle, a "sequential" — w skonfigurowanej kolejności. Każda runda kończy się przed rozpoczęciem następnej.`}},browser:{label:{"v1-13dzmen-7":`Przeglądarka`},help:{"v1-5b74wi-5l":`Ustawienia działania przeglądarki dotyczące lokalnego lub zdalnego połączenia przez CDP, kierowania do profili oraz wykonywania zrzutów ekranu i migawek. Zachowaj ustawienia domyślne, chyba że Twój proces automatyzacji wymaga niestandardowych ustawień transportu przeglądarki.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Zezwalaj na import profilu systemowego`},help:{"v1-1lsvlxw-5w":`Umożliwia hostom z macOS importowanie plików cookie z lokalnego profilu systemowego przeglądarki z rodziny Chrome do zarządzanego profilu przeglądarki OpenClaw. Wyłącz tę opcję, aby uniemożliwić import plików cookie z profilu przeglądarki i zapobiec wyświetlaniu powiązanego monitu o zgodę na dostęp do pęku kluczy macOS.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Tryb wyłącznie podłączania do przeglądarki`},help:{"v1-xaw7xm-4s":`Ogranicza działanie do podłączania do przeglądarki bez uruchamiania lokalnych procesów przeglądarki. Użyj tej opcji, gdy wszystkimi sesjami przeglądarki zarządza zewnętrznie zdalny dostawca CDP.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`Adres URL CDP przeglądarki`},help:{"v1-2n72jb-65":`Adres URL punktu końcowego CDP/DevTools używany do podłączania do zewnętrznie zarządzanej instancji przeglądarki. Użyj go w przypadku scentralizowanych hostów przeglądarek, tuneli lub podłączania do istniejącej sesji. Ogranicz dostęp do tego adresu URL do zaufanych ścieżek sieciowych.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Domyślny profil przeglądarki`},help:{"v1-a6xo96-52":`Nazwa domyślnego profilu przeglądarki wybieranego, gdy wywołujący nie wskażą profilu wprost. Jako domyślnego użyj stałego profilu z ograniczonymi uprawnieniami, aby zmniejszyć ryzyko przypadkowego użycia stanu z innego kontekstu.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Przeglądarka włączona`},help:{"v1-19qr4oj-56":`Włącza obsługę przeglądarki w Gateway, umożliwiając działanie narzędzi przeglądarkowych i przepływów pracy opartych na CDP. Wyłącz, jeśli automatyzacja przeglądarki nie jest potrzebna, aby ograniczyć powierzchnię ataku i nakład pracy przy uruchamianiu.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Włącz wykonywanie skryptów w przeglądarce`},help:{"v1-1oa79mq-59":`Włącza funkcje pomocnicze po stronie przeglądarki, które umożliwiają wykonywanie skryptów w czasie działania, jeśli jest to obsługiwane. Pozostaw wyłączone, chyba że przepływy pracy wymagają wykonywania skryptów wykraczającego poza migawki i nawigację.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Ścieżka do pliku wykonywalnego przeglądarki`},help:{"v1-1plb4ki-6i":`Jawnie określona ścieżka do pliku wykonywalnego przeglądarki, używana, gdy automatyczne wykrywanie nie wystarcza w środowisku hosta. Użyj stałej ścieżki bezwzględnej lub ścieżki zaczynającej się od ~, oznaczającego katalog domowy w systemie operacyjnym, aby sposób uruchamiania pozostawał przewidywalny po ponownych uruchomieniach.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Przekaźnik rozszerzenia przeglądarki`},help:{"v1-6ywlwr-4e":`Ustawienia zgodności uwierzytelniania przekaźnika rozszerzenia Chrome. Utrzymuj okres obsługi starszych metod tylko tak długo, jak wymagają tego starsze sparowane rozszerzenia lub zewnętrzne klienty CDP.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Zezwalaj na starsze metody uwierzytelniania przekaźnika przeglądarki`},help:{"v1-pj2e90-63":`Tymczasowo akceptuje starsze metody uwierzytelniania przekaźnika: Bearer, Basic i token w subprotokole. Wartość domyślna: true na jeden okres migracji. Ustaw false, gdy wszystkie rozszerzenia i zewnętrzne klienty CDP będą używać Browser Relay Authentication v2.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Tryb przeglądarki bez interfejsu graficznego`},help:{"v1-1rswq8j-5a":`Wymusza uruchamianie przeglądarki bez interfejsu graficznego, gdy lokalny program uruchamiający uruchamia jej instancje. W środowiskach serwerowych pozostaw ten tryb włączony i wyłączaj go tylko wtedy, gdy debugowanie wymaga widocznego interfejsu.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Tryb przeglądarki bez piaskownicy`},help:{"v1-slntux-4w":`Wyłącza flagi izolacji w piaskownicy Chromium w środowiskach, w których piaskownica nie działa podczas uruchamiania. W miarę możliwości pozostaw tę opcję wyłączoną, ponieważ jej włączenie osłabia ochronę zapewnianą przez izolację procesów.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Profile przeglądarki`},help:{"v1-1x8lf05-51":`Mapa połączeń nazwanych profili przeglądarki służąca do jawnego kierowania do portów lub adresów URL CDP, z opcjonalnymi metadanymi. Zachowuj spójne nazwy profili i unikaj nakładających się definicji punktów końcowych.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Tryb wyłącznie dołączania dla profilu przeglądarki`},help:{"v1-2b5zs0-5a":`Ustawienie trybu wyłącznie dołączania dla danego profilu, które zastępuje ustawienie ogólne, pomija lokalne uruchamianie przeglądarki i jedynie łączy się z istniejącym punktem końcowym CDP. Przydatne, gdy jeden profil jest zarządzany zewnętrznie, a pozostałe są uruchamiane lokalnie.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Port CDP profilu przeglądarki`},help:{"v1-gx1yiq-49":`Lokalny port CDP danego profilu używany do łączenia się z instancjami przeglądarki przez port zamiast adresu URL. Używaj unikalnych portów dla poszczególnych profili, aby uniknąć konfliktów połączeń.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`Adres URL CDP profilu przeglądarki`},help:{"v1-x491r0-64":`Adres URL punktu końcowego CDP/DevTools danego profilu używany do jawnego kierowania połączeń przeglądarki według nazwy profilu. Używaj go dla zdalnych hostów CDP, tuneli lub profili istniejących sesji, które powinny łączyć się przez działający punkt końcowy Chrome DevTools.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Sterownik profilu przeglądarki`},help:{"v1-17byyx6-5r":`Tryb sterownika przeglądarki dla danego profilu. Użyj "openclaw" (lub starszego "clawd") dla profili opartych na CDP, "existing-session" do łączenia przez Chrome DevTools MCP lub "extension" do uwierzytelnionego połączenia pośredniczącego przez rozszerzenie Chrome.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Ścieżka pliku wykonywalnego przeglądarki dla profilu`},help:{"v1-29azyv-4w":`Ścieżka pliku wykonywalnego przeglądarki dla danego profilu, używana w zarządzanych profilach przeglądarki uruchamianych lokalnie. Zastępuje browser.executablePath i obsługuje ścieżki zaczynające się od ~, oznaczającego katalog domowy w systemie operacyjnym.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Tryb bez interfejsu graficznego dla profilu przeglądarki`},help:{"v1-p4jtgv-4u":`Ustawienie trybu bez interfejsu graficznego dla danego profilu, zastępujące ustawienie domyślne w lokalnie uruchamianych instancjach przeglądarki. Użyj go, gdy jeden profil ma działać bez interfejsu graficznego, bez wymuszania browser.headless dla wszystkich pozostałych profili.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Argumenty Chrome MCP dla profilu przeglądarki`},help:{"v1-rc45ke-5g":`Dodatkowe argumenty Chrome DevTools MCP dla danego profilu przy łączeniu w trybie existing-session, takie jak --no-usage-statistics. Podane tutaj argumenty punktu końcowego zastępują wbudowane automatyczne łączenie lub wybór adresu URL przeglądarki.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Polecenie Chrome MCP dla profilu przeglądarki`},help:{"v1-1xpty8o-2h":`Polecenie Chrome DevTools MCP dla danego profilu przy łączeniu w trybie existing-session. Domyślnie npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Katalog danych użytkownika dla profilu przeglądarki`},help:{"v1-5xvgex-9h":`Katalog danych użytkownika Chromium przypisany do profilu, używany do dołączania do istniejącej sesji przez Chrome DevTools MCP. Użyj go dla Brave, Edge, Chromium lub profili Chrome innych niż domyślny, gdy wbudowany mechanizm automatycznego łączenia wybrałby niewłaściwy katalog danych przeglądarki na wybranym hoście lub węźle przeglądarki. Ścieżki zaczynające się od ~ są rozwijane do katalogu domowego użytkownika w systemie operacyjnym.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Domyślne ustawienia migawek przeglądarki`},help:{"v1-v19wdy-4y":`Domyślna konfiguracja tworzenia migawek używana, gdy wywołujący nie podają jawnych opcji migawki. Dostosuj ją, aby zapewnić spójne działanie tworzenia migawek w różnych kanałach i ścieżkach automatyzacji.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Tryb migawek przeglądarki`},help:{"v1-joeyxp-5c":`Domyślny tryb wyodrębniania migawek określający sposób przekształcania treści strony na potrzeby agenta. Wybierz tryb zapewniający odpowiednią równowagę między czytelnością, wiernością odwzorowania a zużyciem tokenów w Twoich procesach.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Zasady ochrony przeglądarki przed SSRF`},help:{"v1-1qbp9im-5e":`Ustawienia zabezpieczeń przed fałszowaniem żądań po stronie serwera dla ścieżek pobierania danych przez przeglądarkę lub sieć, które mogłyby uzyskać dostęp do hostów wewnętrznych. W środowisku produkcyjnym zachowaj restrykcyjne ustawienia domyślne i zezwalaj na dostęp tylko do jawnie zatwierdzonych celów.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Dozwolone nazwy hostów przeglądarki`},help:{"v1-1rng39-2k":`Dokładne nazwy hostów lub dosłowne adresy IP dozwolone przez mechanizmy kontroli zasad ochrony przeglądarki przed SSRF. Ogranicz listę do minimum.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Zezwalaj na zakres unikatowych adresów lokalnych IPv6 w przeglądarce`},help:{"v1-1glx5cy-2c":`Zezwalaj na unikatowe adresy lokalne IPv6 (fc00::/7) w zaufanych środowiskach proxy korzystających z fikcyjnych adresów IP.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Przeglądarka: zezwalaj na zakres testowy RFC 2544`},help:{"v1-10ateu3-2i":`Zezwalaj na adresy IP z zakresu testowego RFC 2544 (198.18.0.0/15) w zaufanych środowiskach proxy z fikcyjnymi adresami IP.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Przeglądarka: blokowane nazwy hostów`},help:{"v1-nug0we-6k":`Wzorce nazw hostów blokowanych przed rozwiązywaniem DNS i zastosowaniem reguł zezwalających, nawet przy włączonym dostępie do sieci prywatnej. Obsługuje dokładne nazwy hostów oraz "*.example.com" wyłącznie dla subdomen; dodaj osobno "example.com", aby zablokować domenę główną. Pusta lub nieustawiona wartość nie dodaje żadnych blokad.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Przeglądarka: zezwalaj na sieć prywatną (niebezpieczne)`},help:{"v1-17103pi-4m":`Zezwala narzędziom przeglądarki na dostęp do zakresów adresów sieci prywatnej. Domyślnie wyłączone, jeśli nie ustawiono wartości; włączaj tylko dla jawnie zaufanych miejsc docelowych w sieci prywatnej.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Przeglądarka: sprzątanie kart`},help:{"v1-1ctwaad-4y":`Zasady sprzątania w miarę możliwości kart przeglądarki otwartych przez sesje głównego agenta. Pozostaw włączone, aby zapobiec gromadzeniu się nieużywanych kart piaskownicy lub zarządzanej przeglądarki w długo działających instancjach Gateway.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Przeglądarka: sprzątanie kart włączone`},help:{"v1-4sv97p-3u":`Włącza sprzątanie bezczynnych, śledzonych kart przeglądarki w sesjach głównego agenta. Wyłączaj tylko wtedy, gdy zewnętrzne narzędzia w pełni zarządzają cyklem życia kart.`}},channels:{label:{"v1-1ju93md-8":`Kanały`},help:{"v1-12yv6ma-5n":`Konfiguracje dostawców kanałów oraz wspólne ustawienia domyślne sterujące zasadami dostępu, widocznością sygnałów aktywności i zachowaniem poszczególnych interfejsów. Utrzymuj ustawienia domyślne w jednym miejscu i zastępuj je dla poszczególnych dostawców tylko tam, gdzie to konieczne.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Domyślne ustawienia kanałów`},help:{"v1-uz6veb-4p":`Domyślne zachowanie kanałów stosowane u wszystkich dostawców, gdy nie określono ustawień specyficznych dla danego dostawcy. Użyj tej opcji, aby zapewnić spójne zasady bazowe przed dostosowaniem ustawień poszczególnych dostawców.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Domyślna ochrona przed pętlami botów`},help:{"v1-1lpznyk-4w":`Domyślne ustawienia ochrony par przed pętlami dla dostawców kanałów obsługujących zabezpieczenia przed pętlami między botami. Nadpisuj je dla poszczególnych dostawców tylko wtedy, gdy dany kanał wymaga innego limitu.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Domyślny czas przerwy po wykryciu pętli botów w sekundach`},help:{"v1-1yl5ird-2z":`Czas przerwy w sekundach stosowany dla pary po przekroczeniu limitu pętli. Wartość domyślna dla obsługujących tę funkcję kanałów wynosi 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Domyślna ochrona przed pętlami botów włączona`},help:{"v1-3ruik-4r":`Domyślnie włącza ochronę par przed pętlami w obsługujących ją kanałach, gdy wiadomości tworzone przez boty mogą trafić do dalszego przetwarzania. Dostawcy nadal mogą wyłączyć tę ochronę, gdy boty są ignorowane.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Domyślny limit zdarzeń pętli botów w oknie czasowym`},help:{"v1-1u0mdjc-41":`Maksymalna liczba zdarzeń, które para nadawca–odbiorca może wymienić w skonfigurowanym oknie czasowym, zanim rozpocznie się blokowanie. Wartość domyślna dla obsługujących tę funkcję kanałów wynosi 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Domyślna długość okna czasowego pętli botów w sekundach`},help:{"v1-12xpmen-2m":`Długość przesuwnego okna w sekundach dla limitów pętli między parami. Wartość domyślna dla obsługujących tę funkcję kanałów wynosi 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Domyślna widoczność kontekstu`},help:{"v1-1hze3g1-5o":`Domyślna widoczność dodatkowego kontekstu dla pobranych cytatów, wątków i historii: "all" (zachowaj cały kontekst), "allowlist" (tylko nadawcy z listy dozwolonych) lub "allowlist_quote" (lista dozwolonych + zachowanie bezpośrednich cytatów).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Domyślna polityka grup`},help:{"v1-ntl9m4-4n":`Domyślna polityka grup we wszystkich kanałach: "open", "disabled" lub "allowlist". Aby zapewnić większe bezpieczeństwo konfiguracji produkcyjnej, pozostaw "allowlist", chyba że szeroki udział w grupach jest zamierzony.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Domyślna widoczność sygnałów aktywności`},help:{"v1-49bw75-4v":`Domyślne ustawienia widoczności sygnałów aktywności dla komunikatów o stanie wysyłanych przez dostawców lub kanały. Dostosuj je globalnie, aby ograniczyć nadmiar aktualizacji o prawidłowym stanie, zachowując widoczność alertów.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Pokazuj alerty sygnałów aktywności`},help:{"v1-8dk8zx-4g":`Przy wartości true wyświetla alerty sygnałów aktywności informujące o pogorszeniu stanu lub błędach, aby problemy były szybko widoczne w kanałach operatorów. Pozostaw włączone w środowisku produkcyjnym, aby awarie kanałów były widoczne.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Pokazuj prawidłowy stan sygnałów aktywności`},help:{"v1-17tg3mk-4z":`Gdy ma wartość true, wyświetla wpisy sygnału aktywności wskazujące prawidłowy stan/OK w informacjach o stanie kanałów. Pozostaw wartość false w środowiskach z dużą liczbą komunikatów i włączaj tylko wtedy, gdy operatorzy potrzebują wyraźnych potwierdzeń prawidłowego działania.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Używaj wskaźnika sygnału aktywności`},help:{"v1-1w12cs2-4m":`Włącza zwięzłe wyświetlanie sygnału aktywności w formie wskaźnika zamiast rozbudowanego tekstu stanu, jeśli jest to obsługiwane. Używaj trybu wskaźnika w panelach z dużą ilością informacji i wieloma aktywnymi kanałami.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Domyślne wzmianki niejawne`},help:{"v1-4gtdyv-48":`Domyślna reguła określająca, czy odpowiedź botowi, zacytowanie bota lub udział bota w wątku aktywują obsługujące tę funkcję kanały wiadomości bez jawnej wzmianki.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Domyślne wzmianki niejawne przy cytowaniu bota`},help:{"v1-va1u5v-2v":`Domyślnie traktuj cytowane wiadomości bota jako wzmianki niejawne. Wartość domyślna to true dla zachowania zgodności wstecznej.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Domyślne wzmianki niejawne przy odpowiadaniu botowi`},help:{"v1-lm44c3-39":`Domyślnie traktuj odpowiedzi na własne wiadomości bota jako wzmianki niejawne. Wartość domyślna to true dla zachowania zgodności wstecznej.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Domyślne wzmianki niejawne w wątkach z udziałem bota`},help:{"v1-160205h-3o":`Domyślnie traktuj kolejne wiadomości w wątkach, w których uczestniczył bot, jako wzmianki niejawne. Wartość domyślna to true dla zachowania zgodności wstecznej.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Nadpisania modelu dla kanałów`},help:{"v1-1b01spx-2p":`Mapowanie: dostawca -> identyfikator kanału / identyfikator rozmówcy w wiadomościach prywatnych -> nadpisanie modelu (wartości to provider/model lub aliasy).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Procesy robocze w chmurze`},help:{"v1-10carc4-5v":`Opcjonalne profile procesów roboczych w chmurze dla tymczasowych środowisk zdalnych. Jeśli ta sekcja zostanie pominięta lub nie zawiera profili, tworzenie procesów roboczych w chmurze pozostaje niedostępne, a dotychczasowa obsługa statusu bramy i węzłów nie ulega zmianie.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Pulpit procesu roboczego w chmurze (Labs)`},help:{"v1-vllayc-3n":`Włącza eksperymentalny interfejs worker.desktop.observe i panel pulpitu w Control UI dla środowisk procesów roboczych w chmurze obsługujących pulpit.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Pula przygotowanych procesów roboczych w chmurze`},help:{"v1-rw51o5-6b":`Limity dla przygotowanych procesów roboczych w chmurze utrzymywanych w gotowości na potrzeby późniejszych sesji. Zarezerwowane zasoby generują opłaty za działające maszyny do czasu zakończenia ich usuwania przez dostawcę; ich ustalony czas wygaśnięcia zależy od rzeczywistego zapotrzebowania projektu i obowiązującej u dostawcy polityki bezczynności.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Limit gotowych rezerwowych instancji roboczych w chmurze`},help:{"v1-1mpd1dt-7u":`Limit nieprzypisanych, przygotowanych instancji roboczych w chmurze dla całego Gateway, obejmujący wszystkie projekty i profile (domyślnie: 4). Instancje w trakcie przygotowywania oraz rezerwowe instancje, których usunięcie nie zostało potwierdzone, wliczają się do limitu. Ustaw 0, aby usunąć nieprzypisane rezerwy i wyłączyć ich uzupełnianie, zachowując ponowne wykorzystywanie migawek i aktywne sesje.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Profile procesów roboczych w chmurze`},help:{"v1-eii67l-3j":`Nazwane profile procesów roboczych w chmurze. Każdy profil wskazuje dostawcę procesów roboczych zarejestrowanego przez wtyczkę i zawiera ustawienia specyficzne dla tego dostawcy.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Profil procesu roboczego w chmurze`},help:{"v1-1v2w7jl-4u":`Pojedynczy profil procesu roboczego w chmurze wybierany według nazwy podczas tworzenia środowiska. Używaj obsługiwanych odwołań do danych uwierzytelniających dostawcy zamiast umieszczać poufne dane bezpośrednio w tym bloku.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Metoda instalacji procesu roboczego w chmurze`},help:{"v1-blrtbf-74":`Metoda instalacji procesu roboczego: "bundle" (domyślna) przesyła zainstalowaną kompilację bramy identyfikowaną skrótem zawartości i obsługuje wersje opublikowane, rozwojowe i nieopublikowane; "npm" instaluje dokładnie tę samą wersję bramy i jest dostępna tylko wtedy, gdy ta wersja została opublikowana.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Dostawca procesów roboczych w chmurze`},help:{"v1-1p4s4c1-44":`Identyfikator dostawcy procesów roboczych zarejestrowany przez wtyczkę. Skonfigurowana wtyczka musi udostępniać ten identyfikator, aby Gateway mógł tworzyć środowiska na podstawie profilu.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Docelowa liczba gotowych rezerwowych instancji roboczych w chmurze`},help:{"v1-1nwve9s-7w":`Docelowa liczba nieprzypisanych, przygotowanych instancji roboczych na każdy kwalifikujący się projekt korzystający z tego profilu (domyślnie: 1), z uwzględnieniem limitu puli przygotowanych instancji dla całego Gateway. Ustaw 0, aby wyłączyć rezerwy tego profilu, zachowując ponowne wykorzystywanie migawek. Instancje w trakcie przygotowywania oraz rezerwowe instancje, których usunięcie nie zostało potwierdzone, wliczają się do liczby docelowej.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Ustawienia dostawcy procesów roboczych w chmurze`},help:{"v1-mq7u32-4j":`Ustawienia specyficzne dla dostawcy, weryfikowane przez wybraną wtyczkę. Używaj obiektów SecretRef dla wartości zawierających sekrety; ustawienia o nieinterpretowanej strukturze nie obsługują automatycznego rozwiązywania odwołań do sekretów.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Czas bezczynności przed wstrzymaniem procesu roboczego w chmurze`},help:{"v1-1keuwgh-4w":`Automatycznie zwalnia zasoby bezczynnego procesu roboczego w chmurze po upływie tego czasu, np. 45m lub 2h; następna wiadomość powoduje utworzenie nowego procesu w jego miejsce. Minimum: 1m. Pozostaw nieustawione, aby procesy robocze działały bez przerwy.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Profile projektów dla procesów roboczych w chmurze`},help:{"v1-1kkfrif-46":`Domyślne nazwy profili procesów roboczych w chmurze przypisane do znormalizowanych identyfikatorów repozytoriów zapisanych małymi literami (host/owner/repo). Jawnie podane identyfikatory profili przydziału mają pierwszeństwo.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Profil projektu dla procesu roboczego w chmurze`},help:{"v1-1mux5u0-30":`Nazwa profilu procesu roboczego w chmurze używana domyślnie, gdy origin drzewa roboczego sesji odpowiada temu identyfikatorowi repozytorium.`}},commands:{label:{"v1-15x4mpf-8":`Polecenia`},help:{"v1-1gi0dr2-5a":`Steruje interfejsami poleceń czatu, ograniczeniami dostępu do właściciela oraz dostępem do poleceń z podwyższonymi uprawnieniami u różnych dostawców. Zachowaj ustawienia domyślne, chyba że potrzebujesz ściślejszej kontroli operatorów lub szerszej dostępności poleceń.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Reguły dostępu do poleceń z podwyższonymi uprawnieniami`},help:{"v1-7azkw-5g":`Określa reguły zezwalania na polecenia z podwyższonymi uprawnieniami według kanału i nadawcy dla interfejsów poleceń na poziomie właściciela. Używaj ściśle określonych tożsamości właściwych dla danego dostawcy, aby polecenia uprzywilejowane nie były dostępne dla szerokiego grona uczestników czatu.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Zezwalaj na polecenie Bash na czacie`},help:{"v1-83ah7w-36":"Zezwalaj poleceniu bash na czacie (`!`; alias `/bash`) na wykonywanie poleceń powłoki hosta (domyślnie: false; wymaga tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Czas działania Bash na pierwszym planie (ms)`},help:{"v1-1o0o4dw-2c":`Czas oczekiwania bash przed przejściem do pracy w tle (domyślnie: 2000; 0 oznacza natychmiastowe przejście do pracy w tle).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`Zezwalaj na /config`},help:{"v1-151bb7c-21":`Zezwalaj poleceniu /config na czacie na odczyt i zapis konfiguracji na dysku (domyślnie: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`Zezwalaj na /debug`},help:{"v1-y1lc3j-1y":`Zezwalaj na polecenie /debug na czacie do nadpisywania ustawień wyłącznie na czas działania (domyślnie: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`Zezwalaj na /mcp`},help:{"v1-1rtwcgd-2o":`Zezwalaj poleceniu /mcp na czacie na zarządzanie konfiguracją serwerów MCP w OpenClaw w sekcji mcp.servers (domyślnie: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Polecenia natywne`},help:{"v1-dighr2-5n":`Rejestruje natywne polecenia ukośnikowe i polecenia menu w kanałach obsługujących rejestrację poleceń (Discord, Slack, Telegram). Pozostaw tę opcję włączoną, aby ułatwić odnajdywanie poleceń, chyba że celowo korzystasz wyłącznie z poleceń tekstowych.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Natywne polecenia umiejętności`},help:{"v1-19gtqci-5h":`Rejestruje natywne polecenia umiejętności, aby użytkownicy mogli wywoływać umiejętności bezpośrednio z menu poleceń dostawcy, jeśli jest to obsługiwane. Zachowaj zgodność z zasadami dotyczącymi umiejętności, aby udostępniane polecenia odpowiadały oczekiwaniom operatorów.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Właściciele poleceń`},help:{"v1-1di38gv-3y":`Jawna lista właścicieli uprawnionych do wykonywania poleceń zastrzeżonych dla właściciela. Używaj identyfikatorów właściwych dla kanału (opcjonalnie z prefiksem, np. "whatsapp:+15551234567"). '*' jest ignorowane.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`Zezwalaj na /plugins`},help:{"v1-akwy9y-33":`Zezwalaj na polecenie czatu /plugins, które wyświetla wykryte wtyczki i przełącza ich włączenie w konfiguracji (domyślnie: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Zezwalaj na ponowne uruchomienie`},help:{"v1-m32fv2-27":`Zezwalaj na /restart, /update i zewnętrzne żądania ponownego uruchomienia przez SIGUSR2 (domyślnie: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Polecenia tekstowe`},help:{"v1-1utu76s-5j":`Włącza analizowanie poleceń tekstowych we wpisach na czacie, obok natywnych interfejsów poleceń, jeśli są dostępne. Pozostaw tę opcję włączoną, aby zachować zgodność z kanałami, które nie obsługują natywnej rejestracji poleceń.`}},cron:{label:{"v1-1qlte4b-b":`Automatyzacje`},help:{"v1-4md8ic-5u":`Globalne ustawienia harmonogramu dotyczące zapisanych automatyzacji, współbieżności wykonań, dostarczania awaryjnego i przechowywania sesji wykonań. Zachowaj wartości domyślne, chyba że zwiększasz skalę automatyzacji lub integrujesz zewnętrzne odbiorniki webhooków.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Automatyzacje włączone`},help:{"v1-y8otx6-5i":`Włącza wykonywanie automatyzacji według zapisanych harmonogramów zarządzanych przez Gateway. Pozostaw włączone, aby przypomnienia i automatyzacje działały normalnie. Wyłącz tylko wtedy, gdy chcesz wstrzymać wykonywanie wszystkich automatyzacji bez usuwania zadań.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Okres przechowywania sesji automatyzacji`},help:{"v1-4wagu6-7e":"Określa, jak długo sesje zakończonych wykonań automatyzacji są przechowywane przed usunięciem (`24h`, `7d`, `1h30m` lub `false`, aby wyłączyć usuwanie; zerowy czas, np. `0h`, również je wyłącza; domyślnie: `24h`). Użyj krótszego okresu przechowywania, aby ograniczyć wzrost zajętego miejsca przy częstych uruchomieniach."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Pomijaj zaległe automatyzacje cykliczne`},help:{"v1-w9wfmo-66":`Pomija zaległe terminy cyklicznych zadań cron/every przy uruchamianiu Gateway i planuje ich następne przyszłe wykonanie zamiast nadrabiać zaległości. Domyślnie: false. Włącz, aby uniknąć nieaktualnych przypomnień po przerwie w działaniu; jednorazowe zadania at nadal są wykonywane z opóźnieniem.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Zasady SSRF dla webhooków automatyzacji`},help:{"v1-1xlfqnu-5h":`Zasady SSRF stosowane do każdego wychodzącego webhooka automatyzacji. Cele prywatne, pętli zwrotnej, lokalne dla łącza i wewnętrzne pozostają zablokowane, chyba że te zasady jawnie na nie zezwalają. Pozostaw bez ustawienia, aby zachować ścisłe ograniczenia dostarczania.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Dozwolone nazwy hostów dla webhooków automatyzacji`},help:{"v1-1i94hyz-3n":`Dokładne nazwy hostów lub dosłowne adresy IP, do których można dostarczać webhooki automatyzacji, w tym cele w innym przypadku zablokowane. Ogranicz listę do minimum.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Zezwalaj na zakres unikalnych adresów lokalnych IPv6 dla webhooków automatyzacji`},help:{"v1-rke0oj-3b":`Zezwala na wysyłanie webhooków automatyzacji na unikalne adresy lokalne IPv6 (fc00::/7). Używaj tylko w zaufanych środowiskach proxy typu fake-IP.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Zezwalaj na zakres testów wydajności RFC 2544 dla webhooków automatyzacji`},help:{"v1-x1usg4-3h":`Zezwala na wysyłanie webhooków automatyzacji na adresy IP z zakresu testów wydajności RFC 2544 (198.18.0.0/15). Używaj tylko w zaufanych środowiskach proxy z fikcyjnymi adresami IP.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Zablokowane nazwy hostów webhooków automatyzacji`},help:{"v1-16cv1ic-6a":`Wzorce nazw hostów blokowane przed rozwiązywaniem DNS i sprawdzaniem reguł zezwalających na dostarczanie webhooków automatyzacji. Obsługuje dokładne nazwy hostów oraz "*.example.com" wyłącznie dla subdomen; dodaj osobno "example.com", aby zablokować domenę główną. Wartość pusta lub nieustawiona nie dodaje żadnych blokad.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Niebezpieczne zezwolenie na dostęp webhooków automatyzacji do sieci prywatnej`},help:{"v1-1n9710c-3t":`Zezwala na wysyłanie webhooków automatyzacji do celów w sieciach prywatnych i wewnętrznych. Pozostaw wyłączone, chyba że wszystkie skonfigurowane miejsca docelowe webhooków są zaufane.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Token Bearer webhooków automatyzacji`},help:{"v1-1l90hxg-5l":`Token Bearer dołączany do żądań POST webhooków automatyzacji w trybie webhook. Zalecane jest podstawianie wartości z sekretu lub zmiennej środowiskowej oraz regularna rotacja tego tokenu, jeśli współdzielone punkty końcowe webhooków są dostępne z internetu.`}},desktop:{label:{"v1-rs698z-7":`Pulpit`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Lokalny pulpit`},help:{"v1-99weio-30":`Podgląd pulpitu sparowanych węzłów lub eksperymentalnego źródła hosta Gateway, obsługiwany przez lokalny serwer VNC.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Udostępnianie pulpitu`},help:{"v1-m9lbcj-83":`Włącza źródło pulpitu na tym komputerze. Sparowane węzły macOS, Windows i Linux są domyślnie włączone; jawnie ustawiona preferencja udostępniania w aplikacji komputerowej ma pierwszeństwo. Źródło Labs na hoście Gateway jest domyślnie wyłączone i stosuje zmiany na bieżąco. Po zmianie konfiguracji pulpitu sparowanego węzła uruchom go ponownie.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Zarządzany pulpit hosta z systemem Linux`},help:{"v1-1r7n22m-49":`Uruchamia i nadzoruje bezmonitorowy pulpit TigerVNC/XFCE w systemie Linux, dostępny tylko przez interfejs pętli zwrotnej. Jawnie wskazany port lub istniejący serwer VNC na domyślnym porcie nadal ma pierwszeństwo.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Lokalny plik hasła VNC`},help:{"v1-1m5lsox-37":`Ścieżka bezwzględna do pliku hasła VNC. W systemie macOS pomiń ją, aby podać dane logowania do konta podczas otwierania podglądu pulpitu.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Lokalny port VNC`},help:{"v1-1ku4w9b-2b":`Port RFB na interfejsie pętli zwrotnej działającego już serwera VNC na tym komputerze (domyślnie: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnostyka`},help:{"v1-1d5rnym-5p":`Ustawienia diagnostyczne dotyczące ukierunkowanego śledzenia, eksportu telemetrii i inspekcji pamięci podręcznej podczas debugowania. W środowisku produkcyjnym ogranicz podstawową diagnostykę do minimum i włączaj bardziej szczegółowe dane tylko podczas badania problemów.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Śledzenie pamięci podręcznej`},help:{"v1-10523zm-5b":`Ustawienia rejestrowania śladów pamięci podręcznej do obserwowania decyzji dotyczących pamięci podręcznej i kontekstu przesyłanych danych w uruchomieniach osadzonych. Włącz tę opcję tymczasowo na potrzeby debugowania, a następnie ją wyłącz, aby ograniczyć ilość poufnych danych w dziennikach.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Śledzenie pamięci podręcznej włączone`},help:{"v1-2c1umi-1v":`Rejestruj migawki śladów pamięci podręcznej dla uruchomień osadzonego agenta (domyślnie: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnostyka włączona`},help:{"v1-a46pxt-4h":`Główny przełącznik danych z instrumentacji diagnostycznej w dziennikach i mechanizmach integracji telemetrii. Domyślnie włączony; ustaw false tylko w środowiskach o znacznych ograniczeniach.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Flagi diagnostyczne`},help:{"v1-x4w5ok-33":`Włącz ukierunkowane logi diagnostyczne za pomocą flagi (np. ["telegram.http"]). Obsługuje symbole wieloznaczne, takie jak "telegram.*" lub "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Ustawienia eksportu OpenTelemetry dla śladów, metryk i logów generowanych przez komponenty Gateway. Użyj ich podczas integracji ze scentralizowanymi systemami obserwowalności i potokami śledzenia rozproszonego.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Przechwytywanie treści w OpenTelemetry`},help:{"v1-19tid4t-2t":`Opcjonalne przechwytywanie treści w spanach OTEL. Domyślnie wyłączone; wartość true powoduje przechwytywanie treści wiadomości innych niż systemowe oraz treści narzędzi.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry włączone`},help:{"v1-193bm0-5b":`Włącza potok eksportu OpenTelemetry dla śladów, metryk i logów na podstawie skonfigurowanych ustawień punktu końcowego i protokołu. Pozostaw wyłączone, dopóki punkt końcowy kolektora i uwierzytelnianie nie zostaną w pełni skonfigurowane.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`Punkt końcowy OpenTelemetry`},help:{"v1-4rrd1x-4y":`Adres URL punktu końcowego kolektora używany do przesyłania danych eksportowanych przez OpenTelemetry, wraz ze schematem i portem. Użyj dostępnego, zaufanego punktu końcowego kolektora i monitoruj błędy odbioru danych po wdrożeniu.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`Interwał opróżniania buforów OpenTelemetry (ms)`},help:{"v1-1moqogc-53":`Interwał w milisekundach określający częstotliwość przesyłania danych telemetrycznych z buforów do kolektora. Zwiększ go, aby ograniczyć liczbę operacji eksportu, lub zmniejsz, aby szybciej uzyskiwać wgląd w dane podczas reagowania na incydent.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`Nagłówki OpenTelemetry`},help:{"v1-s26t2a-52":`Dodatkowe nagłówki żądań HTTP wysyłane z żądaniami eksportu OpenTelemetry, często używane do uwierzytelniania dzierżawców lub routingu. Przechowuj sekrety w wartościach opartych na zmiennych środowiskowych i unikaj nadmiernej liczby nagłówków.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`Logi OpenTelemetry włączone`},help:{"v1-12wo6rv-4k":`Włącz eksport logów przez OpenTelemetry oprócz zapisywania ich w lokalnych miejscach docelowych. Użyj tej opcji, gdy wymagana jest scentralizowana korelacja logów między usługami i agentami.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`Punkt końcowy logów OpenTelemetry`},help:{"v1-1vgzldu-40":`Punkt końcowy OTLP/HTTP przeznaczony do logów. Jeśli jest ustawiony, zastępuje diagnostics.otel.endpoint i OTEL_EXPORTER_OTLP_ENDPOINT wyłącznie na potrzeby eksportu logów.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`Eksporter logów OpenTelemetry`},help:{"v1-9bzywd-5q":`Miejsce docelowe eksportu logów dla diagnostics.otel.logs. Użyj "otlp" dla skonfigurowanego punktu końcowego logów OTLP, "stdout", aby wysyłać po jednym rekordzie JSON w każdym wierszu stdout w potokach logów kontenerów, lub "both", gdy wymagane są oba miejsca docelowe.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Prefiks nazw metryk OpenTelemetry`},help:{"v1-1epdpi9-b2":`Zastępuje domyślny prefiks "openclaw." w nazwach metryk należących do OpenClaw. Użyj pustego ciągu, aby usunąć prefiks, lub ciągu zaczynającego się od litery i zawierającego maksymalnie 128 znaków ASCII: liter, cyfr, podkreśleń, kropek, łączników i ukośników. Uwzględnij potrzebny separator, na przykład "acme."; standardowe nazwy metryk gen_ai.* pozostają bez zmian. Zmiana tej wartości wymaga aktualizacji pulpitów i alertów, które odwołują się do starych nazw w zapytaniach.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`Metryki OpenTelemetry włączone`},help:{"v1-13r4cf4-4x":`Włącz eksport metryk do skonfigurowanego punktu końcowego kolektora OpenTelemetry. Pozostaw włączony na potrzeby paneli monitorowania stanu działania i wyłączaj tylko wtedy, gdy trzeba zminimalizować ilość danych metryk.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`Punkt końcowy metryk OpenTelemetry`},help:{"v1-qlfh7x-47":`Punkt końcowy OTLP/HTTP przeznaczony dla metryk. Po ustawieniu zastępuje diagnostics.otel.endpoint i OTEL_EXPORTER_OTLP_ENDPOINT wyłącznie na potrzeby eksportu metryk.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`Protokół OpenTelemetry`},help:{"v1-17ine8s-5e":`Protokół transportowy OTel do eksportu danych telemetrycznych. Akceptowany jest tylko "http/protobuf"; uruchom "openclaw doctor --fix", aby naprawić zapisaną starszą wartość "grpc" lub uzyskać wskazówki dotyczące ręcznej edycji właściwe dla danego źródła.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`Współczynnik próbkowania śladów OpenTelemetry`},help:{"v1-brcwep-50":`Współczynnik próbkowania śladów (0-1) określający, jaka część danych śledzenia jest eksportowana do systemów obserwowalności. Niższe wartości zmniejszają obciążenie i koszty, a wyższe zwiększają szczegółowość danych przydatnych podczas debugowania.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`Nazwa usługi OpenTelemetry`},help:{"v1-1hpiqon-5d":`Nazwa usługi zgłaszana w atrybutach zasobu telemetrycznego w celu identyfikacji tej instancji Gateway w systemach obserwowalności. Używaj stałych nazw, aby panele i alerty pozostawały spójne między wdrożeniami.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`Ślady OpenTelemetry włączone`},help:{"v1-j7zrrp-4s":`Włącz eksport śladów do skonfigurowanego punktu końcowego kolektora OpenTelemetry. Pozostaw włączony, gdy potrzebujesz śledzenia opóźnień lub debugowania, a wyłącz, jeśli chcesz zbierać tylko metryki i logi.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`Punkt końcowy śladów OpenTelemetry`},help:{"v1-8yw5p1-43":`Punkt końcowy śladów OTLP/HTTP właściwy dla tego typu sygnału. Jeśli jest ustawiony, zastępuje diagnostics.otel.endpoint i OTEL_EXPORTER_OTLP_ENDPOINT tylko przy eksporcie śladów.`}},discovery:{label:{"v1-l2sr05-9":`Wykrywanie`},help:{"v1-1sqleij-4w":`Ustawienia wykrywania usług obejmujące lokalne ogłaszanie przez mDNS i opcjonalne sygnalizowanie obecności w sieciach rozległych. Ogranicz wykrywanie do przewidzianych sieci, aby uniknąć ujawnienia metadanych usług.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`Wykrywanie przez mDNS`},help:{"v1-vtbyyq-4w":`Grupa ustawień wykrywania przez mDNS służąca do konfigurowania ogłaszania w sieci lokalnej i dostosowywania działania wykrywania. Do standardowego wykrywania w sieci LAN używaj trybu minimalnego, chyba że wymagane są dodatkowe metadane.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`Tryb wykrywania przez mDNS`},help:{"v1-1p28pd5-2m":`Tryb rozgłaszania mDNS (domyślnie "minimal", "full" uwzględnia cliPath/sshPort, "off" wyłącza mDNS).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Wykrywanie w sieciach rozległych`},help:{"v1-1akkqjm-53":`Grupa ustawień wykrywania w sieciach rozległych służąca do udostępniania sygnałów wykrywania poza łączem lokalnym. Włączaj tylko we wdrożeniach, które celowo agregują informacje o obecności Gateway w wielu lokalizacjach.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Domena wykrywania w sieciach rozległych`},help:{"v1-rxrygo-4m":`Opcjonalna domena unicast DNS-SD do wykrywania w sieciach rozległych, na przykład openclaw.internal. Użyj jej, gdy celowo udostępniasz wykrywanie Gateway poza lokalnym zasięgiem mDNS.`}},env:{label:{"v1-1zc80q-b":`Środowisko`},help:{"v1-1ao5po6-55":`Ustawienia importowania i nadpisywania środowiska służące do przekazywania zmiennych środowiska uruchomieniowego do procesu Gateway. Ta sekcja pozwala kontrolować wczytywanie środowiska powłoki i jawne przekazywanie zmiennych.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Import środowiska powłoki`},help:{"v1-1gw487t-4y":`Ustawienia importu środowiska powłoki umożliwiające wczytywanie zmiennych z powłoki logowania podczas uruchamiania. Pozostaw tę opcję włączoną, jeśli korzystasz z sekretów zdefiniowanych w profilu lub modyfikacji PATH.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Włączony import środowiska powłoki`},help:{"v1-5tiuup-5u":`Włącza wczytywanie zmiennych środowiskowych z profilu powłoki użytkownika podczas inicjalizacji przy uruchamianiu. Pozostaw włączone na komputerach programistów lub wyłącz w środowiskach usługowych o ograniczonym dostępie, w których zmienne środowiskowe są zarządzane jawnie.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Limit czasu importu środowiska powłoki (ms)`},help:{"v1-nsk2yf-5c":`Maksymalny czas w milisekundach na ustalenie środowiska powłoki, po którym stosowany jest mechanizm zastępczy. Ustaw krótszy limit, aby przyspieszyć uruchamianie, lub zwiększ go, jeśli inicjalizacja powłoki jest czasochłonna.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Nadpisania zmiennych środowiskowych`},help:{"v1-yxc3z7-5n":`Jawne nadpisania zmiennych środowiskowych w postaci par klucz/wartość, scalane ze środowiskiem procesu OpenClaw podczas działania. Użyj ich, aby zapewnić deterministyczną konfigurację środowiska zamiast polegać wyłącznie na efektach ubocznych profilu powłoki.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Ustawienia działania Gateway obejmujące tryb powiązania z interfejsami, uwierzytelnianie, Control UI, transport zdalny i zabezpieczenia operacyjne. Zachowaj ostrożne ustawienia domyślne, chyba że celowo udostępniasz Gateway poza zaufanymi interfejsami lokalnymi.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Zezwalaj na zastępcze użycie x-real-ip w Gateway`},help:{"v1-1wr3qmw-4c":`Włącza zastępcze użycie x-real-ip, gdy w konfiguracjach z serwerem proxy brakuje x-forwarded-for. Pozostaw wyłączone, chyba że infrastruktura obsługująca ruch przychodzący wymaga tego zachowania dla zgodności.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Uwierzytelnianie Gateway`},help:{"v1-70b6ni-50":`Zasady uwierzytelniania dostępu do Gateway przez HTTP/WebSocket, obejmujące tryb, dane uwierzytelniające, obsługę zaufanego serwera proxy i ograniczanie częstotliwości żądań. Uwierzytelnianie powinno być włączone w każdym wdrożeniu dostępnym poza interfejsem pętli zwrotnej.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Zezwalaj na tożsamość Tailscale przy uwierzytelnianiu Gateway`},help:{"v1-vqtmgw-53":`Po skonfigurowaniu pozwala zaufanym mechanizmom tożsamości Tailscale spełniać wymagania uwierzytelniania Gateway. Używaj tej opcji tylko wtedy, gdy zabezpieczenia tożsamości w sieci tailnet są silne, a procesy pracy operatorów od niej zależą.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Uprawnienia zakresowe tożsamości Gateway`},help:{"v1-1h0zxy7-5n":`Mapuje zweryfikowane tożsamości z zaufanego serwera proxy lub Tailscale na uprawnienia zakresowe operatora obowiązujące tylko dla danego połączenia. Klucze adresów e-mail są dopasowywane bez rozróżniania wielkości liter; przyznane uprawnienia rozszerzają zakresy urządzenia przed zastosowaniem limitu zakresów połączenia.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Tryb uwierzytelniania Gateway`},help:{"v1-j8rodq-9t":`Tryb uwierzytelniania Gateway: "none", "token", "password" lub "trusted-proxy", zależnie od architektury brzegowej. Tryb tokenu/hasła wybiera skonfigurowany sekret (gateway.auth.token lub gateway.auth.password); klienci mogą wysyłać go w dowolnym z dwóch pól uwierzytelniania połączenia. Przy bezpośrednim udostępnianiu używaj tokenu/hasła, a trybu trusted-proxy — wyłącznie za odpowiednio zabezpieczonymi serwerami proxy weryfikującymi tożsamość.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Hasło Gateway`},help:{"v1-1ndt0u2-4g":`Wspólny sekret wybierany przez gateway.auth.mode=password. Klienci mogą wysyłać go w auth.token lub auth.password. Tryb hasła jest wymagany dla Tailscale Funnel.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Limit częstotliwości prób uwierzytelniania Gateway`},help:{"v1-1kstr42-54":`Ustawienia ograniczania częstotliwości prób logowania i uwierzytelniania, które zmniejszają ryzyko ataków brute force na dane uwierzytelniające na granicy Gateway. Pozostaw je włączone w środowiskach dostępnych z zewnątrz i dostosuj progi do typowego natężenia ruchu.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Token Gateway`},help:{"v1-16i7cxs-5q":`Wspólny sekret używany przy ustawieniu gateway.auth.mode=token, domyślnym podczas nowej konfiguracji lokalnej. Klienci mogą przesyłać go w auth.token lub auth.password. Nasłuchiwanie na adresach innych niż adresy pętli zwrotnej wymaga włączonego trybu uwierzytelniania.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Uwierzytelnianie Gateway przez zaufane proxy`},help:{"v1-12fsi5d-58":`Mapowanie nagłówków uwierzytelniania przez zaufane proxy dla nadrzędnych dostawców tożsamości, którzy dodają deklaracje dotyczące użytkownika. Używaj tylko ze znanymi zakresami CIDR proxy i ścisłymi listami dozwolonych nagłówków, aby zapobiec fałszowaniu nagłówków tożsamości.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Tożsamość GitHub w Cloudflare Access OIDC`},help:{"v1-1puth4k-6t":`Opcjonalna zweryfikowana tożsamość GitHub od wybranego dostawcy Cloudflare Access OIDC. Wymaga standardowych nagłówków Access z adresem e-mail i asercją. Przy braku deklaracji profile pozostają oparte wyłącznie na adresie e-mail; istniejące role profili i preferencje współautorstwa zostają zachowane.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Deklaracja identyfikatora konta GitHub`},help:{"v1-pcaaw7-57":`Dokładna nazwa przekazywanej deklaracji OIDC, której wartością jest zweryfikowany identyfikator konta GitHub w postaci ciągu znaków reprezentującego dodatnią liczbę dziesiętną. Skonfiguruj Access tak, aby przekazywał ją w oidc_fields; nigdy nie używaj niezweryfikowanej deklaracji, którą użytkownik może edytować.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Wystawca Cloudflare Access`},help:{"v1-gykv03-56":`Dokładny adres źródłowy HTTPS zaufanego zespołu Cloudflare Access, na przykład https://example.cloudflareaccess.com, bez końcowego ukośnika. Oświadczenia od innych wystawców nie dostarczają tożsamości GitHub.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Identyfikator dostawcy OIDC w Cloudflare Access`},help:{"v1-kbyo5w-44":`Dokładny identyfikator dostawcy tożsamości w Access dla zaufanej integracji OIDC. Sama nazwa wyświetlana dostawcy lub pasująca nazwa oświadczenia nie stanowi podstawy zaufania.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Automatyczne zatwierdzanie urządzeń przez zaufane proxy`},help:{"v1-uh32ha-6z":`Opcjonalna zasada automatycznego zatwierdzania nowych urządzeń operatora korzystających z interfejsu przeglądarkowego lub natywnego oraz rozszerzeń zakresu uprawnień dla tego samego klucza po uwierzytelnieniu przez zaufane proxy. Przyznawane uprawnienia są ograniczane przez deviceAutoApprove.scopes oraz nagłówek x-openclaw-scopes proxy, jeśli jest obecny.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Włączone automatyczne zatwierdzanie urządzeń przez zaufane proxy`},help:{"v1-1nntwls-78":`Automatycznie zatwierdza nowe urządzenia operatora korzystające z interfejsu przeglądarkowego lub natywnego oraz rozszerzenia zakresu uprawnień dla tego samego klucza po uwierzytelnieniu dozwolonego użytkownika przez odwrotne proxy. Domyślnie: false. Włącz tylko wtedy, gdy zabezpieczenia weryfikacji tożsamości na poziomie proxy są wystarczająco silne, aby zastąpić ręczne parowanie urządzeń.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Zakresy uprawnień automatycznego zatwierdzania urządzeń przez zaufany serwer proxy`},help:{"v1-raeila-g3":`Maksymalne zakresy uprawnień przyznawane automatycznie zatwierdzanym urządzeniom operatora. Domyślnie: operator.read, operator.write, operator.approvals i operator.questions. Żądane zakresy są ograniczane do tej listy; żądania bez zakresów otrzymują zakresy z tej listy. Jeśli nie ustawiono wartości, automatyczne zatwierdzanie dodaje również operator.questions dla starszych klientów interfejsu; jawnie określona lista nigdy nie jest rozszerzana. Jawne dodanie operator.admin pozwala każdemu użytkownikowi uwierzytelnionemu przez serwer proxy automatycznie zatwierdzać pełne uprawnienia administratora i sprawia, że żądania bez zakresów automatycznie otrzymują pełne uprawnienia administratora. Powoduje to również zgłoszenie krytycznego problemu w audycie bezpieczeństwa oraz ostrzeżenie przy uruchamianiu Gateway.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Tryb nasłuchiwania Gateway`},help:{"v1-1unqude-4y":`Profil nasłuchiwania w sieci: "auto", "lan", "loopback", "custom" lub "tailnet", określający dostępność interfejsów. Zachowaj "loopback", aby działać wyłącznie lokalnie; "auto" może udostępnić wszystkie interfejsy.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`Agenci CLI`},help:{"v1-1qqo8m2-5a":`Wykrywanie w Control UI zewnętrznych silników sesji CLI udostępnianych przez katalog sesji Gateway. Domyślnie włączone; wyłącz, aby uniemożliwić uruchamianie tych silników z selektora modelu nowej sesji.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`Agenci CLI włączeni`},help:{"v1-ufu7fx-8p":`Przy wartości true pokazuje agentów CLI z katalogu w selektorze modelu nowej sesji w Control UI (domyślnie: true). Ustaw false, aby wyłączyć agentów CLI i tworzenie natywnych sesji CLI. Wyświetlane są tylko katalogi, które deklarują możliwość tworzenia sesji, a selektor pozostaje ukryty, gdy Gateway nie deklaruje obsługi katalogu sesji.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Ustawienia hostowania Control UI, w tym włączanie, ścieżki i wzmacnianie zabezpieczeń pochodzenia żądań przeglądarki oraz uwierzytelniania. Ogranicz dostępność interfejsu do minimum i zastosuj silne mechanizmy uwierzytelniania przed udostępnieniem go w internecie.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Dozwolone źródła dla Control UI`},help:{"v1-1stgitk-9i":`Dozwolone źródła żądań przeglądarki dla połączeń WebSocket Control UI/WebChat (wyłącznie pełne adresy źródeł, np. https://control.example.com). Wymagane przy wdrożeniach Control UI poza interfejsem pętli zwrotnej, chyba że jawnie włączono niebezpieczny mechanizm zastępczy oparty na nagłówku Host. Ustawienie ["*"] zezwala na dowolne źródło żądań przeglądarki i należy go unikać poza ściśle kontrolowanymi testami lokalnymi.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Zezwalaj na zewnętrzne adresy URL osadzane w Control UI`},help:{"v1-obwpfg-6s":`NIEBEZPIECZNY przełącznik umożliwiający hostowanym osadzonym treściom ładowanie bezwzględnych zewnętrznych adresów URL http(s). Pozostaw go wyłączonego, chyba że celowo osadzasz w Control UI zaufane strony innych podmiotów; hostowane dokumenty /__openclaw__/canvas i /__openclaw__/a2ui nie wymagają tej opcji.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Automatycznie pobieraj ikony witryn dla linków`},help:{"v1-bn9u34-ag":`Pobieraj favikony linków i podglądy społecznościowe kart przeglądarki za pośrednictwem Gateway (domyślnie włączone). Kafelki kart przeglądarki wczytują publiczne metadane stron i zadeklarowane obrazy bez użycia plików cookie przeglądarki ani danych uwierzytelniających witryn. Wszystkie żądania podlegają rygorystycznym kontrolom ochrony przed SSRF, a przetwarzanie kodu HTML i obrazów jest ograniczone. Ustaw false, aby wyłączyć automatyczne pobieranie zarówno favikon, jak i podglądów stron; nie ma to wpływu na zrzuty ekranu przeglądarki na żywo.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Ścieżka bazowa Control UI`},help:{"v1-1dx68ar-1w":`Opcjonalny prefiks adresu URL, pod którym udostępniany jest Control UI (np. /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Zaproszenie do społeczności w Control UI`},help:{"v1-1rz3zsx-73":`Pokazuje zaproszenie do społeczności Discord w Control UI udostępnianym przez ten Gateway (domyślnie włączone). Ustaw false, aby ukryć je we wszystkich przeglądarkach korzystających z tego wdrożenia interfejsu. Zmiany są stosowane po odświeżeniu strony lub ponownym połączeniu; ponowne włączenie zachowuje informacje o odrzuceniu zaproszenia zapisane lokalnie w przeglądarkach.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Niebezpieczne zezwolenie na zastępcze ustalanie pochodzenia na podstawie nagłówka Host`},help:{"v1-1t1qi4c-7v":`NIEBEZPIECZNY przełącznik, który włącza zastępcze ustalanie pochodzenia na podstawie nagłówka Host podczas sprawdzania połączeń WebSocket Control UI/WebChat. Ten tryb jest obsługiwany, gdy wdrożenie celowo korzysta z zasad pochodzenia opartych na nagłówku Host; jawne ustawienie gateway.controlUi.allowedOrigins pozostaje zalecanym, bezpieczniejszym ustawieniem domyślnym.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Tryb piaskownicy dla osadzonych treści w Control UI`},help:{"v1-d54l3a-7c":'Zasady piaskownicy iframe dla osadzonych treści w hostowanym Control UI. "strict" wyłącza skrypty, "scripts" zezwala na interaktywne osadzone treści przy zachowaniu izolacji pochodzenia (domyślnie), a "trusted" dodaje `allow-same-origin` dla dokumentów z tej samej witryny, które celowo wymagają większych uprawnień.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI włączony`},help:{"v1-1hhyymc-4w":`Wartość true włącza udostępnianie Control UI usługi Gateway przez jej proces HTTP. Pozostaw włączone na potrzeby lokalnej administracji i wyłącz, gdy zastępuje je zewnętrzny interfejs sterowania.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Środowisko Control UI`},help:{"v1-paarso-4n":`Opcjonalne publiczne oznaczenie środowiska widoczne na pasku Control UI, awatarze agenta, plakietkach etykiet, w tytule przeglądarki i na ikonie witryny. Pomiń je, aby zachować domyślny wygląd.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Kolor środowiska w Control UI`},help:{"v1-mp6cta-2i":`Nazwana paleta kolorów środowiska: teal, amber, purple, coral, pink, blue, green, red lub gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Etykieta środowiska w Control UI`},help:{"v1-1njve3z-3z":`Etykieta środowiska wyświetlana w Control UI i na karcie przeglądarki; białe znaki na początku i końcu są usuwane, a etykieta musi zawierać od 1 do 24 znaków.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Eksperymentalne funkcje Control UI`},help:{"v1-1qobi2m-3g":`Opcjonalne funkcje eksperymentalne Control UI. Mogą się zmieniać między wydaniami i pozostają wyłączone, dopóki nie zostaną jawnie włączone.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Interfejs niestandardowych wtyczek`},help:{"v1-108u6ts-9e":`Zezwól wtyczkom zainstalowanym przez użytkownika na wykonywanie natywnego kodu JavaScript w Control UI (domyślnie: false). Widoki wtyczek dołączonych do aplikacji pozostają dostępne. Niestandardowy interfejs korzysta z uprawnień zalogowanego operatora do Gateway; włączaj go tylko dla zaufanych wtyczek. Zmiany są stosowane bez ponownego uruchamiania Gateway. Odśwież otwarte strony Control UI, aby usunąć wcześniej załadowany kod wtyczek.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Poświadczenie usługi GitHub dla Control UI`},help:{"v1-1p31phh-d6":`Poświadczenie usługi oparte na SecretRef, używane do wykrywania projektów w Control UI i wyświetlania podglądów GitHub po najechaniu kursorem, bez tożsamości zarządzanej. Podglądy preferują skonfigurowaną tożsamość GitHub wybranego agenta i dziedziczą tożsamość systemową, jeśli nie została ona nadpisana. Preferuj jawną konfigurację, aby jasno określić właściciela usługi. Pomiń to ustawienie, aby zachować możliwość użycia GH_TOKEN/GITHUB_TOKEN ze współdzielonego środowiska procesu Gateway. Jeśli jawnie skonfigurowane poświadczenie jest niedostępne, dostęp zostaje zablokowany.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Katalog główny zasobów Control UI`},help:{"v1-elck04-25":`Opcjonalny katalog główny w systemie plików dla zasobów Control UI (domyślnie dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Obserwator sesji Control UI`},help:{"v1-1ahs80-8a":`Generuj na bieżąco podsumowania stanu sesji dla subskrybujących klientów Control UI, używając modelu pomocniczego każdego agenta (domyślnie włączone). Ustaw false, aby wyłączyć wywołania modelu obserwatora w całym Gateway; ustawienie agents.defaults.utilityModel na pusty ciąg wyłącza obserwację przez model pomocniczy dla agentów, którzy nie nadpisują tego ustawienia.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Niestandardowy host nasłuchiwania Gateway`},help:{"v1-lwjcyo-4d":`Adres IPv4 używany do niestandardowego powiązania nasłuchiwania. Konkretne adresy IPv4 wymagają również tego samego portu Gateway pod adresem 127.0.0.1; unikaj 0.0.0.0, chyba że wymagane jest udostępnienie na wszystkich interfejsach.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`API HTTP Gateway`},help:{"v1-ebtex7-4j":`Konfiguracja API HTTP Gateway obejmująca przełączniki punktów końcowych i ustawienia udostępniania API na poziomie transportu. Włączaj tylko wymagane punkty końcowe, aby ograniczyć powierzchnię ataku.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Punkty końcowe HTTP Gateway`},help:{"v1-1a0r104-55":`Przełączniki funkcji punktów końcowych HTTP w interfejsie API Gateway dla tras zgodności i opcjonalnych integracji. Włączaj punkty końcowe świadomie i monitoruj wzorce dostępu po wdrożeniu.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`Punkt końcowy OpenAI Chat Completions`},help:{"v1-1271mpb-2b":"Włącz punkt końcowy `POST /v1/chat/completions` zgodny z OpenAI (domyślnie: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Limity obrazów w OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Ustawienia pobierania i walidacji obrazów dla elementów `image_url` zgodnych z OpenAI."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Lista dozwolonych typów MIME obrazów w OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Dozwolone typy MIME dla elementów `image_url` (lista bez rozróżniania wielkości liter)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Zezwalaj na adresy URL obrazów w OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Zezwalaj na pobieranie z adresów URL po stronie serwera dla elementów `image_url` (domyślnie: false; identyfikatory URI danych pozostają obsługiwane). Ustaw `false`, aby całkowicie wyłączyć pobieranie z adresów URL."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Maksymalna liczba bajtów obrazu w OpenAI Chat Completions`},help:{"v1-d920yx-1s":"Maksymalna liczba bajtów na pobrany lub zdekodowany obraz `image_url` (domyślnie: 10 MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Maksymalna liczba przekierowań dla obrazów w OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Maksymalna liczba przekierowań HTTP dozwolonych podczas pobierania z adresów URL `image_url` (domyślnie: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Limit czasu pobierania obrazów w OpenAI Chat Completions (ms)`},help:{"v1-89w2b9-1x":"Limit czasu w milisekundach dla pobierania z adresów URL `image_url` (domyślnie: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Lista dozwolonych adresów URL obrazów w OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Opcjonalna lista dozwolonych nazw hostów dla pobierania z adresów URL `image_url`; obsługuje dokładne nazwy hostów i wzorce wieloznaczne `*.example.com`. Pusta lub pominięta lista oznacza brak ograniczeń dotyczących nazw hostów."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Nagłówki zabezpieczeń HTTP Gateway`},help:{"v1-n8z1hb-44":`Opcjonalne nagłówki zabezpieczeń odpowiedzi HTTP stosowane przez sam proces Gateway. Jeśli połączenia TLS kończą się na odwrotnym serwerze proxy, zaleca się ustawienie tych nagłówków właśnie tam.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Nagłówek wymuszający bezpieczny transport`},help:{"v1-1buwhc3-3v":`Wartość nagłówka odpowiedzi Strict-Transport-Security. Ustawiaj tylko dla źródeł HTTPS, nad którymi masz pełną kontrolę; użyj false, aby jawnie wyłączyć.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Tryb Gateway`},help:{"v1-nfjirv-5m":`Tryb działania Gateway: "local" uruchamia kanały i środowisko wykonawcze agenta na tym hoście, a "remote" łączy się za pomocą transportu zdalnego. Pozostaw "local", chyba że celowo korzystasz z rozdzielonej topologii ze zdalnym Gateway.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills węzłów Gateway włączone`},help:{"v1-1xwu6at-3g":`Akceptuj umiejętności publikowane przez sparowane węzły, gdy są połączone (domyślnie: true). Ustaw false, aby ignorować umiejętności publikowane przez węzły.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Tryb przeglądarki węzłów Gateway`},help:{"v1-oeu1nc-69":`Routing przeglądarki przez węzły ("auto" = preferuj przeglądarkę hosta, użyj jednego podłączonego węzła przeglądarki, gdy funkcja lokalna jest niedostępna; "manual" = wymagaj jawnego wyboru węzła lub skonfigurowanego przypisania; "off" = wyłącz routing przez węzły).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Przypisanie przeglądarki do węzła Gateway`},help:{"v1-1cykty2-1p":`Kieruj żądania przeglądarki do konkretnego węzła według jego identyfikatora lub nazwy (opcjonalnie).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Lista dozwolonych poleceń węzłów Gateway (dodatkowe polecenia)`},help:{"v1-6l4otb-5m":"Dodatkowe polecenia node.invoke dozwolone poza domyślnym zestawem Gateway (tablica ciągów znaków z poleceniami). Włączenie tutaj niebezpiecznych poleceń zmienia ustawienia istotne dla bezpieczeństwa i jest sygnalizowane przez `openclaw security audit`."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Lista zablokowanych poleceń węzłów Gateway`},help:{"v1-u7c8wx-53":"Nazwy poleceń węzłów, które mają być blokowane, nawet jeśli występują w deklaracjach węzła lub na domyślnej liście dozwolonych poleceń (wyłącznie dokładne dopasowanie nazwy polecenia, np. `system.run`; nie sprawdza treści poleceń powłoki wewnątrz tego polecenia)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Parowanie węzłów Gateway`},help:{"v1-gldsi2-4s":`Ustawienia zasad parowania węzłów. Automatyczne zatwierdzanie po weryfikacji SSH jest domyślnie włączone; automatyczne zatwierdzanie na podstawie CIDR pozostaje wyłączone, dopóki nie zostaną jawnie skonfigurowane listy dozwolonych, zaufanych zakresów CIDR lub adresów IP.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`Zakresy CIDR do automatycznego zatwierdzania parowania węzłów Gateway`},help:{"v1-1m6jsxj-6x":`Opcjonalna lista dozwolonych zakresów CIDR lub adresów IP do automatycznego zatwierdzania pierwszego parowania urządzeń z rolą węzła, bez żądanych zakresów uprawnień. Funkcja jest wyłączona, gdy lista nie jest ustawiona. Parowanie operatora, przeglądarki i Control UI oraz każde parowanie związane z rozszerzeniem roli, zakresu uprawnień, metadanych lub klucza publicznego nadal wymaga ręcznego zatwierdzenia.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Automatyczne zatwierdzanie lokalnego parowania węzłów Gateway`},help:{"v1-glzm36-41":`Zatwierdzaj zaufane parowanie lokalne i rozszerzenia dostępu bez pytania (domyślnie: true); ustaw false, aby zamiast wygody wymagać jawnego zatwierdzenia każdego urządzenia.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Weryfikacja SSH przy parowaniu węzłów Gateway`},help:{"v1-1e4da92-ct":"Automatyczne zatwierdzanie po weryfikacji SSH przy pierwszym parowaniu urządzeń z rolą węzła (domyślnie: włączone). Gateway łączy się zwrotnie przez SSH z hostem inicjującym parowanie (BatchMode, ścisła weryfikacja kluczy hosta) i zatwierdza je tylko wtedy, gdy wynik zdalnego polecenia `openclaw node identity` odpowiada kluczowi urządzenia oczekującego na zatwierdzenie. Ustaw false, aby wyłączyć weryfikację SSH (niezależnie od autoApproveCidrs, które pozostaje aktywne); aby parowanie wymagało wyłącznie ręcznego zatwierdzania, usuń także ustawienie autoApproveCidrs. Przekaż obiekt, aby nadpisać user/identity/timeoutMs/cidrs."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Narzędzia wtyczek węzłów Gateway`},help:{"v1-1c24iq3-28":`Określa, czy sparowane węzły mogą publikować deskryptory narzędzi wtyczek widoczne dla agenta.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Włączone narzędzia wtyczek węzłów Gateway`},help:{"v1-14lgfu6-47":`Akceptuj widoczne dla agenta deskryptory narzędzi wtyczek publikowane przez sparowane węzły (domyślnie: true). Ustaw false, aby ignorować i usunąć wszystkie narzędzia wtyczek publikowane przez węzły.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Port Gateway`},help:{"v1-for8t5-54":`Port TCP, na którym Gateway nasłuchuje żądań do API, Control UI i ścieżek wejściowych kanałów. Użyj dedykowanego portu i unikaj konfliktów z odwrotnymi serwerami proxy lub lokalnymi usługami deweloperskimi.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Portale Gateway`},help:{"v1-1v2lkw9-1c":`Ustawienia publikowania portali i prywatnego dostępu przychodzącego.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Prywatny dostęp przychodzący do portalu`},help:{"v1-20w4gq-69":`Opcjonalny prywatny odwrotny serwer proxy HTTPS obsługujący domenę wieloznaczną, zarządzany przez operatora. Przekazuj oryginalny nagłówek Host, ścieżki i żądania zmiany protokołu na WebSocket do dedykowanego nasłuchu na interfejsie pętli zwrotnej. Uwierzytelnianie portalu tokenem typu bearer pozostaje wymagane. Wymaga ponownego uruchomienia Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Domena wieloznaczna portalu`},help:{"v1-1ipbfad-53":`Sama domena DNS dla losowych subdomen portali (na przykład previews.example.net). Skonfiguruj prywatnie DNS z obsługą domeny wieloznacznej i HTTPS; nie używaj wspólnej przestrzeni nazw hostów z Gateway ani Control UI.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Port pętli zwrotnej dla ruchu przychodzącego portalu`},help:{"v1-1mb98cv-4g":`Dedykowany port HTTP na interfejsie pętli zwrotnej, odbierający ruch z prywatnego serwera proxy HTTPS z obsługą domen wieloznacznych. Musi być inny niż port Gateway. To port zaplecza, a nie publiczny port HTTPS.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Publiczny adres źródłowy Gateway`},help:{"v1-17vekvx-87":`Dostępny z zewnątrz adres źródłowy HTTPS usługi Gateway. HTTP jest dozwolony tylko dla localhost, 127.0.0.1 lub [::1]. Mechanizm MCP OAuth dla poszczególnych podmiotów wysyłających żądania używa go do tworzenia adresu URL wywołania zwrotnego pod ścieżką /oauth/mcp/callback; linki do sesji kanałów i linki do przeglądarek generowane przez wtyczki używają go do uzyskiwania dostępu do Control UI i tras Gateway.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Dostarczanie powiadomień push przez Gateway`},help:{"v1-h23oz7-5s":`Ustawienia dostarczania powiadomień push używane przez Gateway, gdy trzeba wybudzić sparowane urządzenia lub je powiadomić. Skonfiguruj tutaj APNs z usługą pośredniczącą dla oficjalnych kompilacji iOS; bezpośrednie uwierzytelnianie APNs dla kompilacji lokalnych lub ręcznych nadal opiera się na zmiennych środowiskowych.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Dostarczanie przez APNs w Gateway`},help:{"v1-4bbafr-4e":`Ustawienia dostarczania przez APNs dla urządzeń iOS sparowanych z tym Gateway. Użyj ustawień usługi pośredniczącej dla oficjalnych kompilacji z App Store, które rejestrują się za pośrednictwem zewnętrznej usługi przekazującej powiadomienia push.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Usługa pośrednicząca APNs w Gateway`},help:{"v1-7glbel-6x":`Ustawienia zewnętrznej usługi pośredniczącej do wysyłania powiadomień APNs. Gateway domyślnie korzysta z hostowanej usługi pośredniczącej OpenClaw lub z tej niestandardowej usługi na potrzeby push.test, sygnałów wybudzających i wybudzeń w celu ponownego połączenia, gdy sparowana oficjalna kompilacja aplikacji iOS opublikuje rejestrację obsługiwaną przez usługę pośredniczącą.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Bazowy adres URL usługi pośredniczącej APNs dla Gateway`},help:{"v1-1o8mgnq-69":`Opcjonalny niestandardowy bazowy adres URL HTTPS zewnętrznej usługi pośredniczącej APNs używanej przez oficjalne kompilacje aplikacji iOS z App Store. Powinien być zgodny z adresem URL usługi pośredniczącej wbudowanym w kompilację iOS, aby ruch związany z rejestracją i wysyłaniem trafiał do tego samego wdrożenia.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Limit czasu usługi pośredniczącej APNs dla Gateway (ms)`},help:{"v1-a0jkb1-4z":`Limit czasu w milisekundach dla żądań wysyłania z Gateway do usługi pośredniczącej APNs (domyślnie: 10000). Zwiększ go w przypadku wolniejszych usług pośredniczących lub sieci albo zmniejsz, aby szybciej kończyć nieudane próby wybudzenia.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Ponowne wczytywanie konfiguracji`},help:{"v1-d02mvq-4w":`Zasady ponownego wczytywania konfiguracji na bieżąco, określające sposób stosowania zmian i moment wyzwalania pełnego ponownego uruchomienia. Zachowaj tryb hybrydowy, aby zapewnić najbezpieczniejsze aktualizacje podczas pracy, chyba że debugujesz wewnętrzne mechanizmy ponownego wczytywania.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Tryb ponownego wczytywania konfiguracji`},help:{"v1-1q1etcf-3m":`Określa sposób stosowania zmian konfiguracji: "off" ignoruje zmiany wprowadzane na bieżąco, a "hybrid" stosuje zmiany bezpieczne do wprowadzenia podczas pracy, a następnie w razie potrzeby uruchamia ponownie.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Zdalny Gateway`},help:{"v1-6xv7gd-5a":`Ustawienia połączenia ze zdalnym Gateway przez transport bezpośredni lub SSH, gdy ta instancja pośredniczy w komunikacji z innym hostem środowiska wykonawczego. Używaj trybu zdalnego tylko wtedy, gdy celowo skonfigurowano pracę na oddzielnych hostach.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Nagłówki uwierzytelniania brzegowego zdalnego Gateway`},help:{"v1-jg9p7d-5o":`Nagłówki HTTP oparte na sekretach, przekazywane do serwera proxy weryfikującego tożsamość, który działa przed skonfigurowanym zdalnym Gateway. Nagłówki są wysyłane wyłącznie do dokładnego źródła wskazanego przez gateway.remote.url przez WSS i nigdy nie są przekazywane przy przekierowaniach.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Hasło zdalnego Gateway`},help:{"v1-16jc0yx-7y":`Współdzielony sekret wysyłany w polu password w celu uwierzytelnienia tego klienta w zdalnym Gateway. Ustawienie gateway.auth.mode serwera określa używany sekret; akceptowane jest zarówno pole token, jak i password klienta. Zarządzaj tym sekretem zewnętrznie i unikaj zapisywania go jawnym tekstem w konfiguracji zatwierdzanej w repozytorium.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Zasady weryfikacji klucza hosta SSH zdalnego Gateway`},help:{"v1-7qoxtb-49":`Zasady weryfikacji klucza hosta SSH w macOS. "strict" wymaga już zaufanego klucza hosta; "openssh" jawnie przekazuje weryfikację do obowiązującej konfiguracji OpenSSH.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Tożsamość SSH zdalnego Gateway`},help:{"v1-hz2hsm-1f":`Opcjonalna ścieżka do pliku tożsamości SSH (przekazywana do ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Cel SSH zdalnego Gateway`},help:{"v1-85w39w-2t":`Zdalny Gateway przez SSH (tuneluje port Gateway do localhost). Format: user@host lub user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Odcisk TLS zdalnego Gateway`},help:{"v1-1ri16lk-23":`Oczekiwany odcisk sha256 TLS zdalnego Gateway (przypnij go, aby zapobiec atakom MITM).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Token zdalnego Gateway`},help:{"v1-1pb9q8w-7v":`Wspólny sekret wysyłany w polu token w celu uwierzytelnienia tego klienta w zdalnym Gateway. Ustawienie gateway.auth.mode serwera wybiera skonfigurowany sekret; akceptowane jest zarówno pole token, jak i password klienta. Przechowuj go przy użyciu podstawiania sekretów lub zmiennych środowiskowych i zmieniaj wraz ze zmianami uwierzytelniania zdalnego Gateway.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Transport zdalnego Gateway`},help:{"v1-1acfs7m-54":`Transport połączenia zdalnego: "direct" korzysta z połączenia przez skonfigurowany adres URL, natomiast "ssh" tworzy tunel przez SSH. Użyj SSH, gdy potrzebujesz szyfrowanego tunelu bez udostępniania zdalnych portów.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`Adres URL zdalnego Gateway`},help:{"v1-va7exe-1b":`Adres URL WebSocket zdalnego Gateway (ws:// lub wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Role operatorów Gateway`},help:{"v1-b59sc5-6w":`Opcjonalne role operatorów powiązane z profilami dla zespołowych instancji Gateway. Każda nazwana rola kontroluje dostęp do sesji innych osób, izolację środowiska testowego, agentów sesji i uruchomień oraz przyznane zakresy uprawnień operatora; pominięcie tej sekcji zachowuje dotychczasowe zachowanie operatorów.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Domyślna rola operatora`},help:{"v1-1v8add8-4u":`Wymagana rola przypisywana uwierzytelnionym profilom bez prawidłowego jawnego przypisania, gdy skonfigurowano role operatorów. Jej nazwa musi odpowiadać skonfigurowanej definicji roli.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Definicje ról operatorów`},help:{"v1-uv91an-53":`Niepusty zestaw definicji ról nazwanych przez administratora, łączących zasady z zamkniętego zbioru dotyczące udostępniania sesji, izolacji środowiska testowego, dostępu do agentów i zakresów uprawnień operatora, stosowane do uwierzytelnionych profili użytkowników.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Definicja roli operatora`},help:{"v1-p8tfws-6q":`Jedna nazwana rola operatora. Każda definicja musi jawnie określać zasady współdzielenia sesji, dozwolonych agentów sesji i uruchomień oraz maksymalny zakres uprawnień operatora. Może też wymagać izolacji nowo tworzonych sesji w piaskownicy oraz określać wtyczkę zasad dostępu.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Wtyczka zasad dostępu dla roli operatora`},help:{"v1-1gq4q08-9n":`Opcjonalny, dokładny identyfikator wtyczki, której zasady dostępu do Gateway muszą autoryzować tę rolę. Dostęp jest odrzucany, gdy wtyczki brakuje, jest wyłączona, nie można jej załadować lub nie zapewnia aktualnej autoryzacji. Identyfikatory niedostępnych wtyczek pozostają prawidłowymi wartościami konfiguracji, dzięki czemu osoby z niezależnymi rolami personelu i właściciel Gateway mogą przywrócić dostęp. Pominięcie tego pola nie dodaje zależności od wtyczki.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Dozwoleni agenci roli operatora`},help:{"v1-fvun18-4v":`Agenci dostępni, gdy ta rola tworzy sesje lub rozpoczyna uruchomienia: ustaw "*", aby zezwolić na wszystkich agentów, podaj identyfikatory agentów, aby zezwolić tylko na nich, lub użyj pustej listy, aby wyłączyć obie możliwości.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Izolacja roli operatora w piaskownicy`},help:{"v1-sknx21-66":`Izolacja wykonywania dla nowo tworzonych sesji: "inherit" (domyślnie) stosuje zasady agenta; "required" trwale wymaga piaskownicy, nawet gdy tryb piaskownicy agenta jest wyłączony, i blokuje wykonywanie, jeśli backend jest niedostępny.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Maksymalny zakres uprawnień roli operatora`},help:{"v1-1selr2i-4s":`Zamknięta lista zakresów uprawnień operatora wyznaczająca maksymalne uprawnienia tej roli w ramach połączenia. Zakresy żądane, przyznane przez parowanie lub tożsamość oraz rozszerzone są ograniczane do części wspólnej z tą listą.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Dostęp roli operatora do sesji`},help:{"v1-hsoiop-45":`Uprawnienia do współdzielenia sesji przyznane tej roli w odniesieniu do sesji utworzonych przez inne uwierzytelnione osoby; własne sesje danej osoby pozostają dla niej dostępne.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Dostęp roli operatora do innych sesji`},help:{"v1-vf8umx-5r":`Dostęp do sesji innych osób: "none" ukrywa je, "view" pozwala je odczytywać, "suggest" umożliwia zgłaszanie sugestii, a "write" pozwala uczestniczyć. Jawnie przyznane członkostwo w sesji może zapewniać dodatkowy dostęp.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Tailscale dla Gateway`},help:{"v1-6ar9o-4x":`Ustawienia integracji z Tailscale dotyczące udostępniania przez Serve/Funnel i obsługi cyklu życia przy uruchamianiu i zamykaniu Gateway. Pozostaw wyłączone, chyba że wdrożenie celowo korzysta z ruchu przychodzącego przez Tailscale.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Tryb Tailscale dla Gateway`},help:{"v1-6l2099-5a":`Tryb publikowania w Tailscale: "off", "serve" lub "funnel" dla prywatnych lub publicznych ścieżek dostępu. Użyj "serve", aby zapewnić dostęp wyłącznie z sieci tailnet, a "funnel" tylko wtedy, gdy wymagana jest dostępność z publicznego internetu.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Zabezpieczenie migracji zewnętrznego Funnel w Tailscale dla Gateway`},help:{"v1-1mntkor-7q":`Przestarzałe zabezpieczenie migracji dla mode='serve'. Jeśli zewnętrzny Funnel nadal kieruje ruch do standardowego nasłuchu Gateway, OpenClaw pozostawia udostępnianie bez zmian i ostrzega, że do czasu skonfigurowania uwierzytelniania hasłem i zmiany trybu na 'funnel' można korzystać tylko z webhooków uwierzytelnianych przez wtyczki.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Terminal operatora`},help:{"v1-18f5rgm-8b":`Terminal operatora udostępniany w Control UI i klientach mobilnych: powłoka oparta na PTY na hoście Gateway, dostępna wyłącznie w sesjach operatora z zakresem uprawnień administratora. Uruchamia się w obszarze roboczym docelowego agenta. W przypadku agentów w pełni izolowanych (sandbox.mode 'all') dostęp jest odrzucany, aby nie udostępniać powłoki hosta bez ograniczeń.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Limit czasu odłączonej sesji terminala operatora`},help:{"v1-k6qbgr-9e":`Liczba sekund, przez które sesja terminala pozostaje aktywna po utracie połączenia (uśpienie laptopa, ponowne załadowanie strony). W tym czasie można ponownie dołączyć do niej przez terminal.attach i odtworzyć ostatnie dane wyjściowe. Ustaw 0, aby kończyć sesje natychmiast po utracie połączenia. Domyślnie: 300 (5 minut). Odłączone sesje nadal wykonują polecenia, więc skróć ten czas na hostach współdzielonych lub dostępnych z zewnątrz.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Włączony terminal operatora`},help:{"v1-1nez06v-7p":`Włącza terminal operatora dla klientów z uprawnieniami administracyjnymi (domyślnie: true). Udostępnia powłokę w przeglądarce lub na urządzeniu mobilnym ze środowiskiem procesu Gateway; ustaw false, aby ją wyłączyć we wdrożeniach, w których operatorzy z uprawnieniami administracyjnymi nie powinni mieć dostępu do powłoki hosta. Zmiany są stosowane bez ponownego uruchamiania Gateway.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Powłoka terminala operatora`},help:{"v1-19mfe6t-5i":`Plik wykonywalny powłoki uruchamianej przez terminal operatora. Pozostaw nieustawione, aby używać powłoki logowania hosta ($SHELL w systemach Unix, %ComSpec% w systemie Windows), lub wskaż konkretny interpreter, aby zapewnić spójne środowisko operatora.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`TLS w Gateway`},help:{"v1-1dx77dq-4z":`Ustawienia certyfikatu i klucza TLS do obsługi zakończenia połączeń HTTPS bezpośrednio w procesie Gateway. W środowisku produkcyjnym używaj jawnie wskazanych certyfikatów i unikaj udostępniania nieszyfrowanych połączeń w niezaufanych sieciach.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Automatyczne generowanie certyfikatu TLS dla Gateway`},help:{"v1-1ld6uiu-4w":`Automatycznie generuje lokalną parę certyfikat/klucz TLS, gdy nie skonfigurowano konkretnych plików. Używaj tylko w środowiskach lokalnych lub deweloperskich, a do obsługi ruchu produkcyjnego zastąp wygenerowany certyfikat właściwym certyfikatem.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Ścieżka do pakietu CA TLS dla Gateway`},help:{"v1-andqlu-52":`Opcjonalna ścieżka do pakietu certyfikatów CA służącego do weryfikacji klientów lub obsługi niestandardowych wymagań dotyczących łańcucha zaufania na brzegu sieci Gateway. Użyj tej opcji, gdy wdrożenie obejmuje prywatną infrastrukturę PKI lub niestandardowe łańcuchy certyfikatów.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Ścieżka do certyfikatu TLS dla Gateway`},help:{"v1-1wznaof-4q":`Ścieżka w systemie plików do pliku certyfikatu TLS używanego przez Gateway, gdy TLS jest włączony. Używaj zarządzanych ścieżek certyfikatów i zadbaj o zgodność automatycznego odnawiania z tą lokalizacją.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS włączony dla Gateway`},help:{"v1-ykhwp0-4o":`Włącza terminację TLS w punkcie nasłuchującym Gateway, dzięki czemu klienci łączą się bezpośrednio przez HTTPS/WSS. Pozostaw tę opcję włączoną przy bezpośrednim udostępnianiu w internecie lub na granicy z niezaufaną siecią.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Ścieżka do klucza TLS dla Gateway`},help:{"v1-15knri0-4i":`Ścieżka w systemie plików do pliku klucza prywatnego TLS używanego przez Gateway, gdy TLS jest włączony. Ogranicz uprawnienia dostępu do tego pliku klucza i regularnie wymieniaj klucz zgodnie z obowiązującą polityką bezpieczeństwa.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Polityka udostępniania narzędzi w Gateway`},help:{"v1-1ffol26-5a":`Polityka zezwalania na udostępnianie narzędzi lub jego blokowania na poziomie Gateway, która może ograniczać dostępność narzędzi podczas działania niezależnie od profili agentów i narzędzi. Użyj jej do ogólnych ograniczeń w sytuacjach awaryjnych i wzmacniania zabezpieczeń środowiska produkcyjnego.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Lista dozwolonych narzędzi w Gateway`},help:{"v1-163khb1-4y":`Jawna lista dozwolonych narzędzi na poziomie Gateway, przydatna, gdy podczas działania ma być dostępny tylko wąski zestaw narzędzi. Użyj jej w środowiskach z restrykcyjnymi zabezpieczeniami, w których zakres dostępnych narzędzi musi być ściśle kontrolowany.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Lista zablokowanych narzędzi w Gateway`},help:{"v1-1lhssnf-4o":`Jawna lista narzędzi blokowanych na poziomie Gateway, która blokuje ryzykowne narzędzia, nawet jeśli zezwalają na nie zasady niższego poziomu. Używaj reguł blokowania do reagowania w sytuacjach awaryjnych i wzmacniania ochrony wielowarstwowej.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`Zakresy CIDR zaufanych serwerów proxy Gateway`},help:{"v1-n5zcvf-4f":`Lista dozwolonych zakresów CIDR i adresów IP nadrzędnych serwerów proxy, które mogą dostarczać nagłówki przekazujące tożsamość klienta. Ogranicz tę listę, aby niezaufane węzły pośrednie nie mogły podszywać się pod użytkowników.`}},hooks:{label:{"v1-j9ywl7-5":`Punkty zaczepienia`},help:{"v1-1mzh0ry-5v":`Interfejs automatyzacji przychodzących webhooków służący do mapowania zdarzeń zewnętrznych na wybudzenia lub działania agentów w OpenClaw. Przed udostępnieniem go poza zaufanymi sieciami zabezpiecz go za pomocą jawnych reguł kontroli tokenów, sesji i agentów.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Dozwolone identyfikatory agentów dla hooków`},help:{"v1-hree88-7c":`Lista dozwolonych identyfikatorów agentów, do których ostatecznie mogą trafiać żądania i mapowania hooków, w tym przekierowania do domyślnego agenta, gdy pominięto agentId. Użyj jej, aby ograniczyć zdarzenia automatyzacji do dedykowanych agentów usługowych i zmniejszyć zasięg potencjalnych szkód w przypadku ujawnienia tokenu hooka.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Dozwolone prefiksy kluczy sesji dla hooków`},help:{"v1-b346oh-4r":`Lista dozwolonych prefiksów kluczy sesji dla przychodzących żądań hooków, gdy włączone są klucze dostarczane przez wywołującego. Używaj ściśle określonych prefiksów, aby zapobiec wstrzykiwaniu dowolnych kluczy sesji.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Zezwalaj na klucz sesji w żądaniach hooków`},help:{"v1-11n9ps-52":`Wartość true pozwala wywołującym podawać klucz sesji w żądaniach hooków, umożliwiając im sterowanie trasowaniem. Pozostaw wartość false, chyba że zaufani integratorzy wyraźnie potrzebują niestandardowego przypisywania do wątków sesji.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Domyślny klucz sesji dla hooków`},help:{"v1-bzdgkn-57":`Zapasowy klucz sesji używany przy dostarczaniu zdarzeń do hooków, gdy żądanie nie zawiera go w dozwolonych kanałach. Używaj stałego klucza o ograniczonym zakresie, aby uniknąć mieszania niepowiązanych rozmów automatyzacji.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Hooki włączone`},help:{"v1-1mixmjf-4n":`Włącza punkt końcowy hooków i potok wykonywania mapowań dla przychodzących żądań webhook. Pozostaw wyłączone, chyba że aktywnie kierujesz zdarzenia zewnętrzne do Gateway.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Hook Gmail`},help:{"v1-4cibmt-4r":`Ustawienia integracji push z Gmail używane do powiadomień Pub/Sub i opcjonalnej lokalnej obsługi wywołań zwrotnych. W miarę możliwości ogranicz tę integrację do kont Gmail przeznaczonych do automatyzacji.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Konto hooka Gmail`},help:{"v1-12l1h96-4v":`Identyfikator konta Google używany do operacji obserwowania i subskrypcji Gmail w tej integracji hooka. Używaj osobnego konta pocztowego do automatyzacji, aby odizolować uprawnienia operacyjne.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Hook Gmail: zezwalaj na niebezpieczne treści zewnętrzne`},help:{"v1-1w3gdvs-55":`Po włączeniu pozwala przekazywać do przetwarzania zewnętrzne treści Gmail poddane mniej rygorystycznemu oczyszczaniu. Pozostaw wyłączone dla większego bezpieczeństwa i włączaj tylko dla zaufanych strumieni poczty z kontrolowanymi przekształceniami.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`Adres URL wywołania zwrotnego hooka Gmail`},help:{"v1-19fhn6q-4z":`Publiczny adres URL wywołania zwrotnego, z którego Gmail lub pośrednicy korzystają do dostarczania powiadomień do tego potoku hooka. Chroń ten adres URL za pomocą weryfikacji tokenów i ograniczonej dostępności sieciowej.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Hook Gmail: dołącz treść wiadomości`},help:{"v1-14cf1c3-52":`Gdy ustawiono true, pobiera i dołącza treść wiadomości e-mail do dalszego mapowania lub przetwarzania przez agenta. Pozostaw false, chyba że treść wiadomości jest wymagana, ponieważ zwiększa to rozmiar przesyłanych danych i ich wrażliwość.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Etykieta hooka Gmail`},help:{"v1-9zpdg8-4g":`Opcjonalny filtr etykiet Gmail ograniczający, które oznaczone wiadomości wyzwalają zdarzenia hooka. Stosuj wąskie filtry, aby nie zalewać automatyzacji niepowiązaną korespondencją.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Maksymalna liczba bajtów treści dla hooka Gmail`},help:{"v1-2aaxx1-4b":`Maksymalna liczba bajtów danych Gmail przetwarzanych na zdarzenie, gdy opcja includeBody jest włączona. Stosuj ostrożne limity, aby ograniczyć koszty i ryzyko związane z przetwarzaniem zbyt dużych wiadomości.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Nadpisanie modelu hooka Gmail`},help:{"v1-1var65t-59":`Opcjonalne nadpisanie modelu dla uruchomień wyzwalanych przez Gmail, gdy automatyzacje skrzynki pocztowej powinny korzystać z dedykowanego zachowania modelu. Pozostaw nieustawione, aby dziedziczyć domyślne ustawienia agenta, chyba że zadania skrzynki pocztowej wymagają specjalizacji.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Token push hooka Gmail`},help:{"v1-h1vx01-4o":`Współdzielony tajny token wymagany w wywołaniach zwrotnych hooka push Gmail przed przetworzeniem powiadomień. Używaj podstawiania zmiennych środowiskowych i regularnie zmieniaj token, jeśli punkty końcowe wywołań zwrotnych są dostępne z zewnątrz.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Interwał odnawiania hooka Gmail (min)`},help:{"v1-pr1z9-49":`Częstotliwość odnawiania subskrypcji obserwowania Gmail w minutach, zapobiegająca ich wygaśnięciu. Ustaw interwał krótszy niż okres ważności określony przez dostawcę i monitoruj błędy odnawiania w dziennikach.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Lokalny serwer hooka Gmail`},help:{"v1-hom4wq-54":`Blok ustawień lokalnego serwera wywołań zwrotnych do bezpośredniego odbierania powiadomień Gmail bez osobnej warstwy ruchu przychodzącego. Włącz tylko wtedy, gdy ten proces ma samodzielnie obsługiwać ruch webhooków.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Adres nasłuchiwania serwera webhooków Gmail`},help:{"v1-55bieu-4d":`Adres nasłuchiwania lokalnego serwera HTTP wywołań zwrotnych Gmail używanego do bezpośredniej obsługi webhooków. Ogranicz nasłuchiwanie do interfejsu pętli zwrotnej, chyba że dostęp z zewnątrz jest celowo wymagany.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Ścieżka serwera webhooków Gmail`},help:{"v1-1jqhcw4-4h":`Ścieżka HTTP na lokalnym serwerze wywołań zwrotnych Gmail, pod którą przyjmowane są powiadomienia push. Zachowaj zgodność z konfiguracją subskrypcji, aby uniknąć utraty zdarzeń.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Port serwera webhooków Gmail`},help:{"v1-1yku7dz-43":`Port lokalnego serwera HTTP wywołań zwrotnych Gmail używany po włączeniu trybu serwowania. Użyj osobnego portu, aby uniknąć konfliktów z interfejsami Gateway i sterowania.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Subskrypcja webhooków Gmail`},help:{"v1-127h8vg-5b":`Subskrypcja Pub/Sub używana przez Gateway do odbierania powiadomień o zmianach w Gmail ze skonfigurowanego tematu. Jasno określ właściciela subskrypcji, aby wielu odbiorców nie rywalizowało nieoczekiwanie o wiadomości.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale dla webhooków Gmail`},help:{"v1-7jzidp-4l":`Blok konfiguracji udostępniania przez Tailscale do publikowania wywołań zwrotnych Gmail za pośrednictwem tras Serve/Funnel. Korzystaj z prywatnych trybów sieci tailnet przed włączeniem jakiejkolwiek publicznej ścieżki dostępu.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Tryb Tailscale dla webhooków Gmail`},help:{"v1-vhm395-4u":`Tryb udostępniania Tailscale dla wywołań zwrotnych Gmail: "off", "serve" lub "funnel". Użyj "serve" do dostarczania w prywatnej sieci tailnet, a "funnel" tylko wtedy, gdy wymagany jest dostęp z publicznego internetu.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Ścieżka Tailscale dla hooka Gmail`},help:{"v1-fr8qi-4m":`Ścieżka publikowana przez Tailscale Serve/Funnel do przekazywania wywołań zwrotnych Gmail po włączeniu tej funkcji. Utrzymuj jej zgodność z konfiguracją webhooka Gmail, aby żądania trafiały do oczekiwanej procedury obsługi.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Cel Tailscale dla hooka Gmail`},help:{"v1-1twwxge-47":`Adres docelowy lokalnej usługi, do której Tailscale Serve/Funnel przekazuje ruch (na przykład http://127.0.0.1:8787). Używaj jawnych adresów pętli zwrotnej, aby uniknąć niejednoznacznego routingu.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Nadpisanie poziomu rozumowania dla hooka Gmail`},help:{"v1-17owk9q-4z":`Nadpisanie poziomu wysiłku rozumowania dla uruchomień agenta wywoływanych przez Gmail: "off", "minimal", "low", "medium" lub "high". Stosuj umiarkowane wartości domyślne dla rutynowych automatyzacji skrzynki odbiorczej, aby kontrolować koszty i opóźnienia.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Temat Pub/Sub dla hooka Gmail`},help:{"v1-iled0e-4p":`Nazwa tematu Google Pub/Sub używanego przez mechanizm obserwowania Gmail do publikowania powiadomień o zmianach na tym koncie. Przed włączeniem obserwowania upewnij się, że uprawnienia IAM tematu zezwalają Gmail na publikowanie.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Hooki wewnętrzne`},help:{"v1-piq9k-4v":`Ustawienia środowiska wykonawczego hooków wewnętrznych dla dołączonych lub niestandardowych procedur obsługi zdarzeń ładowanych ze ścieżek modułów. Używaj ich do zaufanych automatyzacji wewnątrz procesu i ściśle ograniczaj zakres ładowanych procedur obsługi.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Hooki wewnętrzne włączone`},help:{"v1-1wv0289-4c":`Włącza przetwarzanie wewnętrznych hooków i skonfigurowanych wpisów w środowisku uruchomieniowym hooków wewnętrznych. Pozostaw wyłączone, chyba że hooki wewnętrzne zostały celowo skonfigurowane.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Wpisy hooków wewnętrznych`},help:{"v1-1ovi38l-4o":`Skonfigurowane wpisy hooków wewnętrznych służące do rejestrowania konkretnych procedur obsługi i metadanych w środowisku uruchomieniowym. Definiuj wpisy jawnie i stosuj wersjonowanie, aby umożliwić audyt zachowania w środowisku produkcyjnym.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Moduł ładujący hooki wewnętrzne`},help:{"v1-11re5ph-4p":`Ustawienia modułu ładującego hooki wewnętrzne określające, gdzie podczas uruchamiania wykrywane są moduły obsługi. Ogranicz katalogi główne ładowania, aby zmniejszyć ryzyko przypadkowych konfliktów lub przesłaniania modułów.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Dodatkowe katalogi hooków wewnętrznych`},help:{"v1-1xfdqxg-4c":`Dodatkowe katalogi przeszukiwane w poszukiwaniu modułów hooków wewnętrznych poza domyślnymi ścieżkami ładowania. Utrzymuj tę listę na minimalnym poziomie i kontroluj ją, aby zmniejszyć ryzyko przypadkowego przesłaniania modułów.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Mapowania hooków`},help:{"v1-frhp3v-5i":`Uporządkowane reguły mapowania, które dopasowują przychodzące żądania hooków i wybierają akcje wybudzenia lub agenta z opcjonalnym routingiem dostarczania. Umieszczaj szczegółowe mapowania jako pierwsze, aby reguły z ogólnymi wzorcami nie przechwytywały wszystkich żądań.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Akcja mapowania hooka`},help:{"v1-1r5zt5f-5f":`Typ akcji mapowania: "wake" uruchamia proces wybudzania agenta, a "agent" przekazuje żądanie bezpośrednio do obsługi przez agenta. Użyj "agent", aby wykonać je natychmiast, lub "wake", gdy preferowane jest przetwarzanie wyzwalane przez cykliczny sygnał aktywności.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`Identyfikator agenta w mapowaniu hooka`},help:{"v1-l0uioz-4y":`Identyfikator agenta docelowego wykonującego mapowanie, gdy routing akcji nie powinien używać ustawień domyślnych. Używaj dedykowanych agentów automatyzacji, aby oddzielić działanie webhooków od interaktywnych sesji operatora.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Zezwalaj na niebezpieczne treści zewnętrzne w mapowaniu hooka`},help:{"v1-1np9426-57":`Gdy wartość wynosi true, treść mapowania może zawierać w generowanych wiadomościach słabiej oczyszczone dane z zewnętrznych ładunków. Domyślnie pozostaw false i włączaj tylko dla zaufanych źródeł ze zweryfikowaną logiką transformacji.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Kanał dostarczania mapowania hooka`},help:{"v1-oz7pu5-5s":`Nadpisanie kanału dostarczania wyników mapowania (na przykład "last", "telegram", "discord", "slack", "signal", "imessage" lub "msteams"). Jawnie określaj nadpisania kanałów, aby uniknąć przypadkowego wysyłania do innych kanałów.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Dostarczaj odpowiedź mapowania hooka`},help:{"v1-12tbbam-5o":`Określa, czy wyniki wykonania mapowania są dostarczane do miejsca docelowego w kanale, czy przetwarzane bez wysyłania wiadomości. Wyłącz dostarczanie dla automatyzacji w tle, które nie powinny publikować wyników widocznych dla użytkowników.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Klucz rozdzielania mapowania hooka`},help:{"v1-1d593op-7e":`Klucz tablicy na najwyższym poziomie ładunku, na której elementy rozdzielane jest mapowanie: każdy element uruchamia osobną akcję, a szablony lub transformacje otrzymują ładunek, którego tablica zawiera tylko bieżący element. Ustawienie wstępne Gmail używa forEach: messages, dzięki czemu powiadomienia push wysyłane partiami uruchamiają jedno wykonanie na każdą wiadomość e-mail.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`Identyfikator mapowania hooka`},help:{"v1-q1t4zw-57":`Opcjonalny stały identyfikator wpisu mapowania hooka, używany do audytu, rozwiązywania problemów i ukierunkowanych aktualizacji. Używaj unikalnych identyfikatorów, aby logi i różnice w konfiguracji mogły jednoznacznie wskazywać mapowania.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Dopasowanie mapowania hooka`},help:{"v1-6u73k2-5a":`Obiekt grupujący warunki dopasowania mapowania, takie jak ścieżka i źródło, przed zastosowaniem routingu akcji. Określaj precyzyjne kryteria dopasowania, aby niepowiązany ruch webhooków nie uruchamiał automatyzacji.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Ścieżka dopasowania mapowania hooka`},help:{"v1-1d7dc5j-4k":`Warunek dopasowania ścieżki dla mapowania hooka, zwykle porównywany ze ścieżką przychodzącego żądania. Użyj go, aby zróżnicować działanie automatyzacji według grup ścieżek punktów końcowych webhooków.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Źródło dopasowania mapowania hooka`},help:{"v1-177zgy7-52":`Warunek dopasowania źródła dla mapowania hooka, zwykle ustalany na podstawie zaufanych metadanych z systemu źródłowego lub logiki adaptera. Używaj stałych identyfikatorów źródeł, aby routing pozostawał deterministyczny przy ponownych próbach.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Szablon wiadomości mapowania hooka`},help:{"v1-ggqszl-5c":`Szablon przekształcający ustrukturyzowane dane wejściowe mapowania w końcową treść wiadomości wysyłanej do docelowej ścieżki akcji. Dbaj o deterministyczność szablonów, aby dalsze parsowanie i działanie pozostawały stabilne.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Nadpisanie modelu mapowania hooka`},help:{"v1-10qyo4j-5e":`Opcjonalne nadpisanie modelu dla uruchomień wyzwalanych przez mapowanie, gdy automatyzacja powinna używać innego modelu niż domyślny model agenta. Używaj tej opcji oszczędnie, aby zachowanie pozostawało przewidywalne we wszystkich wykonaniach mapowania.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Nazwa mapowania hooka`},help:{"v1-zrd9tn-4v":`Czytelna nazwa wyświetlana mapowania, używana w diagnostyce i interfejsach konfiguracji dla operatorów. Stosuj krótkie i opisowe nazwy, aby cel routingu był oczywisty podczas analizy incydentów.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Klucz sesji mapowania hooka`},help:{"v1-lfnt1n-58":`Jawne nadpisanie klucza sesji dla wiadomości dostarczanych przez mapowanie w celu kontrolowania ciągłości wątku. Używaj stabilnych kluczy o określonym zakresie, aby powtarzające się zdarzenia były ze sobą powiązane bez przenikania do niepowiązanych rozmów.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Tryb sesji mapowania hooka`},help:{"v1-1ggtdze-5k":`Steruje ciągłością sesji mapowania: "isolated" rozpoczyna nową sesję uruchomienia, a "persistent" ponownie wykorzystuje ustalony sessionKey. Pozostaw isolated, chyba że integracja celowo wymaga trwałego kontekstu.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Szablon tekstu mapowania hooka`},help:{"v1-1rg732b-4y":`Zapasowy szablon tekstowy używany, gdy renderowanie danych w formacie wzbogaconym nie jest pożądane lub obsługiwane. Użyj go, aby zapewnić zwięzłe, spójne podsumowanie tekstowe do wyświetlania w interfejsach czatu.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Nadpisanie ustawienia rozumowania dla mapowania hooka`},help:{"v1-17hq8me-57":`Opcjonalne nadpisanie poziomu wysiłku rozumowania dla uruchomień wyzwalanych przez mapowanie, pozwalające dostosować kompromis między opóźnieniem a głębokością rozumowania. W przypadku hooków o dużym natężeniu ruchu utrzymuj niski lub minimalny poziom, chyba że wyraźnie wymagane jest głębsze rozumowanie.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Limit czasu mapowania hooka (s)`},help:{"v1-1r44ox2-4i":`Maksymalny dozwolony czas wykonywania akcji mapowania, po którym uruchamiana jest obsługa przekroczenia limitu czasu. Stosuj krótsze limity dla źródeł webhooków o dużym natężeniu ruchu, aby zapobiegać narastaniu kolejek.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Miejsce docelowe dostarczania dla mapowania hooka`},help:{"v1-1p7928e-55":`Identyfikator miejsca docelowego w wybranym kanale, używany, gdy odpowiedzi mapowania mają trafiać do stałego celu. Przed włączeniem mapowań w środowisku produkcyjnym sprawdź formaty miejsc docelowych wymagane przez dostawcę.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Transformacja mapowania hooka`},help:{"v1-14igxpm-5m":`Blok konfiguracji transformacji określający moduł i eksport do wstępnego przetwarzania przed obsługą akcji mapowania. Używaj transformacji wyłącznie ze zweryfikowanych ścieżek kodu i zachowuj deterministyczne działanie, aby zapewnić powtarzalność automatyzacji.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Eksport transformacji hooka`},help:{"v1-atn8v-4b":`Nazwany eksport wywoływany z modułu transformacji; w razie pominięcia używany jest domyślny eksport modułu. Ustaw tę opcję, gdy jeden plik zawiera wiele funkcji obsługi transformacji.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Moduł transformacji hooka`},help:{"v1-56futq-4v":`Względna ścieżka modułu transformacji wczytywanego z hooks.transformsDir w celu przekształcania przychodzących danych przed dostarczeniem. Moduły powinny być lokalne, zweryfikowane i pozbawione wzorców umożliwiających wyjście poza katalog bazowy.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Tryb wybudzania mapowania hooka`},help:{"v1-1dzqfnw-59":`Tryb planowania wybudzania: "now" wybudza natychmiast, a "next-heartbeat" odkłada wybudzenie do następnego cyklu sygnału kontrolnego. Używaj trybu odroczonego dla automatyzacji o niższym priorytecie, które tolerują niewielkie opóźnienie.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Ścieżka punktu końcowego hooków`},help:{"v1-1l9ijzv-4u":"Ścieżka HTTP używana przez punkt końcowy hooków (na przykład `/hooks`) na serwerze sterowania Gateway. Używaj trudnej do odgadnięcia ścieżki w połączeniu z weryfikacją tokenu, aby zapewnić ochronę wielowarstwową."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Zestawy ustawień hooków`},help:{"v1-dp8m0l-4v":`Nazwane zestawy ustawień hooków stosowane podczas wczytywania w celu ustanowienia standardowych mapowań i domyślnych zachowań. Jawnie określaj używane zestawy, aby operatorzy mogli kontrolować, które automatyzacje są aktywne.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Token uwierzytelniania hooków`},help:{"v1-1ihf6mv-82":`Współdzielony token typu bearer sprawdzany na wejściu hooków w celu uwierzytelnienia żądań przed uruchomieniem mapowań. Traktuj jego posiadaczy jako w pełni zaufanych wywołujących interfejs wejściowy hooków, a nie jako odrębną rolę bez uprawnień właściciela. Korzystaj z podstawiania zmiennych środowiskowych i regularnie wymieniaj token, gdy punkty końcowe webhooków są dostępne z internetu.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Katalog transformacji hooków`},help:{"v1-1ayj9p0-4t":`Katalog bazowy modułów transformacji hooków wskazywanych przez ścieżki transform.module w mapowaniach. Używaj kontrolowanego katalogu repozytorium, aby dynamiczne importy można było weryfikować i aby pozostawały przewidywalne.`}},logging:{label:{"v1-rq08xq-7":`Rejestrowanie`},help:{"v1-11an9pb-5e":`Ustawienia rejestrowania: poziom ważności, miejsca docelowe, formatowanie i maskowanie danych wrażliwych. W środowisku produkcyjnym stosuj odpowiednio restrykcyjne poziomy rejestrowania i maskowanie danych, zachowując przy tym informacje przydatne do diagnostyki.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Rejestr audytu`},help:{"v1-1lauvy2-6w":`Historia audytu o ograniczonym rozmiarze, zawierająca wyłącznie metadane, do przeglądu przez operatora. Rejestrowanie uruchomień i użycia narzędzi jest domyślnie włączone; rejestrowanie metadanych cyklu życia wiadomości wymaga osobnego włączenia ze względu na prywatność. Zapis w tle działa bez gwarancji kompletności i nie stanowi bezstratnego archiwum na potrzeby zgodności z przepisami.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Rejestr audytu włączony`},help:{"v1-snknxb-4v":`Rejestruje nowe zdarzenia audytu dotyczące uruchomień i narzędzi oraz włączone zdarzenia audytu wiadomości. Domyślnie: true. Zmiany obowiązują natychmiast; zaakceptowane operacje zapisu są kończone, a zachowane wiersze pozostają dostępne dla zapytań do czasu wygaśnięcia.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Audyt tożsamości wykonania`},help:{"v1-1ucirwv-5b":`Zachowuje ograniczone dane przypisania tożsamości wykonania na potrzeby inspekcji konkretnego uruchomienia. Domyślnie: false. Wymaga logging.audit.enabled i dotyczy nowo przyjętych uruchomień; istniejące konteksty pozostają bez zmian.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Zakres audytu wiadomości`},help:{"v1-1yg4lc3-76":`Steruje rejestrowaniem cyklu życia wiadomości bez ich treści: "off" (domyślnie), "direct" tylko dla rozpoznanych rozmów bezpośrednich lub "all" dla rozmów bezpośrednich, grupowych, na kanałach oraz rozmów nieznanego typu. Wymaga logging.audit.enabled. Zmiany dotyczą kolejnych zdarzeń cyklu życia.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Poziom rejestrowania w konsoli`},help:{"v1-16badbd-5u":`Próg poziomu logowania dla konsoli: "silent", "fatal", "error", "warn", "info", "debug" lub "trace" do sterowania wyjściem terminala. Użyj tego ustawienia, aby ograniczyć liczbę komunikatów w lokalnej konsoli, zachowując w razie potrzeby bardziej szczegółowe logi w pliku.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Styl logów konsoli`},help:{"v1-d7u0iq-3q":`Format wyjścia konsoli: "pretty" lub "json". Użyj json w potokach przetwarzania maszynowego, a pretty do pracy w terminalu, gdy priorytetem jest czytelność dla użytkownika.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Ścieżka pliku logów`},help:{"v1-16gaitv-4w":`Opcjonalna ścieżka pliku do trwałego zapisywania logów, dodatkowo do logowania w konsoli lub zamiast niego. Użyj zarządzanej ścieżki z uprawnieniami do zapisu i dostosuj przechowywanie oraz rotację logów do swojej polityki operacyjnej.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Poziom logowania`},help:{"v1-1r5yku0-5o":`Główny próg poziomu logowania dla komunikatów rejestrowanych podczas działania: "silent", "fatal", "error", "warn", "info", "debug" lub "trace". W środowisku produkcyjnym stosuj "info" lub "warn", a debug/trace używaj tylko podczas diagnozowania problemów.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Niestandardowe wzorce maskowania`},help:{"v1-1esa6eg-7k":`Niestandardowe wyrażenia regularne zastępują domyślną listę ciągów dla danych wyjściowych dzienników i transkrypcji oraz uzupełniają reguły ochrony danych w interfejsie użytkownika, narzędziach i diagnostyce. Wbudowana ochrona treści formularzy, ustrukturyzowanych danych uwierzytelniających i samych kluczy AWS obowiązuje zawsze. Użyj tej opcji, aby maskować tokeny i identyfikatory specyficzne dla danego wdrożenia.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Globalne definicje serwerów MCP zarządzane przez OpenClaw. Osadzony OpenClaw i inne adaptery środowisk wykonawczych mogą korzystać z tych serwerów bez zapisywania ich w ustawieniach projektu należących do środowiska wykonawczego.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`Aplikacje MCP`},help:{"v1-amyd91-38":`Obsługa interfejsu MCP Apps. Po włączeniu skonfigurowane serwery MCP mogą udostępniać interaktywne widoki HTML wyników swoich narzędzi.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps włączone`},help:{"v1-ghqy98-3w":`Opcjonalne renderowanie MCP Apps i most komunikacyjny między aplikacją a serwerem. Pozostaw wyłączone, chyba że ufasz skonfigurowanym serwerom MCP udostępniającym zasoby interfejsu aplikacji.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Źródło piaskownicy MCP Apps`},help:{"v1-1sxv3mf-6v":`Opcjonalne, dedykowane publiczne źródło HTTP(S) dla MCP Apps. Używaj go za odwrotnym serwerem proxy lub terminatorem TLS i przekazuj z niego ruch wyłącznie do skonfigurowanego portu piaskownicy MCP Apps. Musi różnić się od źródła Control UI i nie może udostępniać treści wymagających uwierzytelnienia.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Port piaskownicy MCP Apps`},help:{"v1-1b8n71l-4p":`Dedykowany port nasłuchiwania piaskownicy MCP Apps. Domyślnie jest to port Gateway powiększony o jeden. Ustaw nieużywany port, jeśli ten port jest już zajęty przez inną usługę lokalną lub profil Gateway.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`Serwery MCP`},help:{"v1-157ozoz-42":`Nazwane definicje serwerów MCP. OpenClaw przechowuje je we własnej konfiguracji, a adaptery środowiska wykonawczego określają podczas wykonywania, które mechanizmy transportu są obsługiwane.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`Uwierzytelnianie serwera MCP`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`Certyfikat klienta MCP`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`Klucz klienta MCP`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`Certyfikat klienta MCP`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`Klucz klienta MCP`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Odwzorowanie MCP w Codex`},help:{"v1-slcmq1-6x":`Metadane projekcji OpenClaw wyłącznie dla wątków Codex app-server. Nie wpływają na sesje ACP ani na ogólną konfigurację środowiska wykonawczego Codex. Pomiń ten blok, aby serwer był dostępny dla każdego agenta Codex app-server z domyślnym zachowaniem zatwierdzania MCP w Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Agenci MCP w Codex`},help:{"v1-8q98n8-67":`Opcjonalna, niepusta lista identyfikatorów agentów OpenClaw, które powinny otrzymać ten serwer MCP w konfiguracji wątku Codex app-server. Listy puste, zawierające wyłącznie białe znaki lub nieprawidłowe blokują dostęp; jeśli lista zostanie pominięta, serwer jest udostępniany wszystkim agentom Codex app-server.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Zatwierdzanie narzędzi MCP w Codex`},help:{"v1-1xql0qr-3d":`Natywna dla Codex nazwa tego samego trybu zatwierdzania narzędzi MCP dla poszczególnych serwerów. W konfiguracji OpenClaw zalecane jest użycie defaultToolsApprovalMode.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Zatwierdzanie narzędzi MCP w Codex`},help:{"v1-y5vsqq-3s":`Opcjonalny tryb zatwierdzania narzędzi MCP w Codex dla tego serwera: "auto", "prompt" lub "approve". Używaj tylko dla serwerów MCP, którym świadomie ufasz.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`Limit czasu nawiązywania połączenia MCP (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`Serwer MCP włączony`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`Profil uwierzytelniania OAuth MCP`},help:{"v1-fcrb4u-5z":`Identyfikator profilu uwierzytelniania z obsługą odświeżania, używanego do przekazywania bieżącego tokenu bearer do tego zdalnego serwera MCP. Gdy jest ustawiony, OpenClaw odszukuje i odświeża profil w czasie działania i nie przekazuje dalej danych służących do odświeżania.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`Adres URL metadanych klienta OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`Tożsamość OAuth MCP`},help:{"v1-1ie6ys7-59":`Własność danych uwierzytelniających OAuth dla tego serwera. Pomiń to pole lub użyj "shared" dla danych uwierzytelniających zarządzanych przez operatora; użyj "per-requester", aby każdy uwierzytelniony nadawca mógł połączyć własne konto.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`Adres URL przekierowania OAuth MCP`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`Zakres OAuth MCP`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Limit czasu żądania MCP (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`Weryfikacja TLS MCP`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`Weryfikacja TLS MCP`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Równoległe wywołania narzędzi MCP`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Równoległe wywołania narzędzi MCP`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`Wybór narzędzi MCP`},help:{"v1-10poyzb-4v":`Wybór narzędzi MCP dla poszczególnych serwerów. Użyj include, aby udostępnić tylko wybrane nazwy narzędzi MCP, lub exclude, aby ukryć wybrane nazwy narzędzi MCP. Wpisy obsługują dokładne nazwy i proste wzorce glob z '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Wykluczone narzędzia MCP`},help:{"v1-ijrc5y-1u":`Dokładne nazwy narzędzi MCP lub proste wzorce z symbolem wieloznacznym '*', które mają być ukryte na tym serwerze.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Uwzględnione narzędzia MCP`},help:{"v1-89fdfq-3o":`Dokładne nazwy narzędzi MCP lub proste wzorce z symbolem wieloznacznym '*', które mają być udostępniane z tego serwera. Jeśli pominięto, wszystkie narzędzia serwera pozostają dostępne, o ile nie zostały wykluczone.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL bezczynności sesji MCP (ms)`},help:{"v1-j9si74-87":`Opcjonalny czas bezczynności w milisekundach, po którym środowiska wykonawcze MCP sesji OpenClaw są usuwane. Brak wartości lub 0 utrzymuje środowiska aktywne do czasu wyczyszczenia sesji lub wyłączenia Gateway. Wartości dodatnie są zaokrąglane w dół; aktywne dzierżawy i oczekujące żądania uzyskania dostępu zapobiegają usunięciu. Środowiska należące do pojedynczego uruchomienia są nadal zamykane po jego zakończeniu.`}},memory:{label:{"v1-oopaku-6":`Pamięć`},help:{"v1-1wlx40m-13":`Konfiguracja wbudowanej pamięci (globalna).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Tryb odwołań do źródeł w pamięci`},help:{"v1-1q6dxr5-4u":`Steruje widocznością odwołań do źródeł w odpowiedziach: "auto" pokazuje je, gdy są przydatne, "on" pokazuje je zawsze, a "off" je ukrywa. Pozostaw "auto" jako ustawienie domyślne zapewniające równowagę między przydatnymi informacjami a szumem.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Wyszukiwanie w pamięci`},help:{"v1-1ukbud1-25":`Wyszukiwanie wektorowe w MEMORY.md i memory/*.md (obsługiwane jest nadpisywanie ustawień dla poszczególnych agentów).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Pamięć podręczna osadzeń wyszukiwania w pamięci`},help:{"v1-d8h2e4-5b":`Przechowuje obliczone osadzenia fragmentów w pamięci podręcznej SQLite, aby przyspieszyć ponowne indeksowanie i aktualizacje przyrostowe (domyślnie: true). Pozostaw tę opcję włączoną, chyba że sprawdzasz poprawność pamięci podręcznej lub minimalizujesz użycie dysku.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Typ danych wejściowych dokumentu dla wyszukiwania w pamięci`},help:{"v1-1ui33sv-5f":"Opcjonalna, specyficzna dla dostawcy wartość `input_type` dla osadzeń dokumentów i indeksowania pamięci. Używaj jej z punktami końcowymi asymetrycznych osadzeń zgodnymi z OpenAI, które wymagają etykiety fragmentu lub dokumentu."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Włącz wyszukiwanie w pamięci`},help:{"v1-14f11b9-4t":`Główny przełącznik indeksowania i wyszukiwania w pamięci dla tego profilu agenta. Pozostaw włączony, aby umożliwić semantyczne przywoływanie informacji, lub wyłącz, jeśli chcesz uzyskiwać odpowiedzi całkowicie bezstanowe.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Indeks sesji do wyszukiwania w pamięci (eksperymentalny)`},help:{"v1-qvhv8z-3i":`Indeksuje transkrypcje sesji na potrzeby wyszukiwania w pamięci. Zachowaj to zaawansowane nadpisanie, gdy dziedziczenie ustawień przywoływania informacji różni się między poziomem głównym a poszczególnymi agentami.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Dodatkowe ścieżki pamięci`},help:{"v1-ojqokq-7i":`Dodaje do indeksu pamięci dodatkowe katalogi lub pliki .md poza domyślnymi plikami pamięci. Wpisy mogą być ścieżkami w postaci ciągów znaków lub obiektami ze wzorcem glob względem katalogu głównego. Gdy pamięć multimodalna jest włączona, pasujące pliki obrazów i dźwięku w tych ścieżkach również mogą być indeksowane.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Dodatkowa ścieżka pamięci`},help:{"v1-b9mbq8-3m":`Ustawia dodatkowy katalog lub plik pamięci. Ścieżki względne są rozwiązywane względem obszaru roboczego agenta; pliki wskazane bezpośrednio są indeksowane dokładnie według wskazania.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Wzorzec dodatkowej ścieżki pamięci`},help:{"v1-j8br1v-4e":`Ogranicza wpis katalogu do obsługiwanych plików pasujących do tego wzorca glob względem katalogu głównego, na przykład "runbooks/**/*.md". Pomiń go, aby rekurencyjnie skanować wszystkie obsługiwane pliki.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Zapasowy dostawca wyszukiwania w pamięci`},help:{"v1-1r6368w-6p":`Zapasowy dostawca używany, gdy generowanie osadzeń przez głównego dostawcę się nie powiedzie: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" lub "none". Ustaw rzeczywistego dostawcę zapasowego, aby zapewnić niezawodność w środowisku produkcyjnym; używaj "none" tylko wtedy, gdy wolisz jawne zgłaszanie błędów.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Typ danych wejściowych wyszukiwania w pamięci`},help:{"v1-26vbwe-5u":"Używaj tej opcjonalnej, specyficznej dla dostawcy wartości `input_type` tylko wtedy, gdy ta sama etykieta ma dotyczyć żądań generowania osadzeń zarówno zapytań, jak i dokumentów. W przypadku dostawców asymetrycznych preferuj queryInputType i documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Ścieżka do lokalnego modelu osadzeń`},help:{"v1-13ymbnt-5q":"Określa źródło lokalnego modelu osadzeń do lokalnego wyszukiwania w pamięci, takie jak ścieżka do pliku GGUF lub URI `hf:`. Używaj tej opcji tylko wtedy, gdy provider ma wartość `local`, i sprawdź zgodność modelu przed przebudową dużych indeksów."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Model wyszukiwania w pamięci`},help:{"v1-11pohrl-59":`Model osadzeń zastępujący model domyślny wybranego dostawcy pamięci, gdy wymagany jest inny model. Ustaw tę opcję tylko wtedy, gdy potrzebujesz dostosować jakość wyszukiwania lub koszty poza domyślnymi ustawieniami dostawcy.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Multimodalne wyszukiwanie w pamięci`},help:{"v1-1jn02s-9e":'Opcjonalne ustawienia pamięci multimodalnej do indeksowania plików obrazów i dźwięku ze skonfigurowanych dodatkowych ścieżek. Pozostaw tę opcję wyłączoną, chyba że model osadzeń wyraźnie obsługuje osadzenia między modalnościami, a gdy jest włączona, ustaw `memory.search.fallback` na "none". Podczas indeksowania pasujące pliki są przesyłane do skonfigurowanego zdalnego dostawcy osadzeń.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Włącz multimodalne wyszukiwanie w pamięci`},help:{"v1-1dk5d7o-7e":`Włącza indeksowanie obrazów i dźwięku z extraPaths w pamięci. Obecnie wymaga Gemini embedding-2, pozostawia domyślne katalogi główne pamięci ograniczone do plików Markdown, wyłącza dostawców zapasowych wyszukiwania w pamięci i przesyła pasującą zawartość binarną do skonfigurowanego zdalnego dostawcy embeddingów.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Maksymalny rozmiar pliku multimodalnego w wyszukiwaniu w pamięci (bajty)`},help:{"v1-1mmdrvk-5d":`Ustawia maksymalną liczbę bajtów na plik multimodalny, po przekroczeniu której plik jest pomijany podczas indeksowania pamięci. Użyj tego ustawienia, aby ograniczyć koszty przesyłania i opóźnienia indeksowania, lub zwiększ limit dla krótkich nagrań dźwiękowych wysokiej jakości.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Modalności wyszukiwania multimodalnego w pamięci`},help:{"v1-alp4vh-4l":`Określa, które typy plików multimodalnych z extraPaths są indeksowane: "image", "audio" lub "all". Ogranicz ten wybór, aby uniknąć niezamierzonego indeksowania dużych zbiorów danych binarnych.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Wymiarowość wyjściowa wyszukiwania w pamięci`},help:{"v1-1f7zu53-93":`Nadpisuje rozmiar wektora wyjściowego dla embeddingów pamięci zgodnie z możliwościami dostawcy. Modele Gemini obsługują 128–3072 wymiary, a zalecane wartości to 768, 1536 lub 3072; rodziny modeli Bedrock, takie jak Titan V2, Cohere V4 i Nova, udostępniają własne dozwolone rozmiary. Zmiana tej wartości wymaga pełnego ponownego indeksowania, ponieważ wymiary przechowywanych wektorów muszą pozostać spójne.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Dostawca wyszukiwania w pamięci`},help:{"v1-5evseb-71":`Wybiera backend embeddingów używany do tworzenia wektorów pamięci i wykonywania na nich zapytań. Domyślnie: "openai"; ustaw "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" lub "local", aby użyć innego backendu.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Maksymalna liczba wyników wyszukiwania w pamięci`},help:{"v1-13ekath-4x":`Maksymalna liczba trafień w pamięci zwracanych przez wyszukiwanie przed dalszym ustalaniem rankingu i włączeniem do promptu. Zwiększ tę wartość, aby uzyskać szerszy zakres wyników, lub zmniejsz ją, aby uzyskać krótsze prompty i szybsze odpowiedzi.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Minimalna ocena wyników wyszukiwania w pamięci`},help:{"v1-1ww231l-4v":`Minimalny próg oceny trafności wymagany do uwzględnienia wyników z pamięci w końcowym zestawie przywołanych informacji. Zwiększ tę wartość, aby ograniczyć słabe lub nieistotne dopasowania, lub zmniejsz ją, aby złagodzić kryteria wyszukiwania.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Typ danych wejściowych zapytania wyszukiwania w pamięci`},help:{"v1-831yrv-4q":"Opcjonalna, zależna od dostawcy wartość `input_type` dla embeddingów pamięci tworzonych podczas zapytania. Używaj jej z punktami końcowymi asymetrycznych embeddingów zgodnymi z OpenAI, które wymagają etykiety zapytania."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Zapamiętywanie między rozmowami`},help:{"v1-k1itm8-7y":`Wykorzystuje istotny kontekst z innych prywatnych rozmów tego agenta poprzez chronione przywoływanie transkrypcji. Domyślnie włączone tylko wtedy, gdy globalne ustawienie session.dmScope nie jest określone lub ma wartość "main", a żadne powiązanie nie nadpisuje zakresu wiadomości prywatnych; każda skonfigurowana izolacja wiadomości prywatnych domyślnie wyłącza tę funkcję. Jawnie ustawiona wartość true lub false zawsze ma pierwszeństwo.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`Klucz API zdalnej usługi embeddingów`},help:{"v1-nfuuu-62":`Udostępnia dedykowany klucz API do zdalnych wywołań generowania osadzeń używanych przy indeksowaniu pamięci i przetwarzaniu zapytań. Użyj tej opcji, gdy osadzenia pamięci powinny korzystać z innych danych uwierzytelniających niż globalne wartości domyślne lub zmienne środowiskowe.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`Bazowy adres URL zdalnego generowania osadzeń`},help:{"v1-1ugvqgt-5p":`Zastępuje punkt końcowy API do generowania osadzeń, na przykład adresem serwera proxy zgodnego z OpenAI lub niestandardowym bazowym adresem URL Gemini. Używaj tej opcji tylko przy kierowaniu żądań przez własną bramę lub punkt końcowy dostawcy; w przeciwnym razie zachowaj domyślne ustawienia dostawcy.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Zdalne generowanie osadzeń w trybie wsadowym włączone`},help:{"v1-1fehqi-5x":`Włącza interfejsy API dostawcy do przetwarzania wsadowego zadań generowania osadzeń, jeśli są obsługiwane (OpenAI/Gemini), zwiększając przepustowość podczas większych operacji indeksowania. Pozostaw tę opcję włączoną, chyba że diagnozujesz błędy przetwarzania wsadowego u dostawcy lub wykonujesz bardzo małe zadania.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Nagłówki zdalnego generowania osadzeń`},help:{"v1-1uic0kd-5i":`Dodaje niestandardowe nagłówki HTTP do żądań zdalnego generowania osadzeń, łącząc je z domyślnymi nagłówkami dostawcy. Używaj tej opcji do uwierzytelniania na serwerze proxy i dodawania nagłówków routingu dzierżawców. Ogranicz wartości do minimum, aby uniknąć wycieku poufnych metadanych.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Źródła wyszukiwania w pamięci`},help:{"v1-btxtzg-57":`Określa, które źródła są indeksowane: "memory" odczytuje MEMORY.md + pliki pamięci, a "sessions" uwzględnia historię transkrypcji. Zachowaj ["memory"], chyba że potrzebujesz wyszukiwania we wcześniejszych transkrypcjach czatów.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Indeks wektorowy wyszukiwania w pamięci`},help:{"v1-fbybkj-37":`Steruje indeksem semantycznym sqlite-vec. Zachowaj to zaawansowane nadpisanie, gdy globalne zasady dotyczące wektorów różnią się od zasad dla poszczególnych agentów.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Ścieżka rozszerzenia wektorowego wyszukiwania w pamięci`},help:{"v1-1hysv5q-58":"Nadpisuje automatycznie wykrytą ścieżkę biblioteki rozszerzenia sqlite-vec (`.dylib`, `.so` lub `.dll`). Użyj tej opcji, gdy środowisko wykonawcze nie może automatycznie znaleźć sqlite-vec lub gdy chcesz używać konkretnej, sprawdzonej kompilacji."}},messages:{label:{"v1-1wwzqad-8":`Wiadomości`},help:{"v1-i5k0iw-5k":`Infrastruktura wiadomości i ustawienia domyślne wspólne dla agentów. Równorzędne sekcje na poziomie głównym odpowiadają za infrastrukturę i ustawienia domyślne wspólne dla agentów; agents.defaults odpowiada za zachowanie pętli agenta; wpisy poszczególnych agentów mogą nadpisywać oba rodzaje ustawień tam, gdzie jest to obsługiwane.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji reakcji potwierdzającej`},help:{"v1-1iip0zs-1x":`Reakcja emoji używana do potwierdzania wiadomości przychodzących (pusta wartość wyłącza tę funkcję).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Zakres reakcji potwierdzających`},help:{"v1-1jvdg5n-7s":`Określa, kiedy wysyłać reakcje potwierdzające ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" potwierdza wiadomości grupowe zawierające wzmiankę o agencie, niezależnie od tego, czy grupa wymaga wzmianek; "group-all" potwierdza każdą wiadomość grupową. "off"/"none" całkowicie wyłącza reakcje potwierdzające.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Zasady czatu grupowego`},help:{"v1-chqsvh-4l":`Ustawienia obsługi wiadomości grupowych, w tym wyzwalanie przez wzmianki i rozmiar okna historii. Stosuj precyzyjne wzorce wzmianek, aby nie wyzwalać agenta przy każdej wiadomości w kanałach grupowych.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Limit historii grupy`},help:{"v1-1mkbpw-9k":`Maksymalna liczba wcześniejszych wiadomości grupowych wczytywanych jako kontekst w każdej turze sesji grupowej. Wyższe wartości zapewniają lepszą ciągłość rozmowy, a niższe — szybsze i tańsze odpowiedzi. Automatyczna historia promptów jest ograniczona do 200 wiadomości. Maksymalna wartość liczby całkowitej w JSON wybiera domyślne okno historii kanału (50 dla współdzielonej historii grupy), a nie okno bez limitu.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Wzorce wzmianek w grupach`},help:{"v1-i7h7qc-6f":`Bezpieczne wzorce wyrażeń regularnych, które nie rozróżniają wielkości liter, używane do wykrywania bezpośrednich wzmianek i fraz wyzwalających w czatach grupowych. Używaj precyzyjnych wzorców, aby ograniczyć fałszywe trafienia w kanałach o dużym natężeniu ruchu; nieprawidłowe lub niebezpieczne wzorce z zagnieżdżonymi powtórzeniami są ignorowane.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Przychodzące wiadomości grupowe bez wzmianki`},help:{"v1-17wef8h-5f":`Określa sposób przekazywania wiadomości bez wzmianki z ciągle monitorowanych rozmów grupowych. "user_request" traktuje je jako żądanie użytkownika; "room_event" przekazuje je jako cichy kontekst, w którym wygenerowanie widocznej odpowiedzi wymaga narzędzia message.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Widoczne odpowiedzi w grupach`},help:{"v1-qa4z1s-aa":`Nadpisuje sposób obsługi odpowiedzi źródłowych tworzonych przez model w rozmowach grupowych i kanałach. Domyślnie przyjmuje wartość "automatic", gdy nie ustawiono globalnej polityki widocznych odpowiedzi. "message_tool" wymaga użycia message(action=send) do zwykłych odpowiedzi asystenta i ogólnych multimediów z narzędzi; dane wyjściowe środowiska wykonawczego jawnie przypisane do hosta nadal mogą być dostarczane, z wyjątkiem zdarzeń tła w pokoju. "automatic" publikuje zwykłe odpowiedzi tak jak wcześniej.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Opóźnienie scalania wiadomości przychodzących`},help:{"v1-ebyu5x-4a":`Ustawienia opóźnienia scalania wiadomości przychodzących stosowane bezpośrednio przed rozpoczęciem przetwarzania kolejki lub tury. Skonfiguruj je dla specyficznych dla dostawcy serii wiadomości wysyłanych szybko przez tego samego nadawcę.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Opóźnienie scalania wiadomości przychodzących według kanału (ms)`},help:{"v1-wbz54j-4g":`Nadpisania czasu grupowania wiadomości przychodzących dla poszczególnych kanałów, w milisekundach, z identyfikatorami dostawców jako kluczami. Użyj tej opcji, gdy niektórzy dostawcy wysyłają fragmenty wiadomości częściej niż inni.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Czas grupowania wiadomości przychodzących (ms)`},help:{"v1-1616yo2-7w":`Okno bezczynności (ms) służące do grupowania wiadomości przychodzących w krótkich odstępach od tego samego nadawcy. Telegram domyślnie używa 300 ms, jeśli nie ustawiono nadpisania globalnego ani dla kanału; pozostałe kanały domyślnie używają 0. Zero wyłącza standardowe grupowanie serii wiadomości, ale Telegram nadal scala fragmenty długich wiadomości o rozmiarze zbliżonym do limitu.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Kolejka wiadomości przychodzących`},help:{"v1-hm2o31-48":`Strategia kolejkowania wiadomości przychodzących podczas aktywnego wykonania w sesji. Użyj tej opcji, aby dostosować sterowanie przebiegiem, odroczone wiadomości uzupełniające, grupowanie lub przerywanie.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Tryb kolejki według kanału`},help:{"v1-4rf8z8-54":`Nadpisania trybu kolejki dla poszczególnych kanałów, z identyfikatorami dostawców jako kluczami (na przykład telegram, discord, slack). Użyj tej opcji, gdy charakter ruchu w danym kanale wymaga zachowania innego niż określone przez globalne ustawienia domyślne.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Pojemność kolejki`},help:{"v1-16ql8c7-4j":`Maksymalna liczba przychodzących elementów przechowywanych w kolejce przed zastosowaniem zasad odrzucania. Domyślnie 20; w kanałach o dużym natężeniu ruchu utrzymuj ograniczoną pojemność, aby zużycie pamięci pozostawało przewidywalne.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Zastępczy czas grupowania w kolejce według kanału (ms)`},help:{"v1-4tpyt7-4e":`Nadpisania czasu grupowania w kolejce dla poszczególnych kanałów, z identyfikatorami dostawców jako kluczami. Użyj tej opcji, aby niezależnie dostosować obsługę nagłych serii wiadomości w interfejsach czatu o różnym tempie komunikacji.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Strategia odrzucania z kolejki`},help:{"v1-ydb2rw-6m":`Strategia odrzucania po przekroczeniu limitu kolejki. "summarize" usuwa najstarsze wpisy, ale zachowuje zwięzłe podsumowania; "old" usuwa najstarsze wpisy bez podsumowań; "new" odrzuca najnowszy element. Użyj "summarize" w długich rozmowach, w których kontekst ma znaczenie.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Tryb kolejki`},help:{"v1-19k7gy1-67":`Tryb kolejki dla aktywnych wykonań. Użyj "steer", aby wprowadzać prompty do aktywnego wykonania, "followup", aby wykonać je później, "collect", aby później przetworzyć zgodne wiadomości zbiorczo, lub "interrupt", aby przerwać aktywne wykonanie przed rozpoczęciem przetwarzania najnowszego promptu.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Prefiks odpowiedzi wychodzących`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Domyślny tryb stopki ze statystykami użycia`},help:{"v1-l3shsx-dv":`Domyślny tryb stopki ze statystykami użycia w każdej odpowiedzi ("off"|"tokens"|"full"), ustawiany w sesjach, w których nie wybrano go za pomocą /usage. Akceptuje również "on" jako starszy alias dla "tokens". Akceptuje sam tryb lub mapę trybów dla poszczególnych kanałów z wartością zapasową "default". Kolejność pierwszeństwa: wartość sesji -> wpis kanału -> default -> off; jawny wybór za pomocą /usage (w tym off) jest zapisywany i zastępuje ustawienie domyślne. Użyj /usage reset (aliasy: inherit, clear, default), aby usunąć nadpisanie dla sesji i ponownie dziedziczyć tę skonfigurowaną wartość domyślną.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Reakcje statusu`},help:{"v1-193764l-3s":`Reakcje wskazujące status w cyklu działania, które aktualizują emoji przy wiadomości wyzwalającej w miarę postępów agenta (w kolejce → myślenie → narzędzie → gotowe/błąd).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Włącz reakcje statusu`},help:{"v1-1qnmmnc-7x":`Włącz reakcje wskazujące stan cyklu życia w obsługiwanych kanałach. Discord traktuje brak ustawienia jako włączenie, gdy reakcje potwierdzające są aktywne; Slack, Signal, Telegram i WhatsApp wymagają wartości true, aby używać reakcji cyklu życia. Slack domyślnie używa natywnego statusu wątku asystenta do wskazywania postępu.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Szablon stopki zużycia`},help:{"v1-1xibc23-47":`Niestandardowy szablon stopki /usage full, podany jako obiekt bezpośrednio w konfiguracji lub ścieżka do pliku JSON. Jeśli szablon jest nieprawidłowy lub niedostępny, używany jest wbudowany wiersz zużycia.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Widoczne odpowiedzi`},help:{"v1-7yfwc2-8t":`Steruje odpowiedziami źródłowymi tworzonymi przez model w rozmowach bezpośrednich, grupowych i na kanałach. "message_tool" wymaga message(action=send) do wysyłania zwykłych odpowiedzi asystenta i ogólnych multimediów z narzędzi; dane wyjściowe środowiska wykonawczego jednoznacznie należące do hosta nadal mogą być dostarczane, z wyjątkiem zdarzeń w tle w pokoju. "automatic" publikuje zwykłe odpowiedzi tak jak wcześniej.`}},meta:{label:{"v1-1xpfxac-m":`Metadane zgodności`},help:{"v1-1owqhgn-2w":`Metadane zgodności czytelne dla starszych wersji, zachowywane po to, aby starsze pliki wykonywalne mogły odrzucać niebezpieczne konwersje konfiguracji do starszego formatu.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Wersja ostatnio modyfikująca konfigurację`},help:{"v1-qykpv1-1i":`Wersja OpenClaw, która jako ostatnia zapisała tę konfigurację.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Znaczniki migracji konfiguracji`},help:{"v1-burt8q-1q":`Ograniczony zestaw znaczników zgodności dla ukończonych migracji konfiguracji.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Migracja listy dozwolonych modeli w zasadach`},help:{"v1-5psop1-1z":`Odnotowuje zachowanie lub ocenę ograniczeń starszej mapy modeli.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Migracja rozdzielająca modele pomocnicze`},help:{"v1-vzdfqx-2t":`Odnotowuje zachowanie dotychczasowych, niejawnie wybranych modeli głównych przed wydzieleniem wyboru modelu pomocniczego.`}},models:{label:{"v1-hzmwb-6":`Modele`},help:{"v1-1h1niol-5q":`Główna sekcja katalogu modeli obejmująca definicje dostawców, sposób scalania lub zastępowania oraz opcjonalną integrację wykrywania modeli Bedrock. Zadbaj o jawne i zweryfikowane definicje dostawców, zanim zaczniesz polegać na mechanizmach przełączania awaryjnego w środowisku produkcyjnym.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Odświeżanie katalogu modeli`},help:{"v1-1hess4t-40":`Steruje aktualizacjami dołączonego katalogu modeli w tle. Zdalne wpisy mogą aktualizować metadane modeli, ale nie mogą zmieniać punktów końcowych ani nagłówków dostawców.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Odświeżanie katalogu modeli włączone`},help:{"v1-1fogpjj-3j":`Pobiera w tle aktualizacje hostowanego katalogu modeli (domyślnie: true). Ustaw false, aby wyłączyć cały ruch sieciowy związany ze zdalnym katalogiem modeli.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`Adres URL odświeżania katalogu modeli`},help:{"v1-e02ai2-44":`Zastępuje adres URL hostowanego katalogu modeli adresem własnego serwera lustrzanego HTTPS (HTTP na localhost jest dozwolony do testów). Zmiany obowiązują po ponownym uruchomieniu Gateway.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Tryb katalogu modeli`},help:{"v1-1ofrnsp-es":`Steruje działaniem katalogu dostawców: "merge" zachowuje wbudowanych dostawców i nakłada na nich dostawców niestandardowych, a "replace" używa wyłącznie skonfigurowanych dostawców. W trybie "merge" zgodne identyfikatory dostawców zachowują niepuste wartości baseUrl z pliku models.json agenta, natomiast wartości apiKey są zachowywane tylko wtedy, gdy dostawca nie jest zarządzany przez SecretRef w bieżącym kontekście konfiguracji i profilu uwierzytelniania; dostawcy zarządzani przez SecretRef odświeżają apiKey na podstawie bieżących znaczników źródła, a dla wartości contextWindow/maxTokens zgodnych modeli wybierana jest wyższa wartość spośród wpisów jawnych i niejawnych.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Dostawcy modeli`},help:{"v1-1y5jg0v-8p":`Mapa dostawców indeksowana według identyfikatora dostawcy, zawierająca ustawienia połączenia i uwierzytelniania oraz definicje konkretnych modeli. Wbudowanych dostawców można dostosowywać za pomocą nadpisań na poziomie dostawcy; niestandardowi dostawcy muszą zawierać baseUrl i models. Używaj stałych kluczy dostawców, aby odwołania z agentów i narzędzi pozostawały przenośne między środowiskami.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Środowisko wykonawcze dostawcy modeli`},help:{"v1-1luy4fb-5o":`Opcjonalna niskopoziomowa polityka środowiska wykonawczego agenta dla tego dostawcy. Używaj polityki środowiska wykonawczego na poziomie dostawcy lub modelu zamiast przypisywania środowiska dla całego agenta; pominięcie lub wartość domyślna pozwala OpenClaw wybrać środowisko wykonawcze dla wybranego dostawcy.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`Identyfikator środowiska wykonawczego dostawcy modeli`},help:{"v1-1gusd9s-69":`Identyfikator środowiska wykonawczego agenta dostawcy: "openclaw", "auto", zarejestrowany identyfikator warstwy wykonawczej wtyczki, taki jak "codex", lub obsługiwany alias backendu CLI, taki jak "claude-cli". W przypadku OpenAI z oficjalnym punktem końcowym pominięcie tej wartości powoduje domyślne użycie warstwy wykonawczej Codex.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Adapter API dostawcy modeli`},help:{"v1-16c28rb-57":`Wybór adaptera API dostawcy sterującego obsługą zgodności żądań i odpowiedzi przy wywołaniach modeli. Używaj adaptera zgodnego z protokołem dostawcy nadrzędnego, aby uniknąć niezgodności funkcji.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Klucz API dostawcy modeli`},help:{"v1-1p84k96-54":`Dane uwierzytelniające dostawcy używane do uwierzytelniania za pomocą klucza API, gdy dostawca wymaga bezpośredniego uwierzytelniania kluczem. Korzystaj z podstawiania sekretów lub zmiennych środowiskowych i unikaj przechowywania rzeczywistych kluczy w plikach konfiguracyjnych zapisywanych w repozytorium.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Tryb uwierzytelniania dostawcy modeli`},help:{"v1-1l1lwxr-5p":`Wybiera sposób uwierzytelniania u dostawcy: "api-key" dla klucza API, "token" dla tokenu bearer, "oauth" dla danych uwierzytelniających OAuth oraz "aws-sdk" dla uzyskiwania danych uwierzytelniających AWS. Dopasuj to ustawienie do wymagań dostawcy.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Nagłówek Authorization dostawcy modeli`},help:{"v1-1gn3lt3-59":`Gdy ustawiono true, dane uwierzytelniające są wysyłane w nagłówku HTTP Authorization, nawet jeśli dostępna jest inna metoda uwierzytelniania. Używaj tego ustawienia tylko wtedy, gdy dostawca lub serwer proxy wyraźnie wymaga przekazywania nagłówka Authorization.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`Bazowy adres URL dostawcy modeli`},help:{"v1-1ku88v8-53":`Bazowy adres URL punktu końcowego dostawcy, który obsługuje żądania do modeli dla tego wpisu dostawcy. Używaj punktów końcowych HTTPS i w razie potrzeby dostosowuj adresy URL do środowiska za pomocą szablonów konfiguracji.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Nagłówki dostawcy modeli`},help:{"v1-chg59u-4x":`Statyczne nagłówki HTTP dołączane do żądań do dostawcy na potrzeby routingu dzierżawców, uwierzytelniania na serwerze proxy lub niestandardowych wymagań bramy. Używaj ich oszczędnie i przechowuj poufne wartości nagłówków w sekretach.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Wstrzykiwanie num_ctx u dostawcy modeli (zgodność z OpenAI)`},help:{"v1-53rmcr-6n":"Określa, czy OpenClaw wstrzykuje `options.num_ctx` dla dostawców Ollama skonfigurowanych z adapterem zgodnym z OpenAI (`openai-completions`). Domyślna wartość to true. Ustaw false tylko wtedy, gdy serwer proxy lub usługa nadrzędna odrzuca nieznane pola `options` w treści żądania."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Lokalna usługa dostawcy modeli`},help:{"v1-19zkcow-4y":`Opcjonalny proces lokalnego serwera modeli uruchamiany na żądanie dla tego dostawcy. OpenClaw sprawdza healthUrl, w razie potrzeby uruchamia polecenie, czeka na gotowość, a następnie wysyła żądanie do modelu.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Argumenty lokalnej usługi dostawcy modeli`},help:{"v1-t12wib-27":`Lista argumentów przekazywanych do polecenia lokalnego serwera modeli bez rozwijania przez powłokę.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Polecenie lokalnej usługi dostawcy modeli`},help:{"v1-1x6hz64-4j":`Bezwzględna ścieżka do pliku wykonywalnego procesu lokalnego serwera modeli. Podaj tę ścieżkę jawnie, aby uruchamianie dostawcy było deterministyczne i nie zależało od wyszukiwania w PATH przez powłokę.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Katalog roboczy lokalnej usługi dostawcy modeli`},help:{"v1-fi3xlx-1h":`Katalog roboczy procesu lokalnego serwera modeli.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Środowisko lokalnej usługi dostawcy modeli`},help:{"v1-1lwb9k1-3k":`Dodatkowe zmienne środowiskowe dla procesu lokalnego serwera modeli. Wartości wyglądające na poufne są maskowane w migawkach konfiguracji.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL sprawdzania stanu lokalnej usługi dostawcy modeli`},help:{"v1-jv7aw-35":`URL służący do sprawdzania gotowości przed wysłaniem żądań do modelu. Jeśli zostanie pominięty, OpenClaw użyje baseUrl dostawcy z dołączonym /models.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Zatrzymywanie lokalnej usługi dostawcy modeli przy bezczynności`},help:{"v1-1efg054-3z":`Czas w milisekundach, przez który lokalny serwer modeli uruchomiony przez OpenClaw pozostaje aktywny po zakończeniu ostatniego żądania. Ustaw 0, aby pozostawał aktywny do zamknięcia OpenClaw.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Limit czasu oczekiwania na gotowość lokalnej usługi dostawcy modeli`},help:{"v1-4gp0f0-2r":`Maksymalny czas w milisekundach oczekiwania na potwierdzenie gotowości lokalnego serwera modeli po uruchomieniu procesu.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Maksymalna liczba tokenów dostawcy modeli`},help:{"v1-fnj50y-38":`Domyślny maksymalny limit tokenów wyjściowych stosowany do modeli tego dostawcy, gdy wpis modelu nie określa maxTokens.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Lista modeli dostawcy`},help:{"v1-1vbm0gt-63":`Zadeklarowana lista modeli dostawcy, obejmująca identyfikatory, metadane, parametry specyficzne dla dostawcy oraz opcjonalne wskazówki dotyczące zgodności i kosztów. Identyfikatory muszą dokładnie odpowiadać wartościom w katalogu dostawcy, aby wybór i przełączanie na modele zapasowe działały prawidłowo.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Środowisko wykonawcze modelu`},help:{"v1-1k70g2n-3g":`Opcjonalna niskopoziomowa polityka środowiska wykonawczego agenta dla tego konkretnego modelu. Polityka środowiska wykonawczego modelu ma pierwszeństwo przed polityką środowiska wykonawczego dostawcy.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`Identyfikator środowiska wykonawczego modelu`},help:{"v1-1llzv33-42":`Identyfikator środowiska wykonawczego agenta modelu: "openclaw", "auto", zarejestrowany identyfikator warstwy wykonawczej wtyczki, taki jak "codex", lub obsługiwany alias backendu CLI, taki jak "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Multimedia wejściowe modelu`},help:{"v1-wxtj8e-2x":`Opcjonalne metadane dotyczące obsługi multimediów przez model, używane przez narzędzia do wyboru zachowawczych domyślnych ustawień kompresji obrazów.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Obrazy wejściowe modelu`},help:{"v1-1nviirq-3c":`Opcjonalne limity obrazów wejściowych dla tego modelu, takie jak maksymalna długość boku, maksymalna liczba pikseli i preferowana długość boku przy kompresji.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Maksymalny rozmiar obrazu dla modelu w bajtach`},help:{"v1-c2469j-23":`Maksymalny rozmiar zakodowanych danych obrazu akceptowany przez dostawcę dla tego modelu.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Maksymalna liczba pikseli obrazu dla modelu`},help:{"v1-9d6yqp-1u":`Maksymalna liczba pikseli obrazu akceptowana przez dostawcę dla tego modelu.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Maksymalna długość boku obrazu dla modelu`},help:{"v1-1gbci08-1y":`Maksymalna szerokość lub wysokość obrazu akceptowana przez dostawcę dla tego modelu.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Preferowana długość boku obrazu dla modelu`},help:{"v1-1u1mpcg-2x":`Preferowana długość boku przy skalowaniu obrazu w celu uzyskania zrównoważonej kompresji. Pozostaw bez ustawienia, aby użyć zachowawczej wartości domyślnej OpenClaw.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Tryb rozliczania tokenów obrazów modelu`},help:{"v1-1oy6z7v-1z":`Sposób rozliczania tokenów obrazów przez dostawcę: "tile", "detail" lub "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Parametry wykonawcze dostawcy modeli`},help:{"v1-464sgu-4t":`Parametry wykonawcze specyficzne dla dostawcy, interpretowane przez jego wtyczki. Używaj kluczy udokumentowanych przez dostawcę i kieruj się jego dokumentacją zamiast doraźnymi, ogólnymi założeniami.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Region dostawcy modeli`},help:{"v1-yq7rxk-5h":`Opcjonalny region wdrożenia/API dostawcy, interpretowany przez dostawców udostępniających regionalne punkty końcowe. Obsługiwane wartości znajdziesz w dokumentacji dostawcy; jeśli ustawiono zarówno region, jak i baseUrl, ustawienie baseUrl zwykle ma pierwszeństwo.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Nadpisania ustawień żądań do dostawcy modeli`},help:{"v1-1lkxryk-87":`Opcjonalne nadpisania ustawień żądań do dostawcy modeli, obejmujące dodatkowe nagłówki, nadpisania uwierzytelniania, routing przez proxy, ustawienia klienta TLS oraz opcjonalne allowPrivateNetwork dla zaufanych punktów końcowych hostowanych samodzielnie. Używaj ich tylko wtedy, gdy usługa nadrzędna lub ścieżka sieciowa w organizacji wymaga dostosowania transportu.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Zezwalaj na sieć prywatną w żądaniach do dostawcy modeli`},help:{"v1-1nbtcjk-fo":`Gdy ustawiono true, zezwala na żądania HTTP dostawcy modeli do zakresów prywatnych, CGNAT lub podobnych przez mechanizm ochronny pobierania HTTP dostawcy (fetchWithSsrFGuard). Niestandardowe lub lokalne bazowe adresy URL dostawców już ufają dokładnie skonfigurowanemu źródłu, z wyjątkiem źródeł metadanych, link-local i NAT64 do użytku lokalnego (64:ff9b:1::/48); ustaw false, aby wyłączyć to zaufanie. OpenAI Responses WebSocket wykorzystuje request do obsługi nagłówków/TLS, ale nie korzysta z tej ścieżki pobierania z ochroną SSRF. Używaj true tylko w przypadku samodzielnie hostowanych punktów końcowych kontrolowanych przez operatora, które muszą łączyć się z prywatnymi źródłami poza źródłem skonfigurowanym w baseUrl.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Nadpisanie uwierzytelniania żądań dostawcy modeli`},help:{"v1-ucdgnf-1w":`Nadpisuje sposób uwierzytelniania żądań dla tego dostawcy.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Nazwa nagłówka uwierzytelniania żądań dostawcy modeli`},help:{"v1-1881nqr-1i":`Niestandardowa nazwa nagłówka uwierzytelniania używana, gdy tryb uwierzytelniania to header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Tryb uwierzytelniania żądań dostawcy modeli`},help:{"v1-1lhv8hs-24":`Tryb nadpisania uwierzytelniania: "provider-default", "authorization-bearer" lub "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Prefiks nagłówka uwierzytelniania żądań dostawcy modeli`},help:{"v1-1rbm9lz-21":`Opcjonalny prefiks dodawany przed request.auth.value, gdy tryb uwierzytelniania to header.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Token Bearer żądań dostawcy modeli`},help:{"v1-6rcasw-1l":`Token Bearer używany, gdy tryb uwierzytelniania to authorization-bearer.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Wartość nagłówka uwierzytelniania żądań do dostawcy modeli`},help:{"v1-1v69ej-1j":`Niestandardowa wartość nagłówka uwierzytelniania używana, gdy tryb uwierzytelniania to header.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Nagłówki żądań do dostawcy modeli`},help:{"v1-zj3orj-2i":`Dodatkowe nagłówki dołączane do żądań do dostawcy po ustaleniu domyślnej atrybucji i danych uwierzytelniania.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Serwer proxy dla żądań do dostawcy modeli`},help:{"v1-md5uj8-4j":`Opcjonalne nadpisanie ustawień serwera proxy dla żądań do dostawcy modeli. Użyj "env-proxy", aby uwzględnić ustawienia serwera proxy ze środowiska, lub "explicit-proxy", aby kierować żądania przez określony adres URL serwera proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Tryb serwera proxy dla żądań do dostawcy modeli`},help:{"v1-1dx0ozg-29":`Tryb nadpisania ustawień serwera proxy dla żądań do dostawcy modeli: "env-proxy" lub "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`Ustawienia TLS serwera proxy dla żądań do dostawcy modeli`},help:{"v1-rdx62w-1v":`Opcjonalne ustawienia TLS używane podczas łączenia ze skonfigurowanym serwerem proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`Certyfikaty CA TLS serwera proxy dla żądań do dostawcy modeli`},help:{"v1-11pg2fd-1s":`Niestandardowy pakiet certyfikatów CA używany do weryfikacji łańcucha certyfikatów TLS serwera proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`Certyfikat TLS serwera proxy dla żądań do dostawcy modeli`},help:{"v1-x8nk2q-22":`Certyfikat TLS klienta przedstawiany serwerowi proxy, gdy wymagane jest wzajemne uwierzytelnianie TLS.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Pomijanie weryfikacji TLS serwera proxy dla żądań do dostawcy modeli`},help:{"v1-12vjdm9-2j":`Pomija weryfikację certyfikatu TLS serwera proxy. Używaj tylko w kontrolowanych środowiskach programistycznych.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`Klucz TLS serwera proxy dla żądań do dostawcy modeli`},help:{"v1-1skyr56-1w":`Klucz prywatny sparowany z request.proxy.tls.cert na potrzeby wzajemnego uwierzytelniania TLS z serwerem proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Hasło klucza TLS serwera proxy dla żądań do dostawcy modeli`},help:{"v1-wjvoxd-1m":`Opcjonalne hasło używane do odszyfrowania request.proxy.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Nazwa serwera TLS proxy dla żądań do dostawcy modeli`},help:{"v1-b4oabu-22":`Opcjonalne nadpisanie SNI/nazwy serwera używane podczas nawiązywania połączenia TLS z serwerem proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`Adres URL serwera proxy dla żądań do dostawcy modeli`},help:{"v1-kvbgou-48":`Jawnie określony adres URL serwera proxy używany, gdy request.proxy.mode ma wartość explicit-proxy. Dane uwierzytelniające zawarte w adresie URL są traktowane jako poufne i ukrywane w migawkach.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS dla żądań do dostawcy modeli`},help:{"v1-16u7v7h-2b":`Opcjonalne ustawienia TLS używane przy bezpośrednim łączeniu z punktem końcowym modelu u dostawcy.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`Pakiet CA TLS dla żądań do dostawcy modelu`},help:{"v1-ny8y3e-1v":`Niestandardowy pakiet certyfikatów CA używany do weryfikacji łańcucha certyfikatów TLS dostawcy.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`Certyfikat TLS dla żądań do dostawcy modelu`},help:{"v1-1lltmhw-2e":`Certyfikat TLS klienta przedstawiany punktowi końcowemu dostawcy, gdy wymagane jest wzajemne uwierzytelnianie TLS.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Pomijanie weryfikacji TLS dla żądań do dostawcy modelu`},help:{"v1-1006cuy-2m":`Pomija weryfikację certyfikatu TLS dostawcy. Używaj tylko w kontrolowanych środowiskach programistycznych.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Klucz TLS dla żądań do dostawcy modelu`},help:{"v1-w2agir-1t":`Klucz prywatny powiązany z request.tls.cert, używany do wzajemnego uwierzytelniania TLS z dostawcą.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Hasło TLS dla żądań do dostawcy modelu`},help:{"v1-10ds42f-1g":`Opcjonalne hasło używane do odszyfrowania request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Nazwa serwera TLS dla żądań do dostawcy modelu`},help:{"v1-18yt7x9-1y":`Opcjonalne nadpisanie nazwy serwera/SNI używane podczas nawiązywania połączenia TLS z dostawcą.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Limit czasu żądania do dostawcy modelu`},help:{"v1-t3yn8l-ih":`Opcjonalny limit czasu żądania do modelu w sekundach, ustawiany osobno dla każdego dostawcy. Ustawienia żądań na poziomie dostawcy wpływają na jawnie zdefiniowane wpisy modeli tego dostawcy; nie tworzą modeli niejawnych. W przypadku dostawców niestandardowych ustaw ten parametr obok baseUrl i models dostawcy. Dotyczy żądań HTTP do dostawcy, w tym nawiązywania połączenia, nagłówków, treści oraz obsługi przerywania całego żądania. Podnosi też dla tego dostawcy limit mechanizmu nadzorującego bezczynność i strumieniowanie LLM powyżej niejawnej wartości domyślnej wynoszącej około 120 s. Używaj tego ustawienia w przypadku powolnych serwerów modeli działających lokalnie lub we własnej infrastrukturze, a także dostawców chmurowych, którzy buforują tokeny rozumowania bez przesyłania danych przez sieć (Gemini preview, Claude/Opus z dużymi pakietami danych narzędzi), zamiast zmieniać globalne limity czasu agenta.`}},nodeHost:{label:{"v1-nb8lk1-9":`Host węzła`},help:{"v1-8recuz-4z":`Ustawienia hosta węzła dotyczące funkcji udostępnianych z tego węzła Gateway innym węzłom lub klientom. Zachowaj wartości domyślne, chyba że celowo udostępniasz lokalne funkcje za pośrednictwem sieci węzłów.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Uruchomienia agentów w węźle`},help:{"v1-4uz5ur-2k":`Włącz natywne tury agenta wymagające zatwierdzenia na tym hoście węzła bez interfejsu graficznego. Domyślnie wyłączone.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Uruchomienia agenta Claude w węźle`},help:{"v1-g8az5y-2l":`Określa, czy ten host węzła bez interfejsu graficznego może zgłaszać do Gateway dostępność tur agenta Claude CLI.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Uruchomienia agenta Claude w węźle włączone`},help:{"v1-1ke804l-44":`Zgłaszaj dostępność kontynuowania sesji Claude na sparowanym węźle, gdy lokalny plik wykonywalny claude jest dostępny (domyślnie: false). Uruchomienia nadal wymagają zatwierdzenia wykonania poleceń w węźle.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Automatyczne aktualizacje węzła`},help:{"v1-16xjk4e-5n":`Steruje automatycznymi aktualizacjami oddzielnego środowiska wykonawczego dla hostów węzłów bez interfejsu graficznego, dystrybuowanych w pakietach. Sprawdza dostępność aktualizacji co godzinę i czeka na zakończenie wszystkich zadań węzła przed ponownym uruchomieniem; automatyczne ponowne uruchomienia następują w odstępach co najmniej 12 godzin.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Automatyczne aktualizacje węzła włączone`},help:{"v1-1sa0yeg-7w":`Włącz automatyczne aktualizacje do wersji stabilnych lub beta dla długo działających węzłów bez interfejsu graficznego, dystrybuowanych w pakietach (domyślnie: true). Ustaw false, aby zrezygnować. Są również wyłączane przez update.checkOnStart=false lub OPENCLAW_NO_AUTO_UPDATE=1; aktualizacje nie są stosowane automatycznie w kopiach roboczych kodu źródłowego, aplikacjach natywnych, prywatnych procesach roboczych ani w kanałach dev i extended-stable.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Serwer proxy przeglądarki w węźle`},help:{"v1-2xrew7-4f":`Grupuje ustawienia proxy przeglądarki służące do udostępniania lokalnego sterowania przeglądarką przez routing węzła. Włącz tylko wtedy, gdy procesy na zdalnych węzłach wymagają dostępu do lokalnych profili przeglądarki.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Dozwolone profile proxy przeglądarki węzła`},help:{"v1-1ew5dkm-8b":`Opcjonalna lista dozwolonych nazw profili przeglądarki udostępnianych przez routing proxy węzła. Pozostaw pustą, aby zachować domyślny pełny zakres obsługi profili, w tym trasy ich tworzenia i usuwania. Po jej ustawieniu OpenClaw wymusza dostęp do profili zgodnie z zasadą minimalnych uprawnień i blokuje tworzenie oraz usuwanie trwałych profili przez proxy.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Włączone proxy przeglądarki węzła`},help:{"v1-pa04pd-5b":`Udostępnia lokalny serwer sterowania przeglądarką przez routing proxy węzła, aby zdalni klienci mogli korzystać z funkcji przeglądarki tego hosta. Pozostaw wyłączone, chyba że zdalna automatyzacja wyraźnie tego wymaga.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP hosta węzła`},help:{"v1-1mdhrwl-48":`Używaj serwerów MCP uruchamianych przez hosta węzła działającego bez interfejsu graficznego i udostępnianych sparowanej z nim bramie jako narzędzi agenta. Po zmianie tej sekcji uruchom ponownie hosta węzła.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Serwery MCP hosta węzła`},help:{"v1-19m002f-3x":`Nazwane definicje serwerów MCP lokalnych dla tego węzła. Używają tego samego formatu serwera co mcp.servers; host węzła nie obsługuje serwerów OAuth.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Skills hosta węzła`},help:{"v1-v8txza-41":`W tej sekcji możesz udostępniać umiejętności zainstalowane w ~/.openclaw/skills z hosta węzła działającego bez interfejsu graficznego. Po zmianie plików umiejętności uruchom ponownie hosta węzła.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Włączone Skills hosta węzła`},help:{"v1-1ggpkqb-36":`Skanuj i publikuj umiejętności hostowane na węźle po nawiązaniu połączenia (domyślnie: true). Ustaw false, aby wyłączyć publikowanie umiejętności węzła.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Uruchomienia procesów roboczych węzła`},help:{"v1-1w83rox-2p":`Włącz pełne hostowanie sesji procesów roboczych OpenClaw z pakietów zarządzanych przez Gateway. Domyślnie wyłączone.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Limit uruchomień procesów roboczych węzła`},help:{"v1-10nvk8f-3w":`Maksymalna liczba równoczesnych sesji procesów roboczych hostowanych przez ten węzeł (domyślnie: liczba dostępnych rdzeni CPU). Wartość musi być liczbą całkowitą od 1 do 1024.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Obraz kontenera procesów roboczych węzła`},help:{"v1-1oqx50o-5t":`Opcjonalny obraz Node 24.16+ lub 26.1+ dla procesów roboczych izolowanych w kontenerach (domyślnie: "node:24.19.0-slim"). W razie potrzeby użyj obrazu przypiętego do skrótu, pochodzącego z prywatnego rejestru lub wstępnie załadowanego; brakujące obrazy są pobierane przy pierwszym użyciu.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Uruchomienia procesów roboczych węzła włączone`},help:{"v1-b3t0xp-2t":`Zezwól temu sparowanemu węzłowi na hostowanie sesji wyłącznie z dokładnie tych pakietów, które zainstalował jego Gateway (domyślnie: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Izolacja procesów roboczych węzła`},help:{"v1-19i6swo-58":`Wybierz granicę izolacji procesu sesji roboczej: "none" uruchamia go bezpośrednio na hoście węzła (domyślnie); "container" wymaga działającego silnika zgodnego z Docker i nigdy nie przechodzi awaryjnie na uruchamianie na hoście.`}},plugins:{label:{"v1-10renyj-7":`Wtyczki`},help:{"v1-1qbev2k-5c":`Ustawienia systemu wtyczek umożliwiające włączanie rozszerzeń, ograniczanie zakresu ładowania, konfigurowanie wpisów i śledzenie instalacji. W środowiskach produkcyjnych stosuj jawnie określoną politykę wtyczek zgodną z zasadą najmniejszych uprawnień.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Lista dozwolonych wtyczek`},help:{"v1-pupwbe-7z":`Opcjonalna lista identyfikatorów dozwolonych wtyczek. Jeśli jest ustawiona, tylko wymienione wtyczki mogą zostać załadowane. Skonfigurowane wbudowane kanały czatu nadal mogą aktywować swoją wbudowaną wtyczkę, gdy kanał jest jawnie włączony w konfiguracji. Użyj tej opcji, aby wymusić korzystanie wyłącznie z zatwierdzonych rozszerzeń w kontrolowanych środowiskach.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Lista blokowanych wtyczek`},help:{"v1-4gyt4z-4i":`Opcjonalna lista identyfikatorów wtyczek, które są blokowane, nawet jeśli uwzględniono je na listach dozwolonych wtyczek lub w ścieżkach. Używaj reguł blokowania do awaryjnego wycofywania zmian i bezwarunkowego blokowania ryzykownych wtyczek.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Włącz wtyczki`},help:{"v1-pnygd7-50":`Globalnie włącza lub wyłącza ładowanie wtyczek i rozszerzeń podczas uruchamiania oraz ponownego wczytywania konfiguracji (domyślnie: true). Pozostaw tę opcję włączoną tylko wtedy, gdy Twoje wdrożenie wymaga funkcji rozszerzeń.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Wpisy wtyczek`},help:{"v1-cn74rf-54":`Ustawienia poszczególnych wtyczek przypisane do ich identyfikatorów, obejmujące stan włączenia oraz dane konfiguracji środowiska wykonawczego specyficzne dla danej wtyczki. Używaj ich do dostosowywania konkretnych wtyczek bez zmiany globalnych zasad ładowania.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Klucz API wtyczki`},help:{"v1-ctytg2-53":`Opcjonalne pole klucza API używane przez wtyczki, które obsługują bezpośrednie konfigurowanie klucza w ustawieniach wpisu. Korzystaj z podstawiania sekretów lub zmiennych środowiskowych i unikaj zapisywania rzeczywistych danych uwierzytelniających w plikach konfiguracyjnych objętych kontrolą wersji.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Konfiguracja wtyczki`},help:{"v1-1he672p-51":`Dane konfiguracyjne zdefiniowane przez wtyczkę, interpretowane zgodnie z jej własnym schematem i regułami walidacji. Używaj wyłącznie pól opisanych w dokumentacji wtyczki, aby uniknąć ignorowanych lub nieprawidłowych ustawień.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Wtyczka włączona`},help:{"v1-12soc0h-9a":`Ustawienie włączenia konkretnej wtyczki, które nadpisuje globalną politykę wtyczek. W domyślnym hybrydowym trybie przeładowania zmiany przeładowują środowisko wykonawcze wtyczki na potrzeby nowych tur agenta bez ponownego uruchamiania Gateway, chyba że wtyczka wymaga ponownego uruchomienia dla tej ścieżki. Użyj tego ustawienia, aby stopniowo wdrażać wtyczkę w kolejnych środowiskach.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Zmienne środowiskowe wtyczki`},help:{"v1-p39pu4-52":`Mapa zmiennych środowiskowych wtyczki, wstrzykiwana wyłącznie do jej kontekstu wykonawczego. Użyj tego ustawienia, aby ograniczyć dane uwierzytelniające dostawcy do jednej wtyczki zamiast udostępniać je w globalnym środowisku procesu.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Polityka hooków wtyczki`},help:{"v1-1oslnrf-4c":`Ustawienia polityki typowanych hooków dla poszczególnych wtyczek, określające zabezpieczenia egzekwowane przez rdzeń systemu. Użyj ich, aby ograniczyć kategorie hooków o dużym wpływie bez wyłączania całej wtyczki.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Zezwalaj na hooki dostępu do rozmowy`},help:{"v1-xqz31z-7e":"Określa, czy ta wtyczka może odczytywać nieprzetworzoną treść rozmowy za pośrednictwem typowanych hooków, takich jak `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` i `agent_end`. W przypadku wtyczek niedołączonych do pakietu wymagane jest jawne włączenie tej opcji."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`Zezwalaj na hooki wstrzykiwania promptów`},help:{"v1-7y6cny-32":"Określa, czy ta wtyczka może modyfikować prompty za pośrednictwem typowanych hooków. Ustaw false, aby zablokować `before_prompt_build`."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Limit czasu hooka wtyczki (ms)`},help:{"v1-4ra6b7-74":`Domyślny limit czasu w milisekundach dla typowanych hooków tej wtyczki, ograniczony do 600000. Jeśli nie jest ustawiony, każdy hook korzysta z limitu czasu zadeklarowanego przez wtyczkę lub z zasad Gateway dla danego hooka; nie ma jednej stałej wartości domyślnej. Wartości dla poszczególnych hooków w hooks.timeouts mają pierwszeństwo.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Nadpisania limitów czasu hooków wtyczki`},help:{"v1-yphl9b-5s":`Nadpisania limitów czasu poszczególnych hooków w milisekundach, z nazwą typowanego hooka jako kluczem, nie większe niż 600000. Stosuj nadpisania tylko dla znanych wolnych hooków, takich jak before_prompt_build lub agent_end, zamiast zwiększać limit czasu wszystkich hooków.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Zasady LLM wtyczki`},help:{"v1-dlca6c-4j":`Ustawienia api.runtime.llm.complete określające dla każdej wtyczki uprawnienia do nadpisywania modelu i agenta. Pozostaw nieustawione, chyba że wtyczka musi jawnie sterować wywołaniami generowania odpowiedzi zarządzanymi przez aplikację hosta.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Zezwalaj wtyczce na nadpisywanie agenta LLM`},help:{"v1-k8c08b-4n":`Jawnie zezwala tej wtyczce na żądanie api.runtime.llm.complete z identyfikatorem agenta innym niż domyślny. Pozostaw false, chyba że wtyczka jest zaufana w zakresie dostępu do modeli różnych agentów.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Zezwalaj wtyczce na nadpisywanie profilu uwierzytelniania LLM`},help:{"v1-9ityw9-4x":`Zezwala tej wtyczce na wybór profilu uwierzytelniania innego niż domyślny do generowania odpowiedzi w izolowanym środowisku wykonawczym agenta. Pozostaw false, chyba że wtyczka jest zaufana w zakresie jawnego kierowania poświadczeń w izolowanym środowisku.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Dozwolone modele generowania odpowiedzi LLM wtyczki`},help:{"v1-1ul08he-54":`Dozwolone modele dla każdego wywołania uzupełniania LLM przez wtyczkę, podane jako kanoniczne odwołania "provider/model", w tym wartości domyślne ustalane przez hosta i nadpisania. Używaj "*" tylko wtedy, gdy świadomie zezwalasz na dowolny model.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Dozwolone modele LLM wtyczki`},help:{"v1-154sk45-47":`Dozwolone modele zastępcze dla zaufanych wywołań LLM przez wtyczkę, podane jako kanoniczne odwołania "provider/model". Używaj "*" tylko wtedy, gdy świadomie zezwalasz na zastąpienie modelu dowolnym innym.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Zezwalaj wtyczce na zmianę modelu LLM`},help:{"v1-uw4jmc-47":`Jawnie zezwala tej wtyczce na żądanie zmiany modelu w api.runtime.llm.complete. Pozostaw false, chyba że wtyczka jest zaufana i może sterować wyborem modelu.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Zasady dotyczące subagentów wtyczki`},help:{"v1-wbf4m1-4d":`Ustawienia środowiska wykonawczego subagentów dla poszczególnych wtyczek, określające uprawnienia do zmiany modelu i listy dozwolonych modeli. Pozostaw nieustawione, chyba że wtyczka musi jawnie sterować wyborem modelu subagenta.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Dozwolone modele subagentów wtyczki`},help:{"v1-2pvkow-42":`Dozwolone modele zastępcze dla zaufanych uruchomień subagentów przez wtyczkę, podane jako kanoniczne odwołania "provider/model". Używaj "*" tylko wtedy, gdy świadomie zezwalasz na dowolny model.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Zezwalaj wtyczce na zmianę modelu subagenta`},help:{"v1-1r5tzm1-4g":`Jawnie zezwala tej wtyczce na żądanie zmiany dostawcy/modelu podczas uruchomień subagentów w tle. Pozostaw false, chyba że ufasz wtyczce w zakresie sterowania wyborem modelu.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Moduł ładowania wtyczek`},help:{"v1-1myjwbi-52":`Grupa ustawień modułu ładowania wtyczek służąca do określania ścieżek w systemie plików, w których wykrywane są wtyczki. Określaj ścieżki ładowania jawnie i weryfikuj je, aby uniknąć przypadkowego ładowania niezaufanych rozszerzeń.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Ścieżki ładowania wtyczek`},help:{"v1-o689p1-4z":`Dodatkowe pliki lub katalogi wtyczek skanowane przez moduł ładowania poza wbudowanymi lokalizacjami domyślnymi. Używaj katalogów przeznaczonych na rozszerzenia i unikaj zbyt ogólnych ścieżek zawierających niepowiązane pliki wykonywalne.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Sloty wtyczek`},help:{"v1-zx6crl-5f":`Określa, które wtyczki zajmują wyłączne sloty środowiska wykonawczego, takie jak pamięć, aby daną funkcję zapewniała tylko jedna wtyczka. Jawnie przypisuj sloty, aby uniknąć nakładania się dostawców o sprzecznym działaniu.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Wtyczka silnika kontekstu`},help:{"v1-4v13iw-2t":`Wybiera aktywną wtyczkę silnika kontekstu według identyfikatora, tak aby za orkiestrację kontekstu odpowiadała jedna wtyczka.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Wtyczka pamięci`},help:{"v1-80ngcl-23":`Wybierz aktywną wtyczkę pamięci według identyfikatora lub "none", aby wyłączyć wtyczki pamięci.`}},presence:{label:{"v1-10fdwo4-8":`Obecność`}},proxy:{label:{"v1-ji57pa-d":`Zarządzany serwer proxy`},help:{"v1-vui6bx-58":`Routing zarządzany przez operatora za pośrednictwem serwera forward proxy dla ruchu HTTP, HTTPS, WebSocket oraz obsługiwanych ścieżek bezpośredniego ruchu wychodzącego środowiska wykonawczego OpenClaw. Używaj tej opcji, gdy centralna kontrola ruchu wychodzącego jest częścią granicy wdrożenia.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Włączone zarządzane proxy`},help:{"v1-1456xdw-49":`Jawne nadpisanie ustawienia zarządzanego proxy. Obecność adresu URL domyślnie włącza routing; ustaw false, aby ignorować adresy URL proxy z konfiguracji lub zmiennych środowiskowych bez ich usuwania.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Tryb pętli zwrotnej zarządzanego proxy`},help:{"v1-1kaiuh0-3c":`Steruje routingiem płaszczyzny sterowania Gateway przez pętlę zwrotną, gdy tryb zarządzanego proxy jest aktywny: "gateway-only", "proxy" lub "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`Adres URL zarządzanego proxy`},help:{"v1-p36b5l-3v":`Adres URL zarządzanego proxy przekazującego. Użyj http:// dla zwykłego proxy CONNECT lub https://, gdy samo połączenie z punktem końcowym proxy musi korzystać z TLS.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS zarządzanego proxy`},help:{"v1-6i0vu-3q":`Ustawienia TLS używane podczas łączenia z punktem końcowym zarządzanego proxy. Te ustawienia dotyczą TLS proxy, a nie TLS połączenia docelowego po CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`Plik CA dla TLS zarządzanego proxy`},help:{"v1-1ntzjia-2p":`Ścieżka w systemie plików do niestandardowego pakietu certyfikatów CA używanego do weryfikacji certyfikatu punktu końcowego zarządzanego proxy HTTPS.`}},secrets:{label:{"v1-1sihgpy-7":`Sekrety`},help:{"v1-jgn0o9-2l":`Dostawcy odwołań do sekretów, zachowanie współdzielonego magazynu i opcjonalna ochrona ruchu wychodzącego podprocesów.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Proxy ruchu wychodzącego dla sekretów`},help:{"v1-1qfgid-4n":`Proxy pętli zwrotnej zarządzane przez Gateway, które zastępuje znaczniki sekretów ze współdzielonego magazynu dopiero w momencie wysyłania żądania wychodzącego. Po zmianie tej sekcji, odczytywanej przy uruchamianiu, uruchom ponownie Gateway.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Dozwolone hosty proxy ruchu wychodzącego dla sekretów`},help:{"v1-9ypodl-6t":`Opcjonalna lista dozwolonych miejsc docelowych dla żądań i tuneli CONNECT. Jeśli jest ustawiona, miejsca docelowe muszą znajdować się na tej liście, w powiązaniu hosta z konkretnym sekretem lub na liście bypassHosts. Pusta lista zezwala tylko na hosty powiązane lub objęte pomijaniem. Po jej zmianie uruchom ponownie Gateway.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Hosty pomijane przez serwer proxy ruchu wychodzącego dla sekretów`},help:{"v1-1oiiomv-57":`Dokładne nazwy hostów korzystających z uwierzytelnionych tuneli CONNECT bez wglądu w zawartość dla klientów z przypiętymi certyfikatami. Znaczniki zastępcze pozostają zaszyfrowane i spowodują niepowodzenie uwierzytelniania u dostawcy zamiast ujawnienia tekstu jawnego.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Włączony serwer proxy ruchu wychodzącego dla sekretów`},help:{"v1-u99b1i-2h":`Włącza podstawianie sekretów w ruchu wychodzącym dla podprocesów agenta uruchamianych przez Gateway. Domyślnie: false.`}},session:{label:{"v1-8yh9jr-7":`Sesja`},help:{"v1-j86s32-5d":`Globalne ustawienia routingu sesji, resetowania, zasad dostarczania i konserwacji wpływające na działanie historii rozmów. Zachowaj ustawienia domyślne, chyba że potrzebujesz ściślejszej izolacji, retencji lub ograniczeń dostarczania.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Zakres sesji wiadomości prywatnych`},help:{"v1-ql362c-5l":`Zakres sesji wiadomości prywatnych: "main" zachowuje ciągłość, a "per-peer", "per-channel-peer" i "per-account-channel-peer" zwiększają izolację. Używaj trybów izolowanych w przypadku współdzielonych skrzynek odbiorczych lub wdrożeń z wieloma kontami.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Zakres sesji grupowych`},help:{"v1-1fdezx2-6i":`Zakres sesji grup i kanałów: "per-group" rozdziela pokoje, a główna sesja agenta obserwuje je w tle, niezależnie od dmScope; "main" łączy kontekst pokoi z sesją główną i nie wymaga obserwowania. Używaj "main" tylko dla zaufanych pokoi.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Powiązania tożsamości sesji`},help:{"v1-1y5jnsm-5n":`Mapuje tożsamości kanoniczne na identyfikatory rozmówców z prefiksem dostawcy, aby konta tego samego użytkownika trafiały do jednego wątku wiadomości prywatnych (przykład: telegram:123456). Użyj tej opcji, gdy ta sama osoba korzysta z wielu kanałów lub kont.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Klucz sesji głównej`},help:{"v1-18p638h-3q":`Akceptowane, ale ignorowane: sufiks sesji głównej dla każdego agenta to zawsze "main". Pomiń to pole; globalny zakres sesji używa zamiast tego "global".`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Konserwacja sesji`},help:{"v1-imr441-66":`Ustawienia automatycznej konserwacji magazynu sesji: archiwizacja sesji panelu, wiek kwalifikujący do usunięcia, limity wpisów, okres przechowywania archiwów po zresetowaniu i czyszczenie w ramach limitu miejsca na dysku. Zacznij od trybu warn, aby obserwować skutki, a po dostrojeniu progów przejdź do trybu enforce.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Archiwizuj nieaktywne sesje panelu po`},help:{"v1-1frdtub-5n":"Archiwizuje nieaktywne sesje panelu po upływie tego czasu (na przykład `7d`), aby pozostały dostępne bez przepełniania listy aktywnych sesji. Ustaw `false` lub `0`, aby wyłączyć automatyczną archiwizację sesji panelu."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Magazyn archiwalny transkrypcji`},help:{"v1-1kp9s9h-5s":`Przenosi nieaktywne transkrypcje do skompresowanych archiwów JSONL, zachowując metadane sesji. Pliki archiwów stają się niezbędną częścią historii i muszą być uwzględniane w kopiach zapasowych. Zmiany są stosowane bez ponownego uruchamiania Gateway.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Liczba dni nieaktywności przed archiwizacją`},help:{"v1-zay1q3-5b":`Archiwizuj transkrypcje po tylu dniach nieaktywności (dodatnia liczba całkowita, domyślnie 30). Aktywna praca jest chroniona; zmiana progu zacznie obowiązywać przy następnym przebiegu procesu roboczego, bez ponownego uruchamiania Gateway.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Automatycznie archiwizuj stare transkrypcje`},help:{"v1-6p6vmb-5a":`Włącza archiwizację transkrypcji w tle (domyślnie false). Proces roboczy co minutę sprawdza, czy są transkrypcje kwalifikujące się do archiwizacji. Ta jawnie określona polityka archiwizacji jest niezależna od usuwania i czyszczenia w ramach limitu miejsca na dysku.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Docelowy górny próg zajętości dysku przez sesje`},help:{"v1-143vh09-7z":`Docelowy rozmiar po czyszczeniu w ramach limitu miejsca na dysku (górny próg). Domyślnie wynosi 80% maxDiskBytes; ustaw go jawnie, aby skuteczniej odzyskiwać miejsce na dyskach o ograniczonej pojemności. Wartość obliczona jako zero powoduje użycie wartości domyślnej; wartości ujemne są nieprawidłowe. Aby wyłączyć limit, użyj zamiast tego maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Maksymalny limit miejsca na dysku dla sesji`},help:{"v1-147lxk3-cj":'Limit fizycznego miejsca na dysku na agenta, obejmujący główną bazę SQLite, plik WAL i wliczane artefakty katalogu sesji (na przykład `500mb`). Domyślnie `10gb`; chronione dane mogą utrzymywać zużycie powyżej wartości docelowej. Po przekroczeniu limitu tryb warn zgłasza brak miejsca, a tryb enforce usuwa stare artefakty resetowania i usuwania, historię bez odwołań, a następnie archiwa utworzone z powodu limitu. Archiwa ręczne, utworzone w ramach retencji czasowej, z poziomu panelu, na potrzeby odzyskiwania oraz starszego typu pozostają chronione. Ustaw `false`, `0` lub `"0"`, aby wyłączyć.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Maksymalna liczba wpisów sesji`},help:{"v1-1w2egrh-7u":`Ogranicza liczbę niezarchiwizowanych wpisów sesji (domyślnie 5000). Kwalifikujące się trwałe rozmowy przekraczające limit są archiwizowane wraz z historią; jednorazowe wpisy automatyzacji są usuwane. Istniejące archiwa nie są wliczane do limitu. Chronione aktywne wpisy nadal są wliczane i mogą utrzymywać liczbę wpisów w magazynie powyżej limitu.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Tryb konserwacji sesji`},help:{"v1-bq39hk-6v":`Określa, czy działania wynikające z polityk przycinania i limitu miejsca na dysku są tylko zgłaszane ("warn"), czy faktycznie wykonywane ("enforce"). Podczas wdrażania pozostaw "warn", a po zweryfikowaniu bezpiecznych progów przełącz na "enforce". Archiwizacja ma własne, jawnie określone ustawienie enabled.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Zachowuj ostatnie sesje`},help:{"v1-138q5wx-89":"Chroni sesje interaktywne aktywne w podanym okresie (na przykład `7d`) przed automatycznym usuwaniem historii ze względu na wiek, liczbę wpisów i limit miejsca na dysku. Brak ustawienia lub `false` zachowuje standardową zasadę usuwania najstarszych wpisów w pierwszej kolejności. Syntetyczne wiersze uruchomień modeli, cron, hook, heartbeat, ACP i subagentów nadal kwalifikują się do czyszczenia w ramach limitów."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Usuwanie sesji po upływie`},help:{"v1-1xn50w7-76":"Archiwizuje kwalifikujące się trwałe rozmowy i usuwa jednorazowe wpisy automatyzacji starsze niż wskazany okres (domyślnie `30d`; na przykład `12h`). Zarchiwizowane rozmowy zachowują historię i można je przywrócić; rozmowy chronione lub dostępne do routingu pozostają aktywne."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Okres przechowywania archiwów resetowania sesji`},help:{"v1-16amrs1-7r":"Przechowywanie zarchiwizowanych transkrypcji na podstawie ich wieku (`*.reset.<timestamp>` i `*.deleted.<timestamp>`). Domyślnie archiwa są przechowywane, dopóki limit miejsca na dysku nie wymusi ich usunięcia, począwszy od najstarszych; ustaw okres (na przykład `30d`), aby włączyć usuwanie po upływie określonego czasu, lub `false`, aby je jawnie wyłączyć."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Powiadamiaj sesję Home o utworzeniu sesji`},help:{"v1-c4prn5-8b":`Dodaje powiadomienie systemowe do kolejki w sesji Home agenta będącego właścicielem po utworzeniu sesji (domyślnie: true). Powiadomienia zawierają dostępny tytuł i metadane twórcy oraz są odczytywane w następnej turze sesji Home lub przy następnym sygnale aktywności. Ustaw false, aby wyłączyć; wersje robocze, sesje incognito, sesje wewnętrzne i zaplanowane uruchomienia cron są wykluczone.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Zasady resetowania sesji`},help:{"v1-1hmt7n3-6r":`Definiuje domyślny obiekt zasad resetowania używany, gdy nie ma zastosowania żadne nadpisanie dla konkretnego typu lub kanału. Domyślnie sesje nie resetują się automatycznie; aby to włączyć, użyj harmonogramów dziennych lub opartych na bezczynności. Polecenia /new i /reset pozostają dostępne w dowolnym momencie.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Godzina codziennego resetowania sesji`},help:{"v1-wry8cv-59":`Ustawia godzinę graniczną czasu lokalnego (0–23) dla trybu codziennego resetowania, aby sesje rozpoczynały się od nowa o przewidywalnych porach. Używaj z mode=daily i dostosuj do oczekiwań operatora dotyczących strefy czasowej, aby działanie było intuicyjne.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Minuty bezczynności przed resetowaniem sesji`},help:{"v1-1kzj0id-5e":`Ustawia okres bezczynności przed resetowaniem w trybie bezczynności i może też pełnić funkcję dodatkowego zabezpieczenia w trybie dziennym. Używaj większych wartości, aby zachować ciągłość, lub mniejszych, aby częściej rozpoczynać nowe, krótkotrwałe wątki.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Tryb resetowania sesji`},help:{"v1-e5ie4w-5b":`Wybiera strategię resetowania: "none" wyłącza automatyczne resetowanie (domyślnie), "daily" resetuje o skonfigurowanej godzinie, a "idle" resetuje po okresie bezczynności. /new i /reset pozostają dostępne w każdym trybie.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Resetowanie sesji według kanału`},help:{"v1-1uxsulx-5h":`Umożliwia precyzyjne sterowanie resetowaniem poprzez ustawienia dla poszczególnych kanałów, przypisane do identyfikatorów dostawcy/kanału. Używaj tego tylko wtedy, gdy jeden kanał wymaga wyjątkowych zasad resetowania, wykraczających poza zasady dla danego typu.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Resetowanie sesji według typu czatu`},help:{"v1-ypdr7u-52":`Zastępuje domyślne zasady resetowania według typu czatu (bezpośredni, grupowy, wątek), gdy ustawienia domyślne są niewystarczające. Używaj tego, gdy aktywność w grupach lub wątkach wymaga innej częstotliwości resetowania niż wiadomości bezpośrednie.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Resetowanie sesji (czat bezpośredni)`},help:{"v1-fjnlp5-56":`Określa zasady resetowania czatów bezpośrednich i zastępuje podstawową konfigurację session.reset dla tego typu. Używaj tego jako standardowego ustawienia dla wiadomości bezpośrednich zamiast starszego aliasu dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Resetowanie sesji (czat grupowy)`},help:{"v1-hl1200-4u":`Określa zasady resetowania sesji czatów grupowych, w których ciągłość rozmowy i natężenie zbędnych wiadomości różnią się od czatów bezpośrednich. W aktywnych grupach stosuj krótsze okresy bezczynności, jeśli utrata spójności kontekstu staje się problemem.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Resetowanie sesji (wątek)`},help:{"v1-1hgpeke-4w":`Określa zasady resetowania sesji ograniczonych do wątku, w tym pracy skupionej na konkretnych wątkach kanału. Używaj tego, gdy sesje wątków powinny wygasać szybciej lub wolniej niż sesje innych typów czatu.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Wyzwalacze resetowania sesji`},help:{"v1-rcabsw-5a":`Lista wyzwalaczy wiadomości, które wymuszają reset sesji po wykryciu dopasowania w treści przychodzącej. Stosuj je oszczędnie do jednoznacznych fraz resetujących, aby kontekst nie był nieoczekiwanie tracony podczas zwykłej rozmowy.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Zakres sesji`},help:{"v1-axt4ds-5z":`Ustawia podstawową strategię grupowania sesji: "per-sender" rozdziela sesje według nadawcy, a "global" udostępnia jedną wspólną sesję na kontekst kanału. Zachowaj "per-sender", aby zapewnić bezpieczniejsze działanie w środowisku wielu użytkowników, chyba że celowo potrzebujesz wspólnego kontekstu.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Zasady wysyłania między sesjami`},help:{"v1-17qpipb-5l":`Kontroluje uprawnienia do wysyłania między sesjami za pomocą reguł zezwalających i blokujących, sprawdzanych względem channel, chatType i prefiksów kluczy. Użyj tego ustawienia, aby ograniczyć miejsca, do których narzędzia sesji mogą dostarczać wiadomości w złożonych środowiskach.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Domyślne działanie zasad wysyłania między sesjami`},help:{"v1-15plhut-53":`Ustawia działanie zastępcze, gdy żadna reguła sendPolicy nie pasuje: "allow" lub "deny". Zachowaj "allow" w prostszych konfiguracjach lub wybierz "deny", gdy wymagasz jawnych reguł zezwalających dla każdego miejsca docelowego.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Reguły zasad wysyłania między sesjami`},help:{"v1-o217za-5h":'Uporządkowane reguły zezwalające i blokujące, sprawdzane przed zastosowaniem działania domyślnego, na przykład `{ action: "deny", match: { channel: "discord" } }`. Umieść najbardziej szczegółowe reguły na początku, aby reguły ogólne nie przesłaniały wyjątków.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Działanie reguły wysyłania między sesjami`},help:{"v1-178vm80-54":`Określa decyzję reguły jako "allow" lub "deny", gdy spełnione są odpowiednie kryteria dopasowania. Aby egzekwować ścisłe ograniczenia z jawnymi wyjątkami zezwalającymi, umieść reguły odmowy przed regułami zezwalającymi.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Warunki dopasowania reguły wysyłania w sesji`},help:{"v1-18qh5qg-5d":`Określa opcjonalne warunki dopasowania reguły, które mogą łączyć ograniczenia dotyczące channel, chatType i prefiksu klucza. Stosuj precyzyjne warunki dopasowania, aby cel polityki był czytelny, a debugowanie pozostało proste.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Kanał reguły wysyłania w sesji`},help:{"v1-u5erwx-50":`Ogranicza stosowanie reguły do określonego identyfikatora kanału lub dostawcy (na przykład discord, telegram, slack). Użyj tej opcji, gdy jeden kanał powinien zezwalać na dostarczanie lub go zabraniać niezależnie od pozostałych.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Typ czatu reguły wysyłania w sesji`},help:{"v1-7cv4f9-4z":`Ogranicza stosowanie reguły do typu czatu (direct, group, thread), dzięki czemu zachowanie zależy od formy rozmowy. Użyj tej opcji, gdy wiadomości prywatne i grupowe wymagają różnych ograniczeń bezpieczeństwa.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Prefiks klucza reguły wysyłania w sesji`},help:{"v1-ac4dee-5n":`Dopasowuje znormalizowany prefiks klucza sesji po wewnętrznych etapach normalizacji klucza w komponentach stosujących politykę. Używaj tej opcji do ogólnej kontroli na podstawie prefiksów, a gdy wymagane jest dokładne dopasowanie pełnego klucza, wybierz rawKeyPrefix.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Prefiks surowego klucza reguły wysyłania w sesji`},help:{"v1-1g9w044-5e":`Dopasowuje surowy, nieznormalizowany prefiks klucza sesji, aby precyzyjnie stosować zasady do pełnych kluczy. Użyj tej opcji, gdy znormalizowany keyPrefix jest zbyt ogólny i potrzebujesz precyzji uwzględniającej prefiks agenta lub konkretny transport.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Tryby udostępniania sesji`},help:{"v1-xbh52d-5a":`Określa, które tryby współpracy mogą wybierać właściciele sesji i administratorzy. Pominięte wartości logiczne domyślnie oznaczają włączenie; ustaw dla trybu false, aby usunąć go z listy wyboru i odrzucać nowe próby jego wybrania.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Zezwalaj na sesje robocze`},help:{"v1-1lzap27-2p":`Zezwala na widoczność w trybie roboczym, który ukrywa sesje przed operatorami niebędącymi ich właścicielami ani administratorami. Domyślnie: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Zezwalaj na sesje tylko do odczytu`},help:{"v1-upl3nu-21":`Zezwala na ustawienie sesji jako dostępnych tylko do odczytu dla osób niebędących uczestnikami. Domyślnie: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Zezwalaj na sesje w trybie sugestii`},help:{"v1-4i8owu-4g":`Zezwala na widoczność w trybie sugestii. Na tym etapie wymusza te same zasady dostępu co tryb tylko do odczytu; kolejki sugestii są konfigurowane przez funkcję wprowadzaną na późniejszym etapie. Domyślnie: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Ścieżka magazynu sesji`},help:{"v1-hreznz-56":`Ustawia ścieżkę pliku magazynu sesji używanego do zachowywania rekordów sesji między ponownymi uruchomieniami. Podaj jawną ścieżkę tylko wtedy, gdy potrzebujesz niestandardowego układu plików na dysku, kierowania kopii zapasowych do określonej lokalizacji lub przechowywania danych na zamontowanym woluminie.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Powiązania wątków sesji`},help:{"v1-zbzihu-4s":`Wspólne ustawienia domyślne tworzenia sesji powiązanych z wątkami i ich routingu w obsługiwanych kanałach. Skonfiguruj tutaj globalne ustawienia domyślne i nadpisuj je dla poszczególnych kanałów tylko wtedy, gdy ich działanie ma się różnić.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Kontekst tworzenia sesji w wątku`},help:{"v1-1set6nw-4c":`Domyślny natywny kontekst subagenta dla sesji tworzonych w powiązaniu z wątkiem. Użyj "fork", aby rozpocząć od transkrypcji żądającego, lub "isolated", aby utworzyć sesję podrzędną bez wcześniejszego kontekstu. Domyślnie: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Powiązanie z wątkiem włączone`},help:{"v1-foomtc-3f":`Główny globalny przełącznik tworzenia sesji powiązanych z wątkami, ich routingu i dostarczania wiadomości. Wyłącz, aby globalnie wyłączyć powiązania z wątkami.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Limit czasu bezczynności powiązania z wątkiem (godziny)`},help:{"v1-gffnx3-3h":`Domyślny okres bezczynności w godzinach dla sesji powiązanych z wątkami u różnych dostawców i w różnych kanałach (0 wyłącza wygasanie z powodu bezczynności). Domyślnie: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Maksymalny wiek powiązania z wątkiem (godziny)`},help:{"v1-1xfcyhw-39":`Opcjonalny bezwzględny maksymalny wiek w godzinach dla sesji powiązanych z wątkami u różnych dostawców i w różnych kanałach (0 wyłącza ten limit). Domyślnie: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Tworzenie sesji powiązanych z wątkami`},help:{"v1-1lqwbdl-46":`Globalne domyślne ustawienie zezwalające na tworzenie sesji roboczych powiązanych z wątkami za pomocą sessions_spawn i mechanizmu tworzenia sesji w wątkach ACP. Domyślnie: true, gdy powiązania z wątkami są włączone.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Dozwolone cele dowiązań symbolicznych umiejętności`},help:{"v1-xzybiq-4t":`Zaufane rzeczywiste katalogi główne, na które mogą wskazywać dowiązania symboliczne umiejętności, gdy ich cele znajdują się poza skonfigurowanym katalogiem źródłowym. Ogranicz ten zakres, na przykład do katalogu umiejętności w sąsiednim repozytorium.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Dodatkowe katalogi umiejętności`},help:{"v1-11o7opu-53":`Dodatkowe współdzielone katalogi główne umiejętności skanowane z najniższym priorytetem. Używaj tej opcji dla sąsiednich repozytoriów lub współdzielonych pakietów umiejętności, które powinny być dostępne bez kopiowania ich do obszaru roboczego OpenClaw.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Monitoruj Skills`},help:{"v1-1ckr2l5-5d":`Włącz monitorowanie systemu plików pod kątem zmian definicji umiejętności, aby aktualizacje mogły być stosowane bez pełnego ponownego uruchomienia procesu. Pozostaw włączone podczas prac programistycznych i wyłącz w niezmiennych obrazach produkcyjnych.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Tryb autonomiczny warsztatu umiejętności`},help:{"v1-1s3kgit-6j":`Steruje uczeniem się w tle: "off" pozostawia tylko przypomnienie o sugestii, "propose" tworzy oczekujące propozycje, a "auto" stosuje zarejestrowane propozycje i przeprowadza cotygodniowy przegląd umiejętności zarządzanych przez warsztat za pomocą zwykłych zmian w plikach. Domyślnie: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`Zasady interfejsów dostarczania`},help:{"v1-vgtjbs-50":`Nadpisania zasad wiadomości dla poszczególnych interfejsów dostarczania, przypisane do ustalonego identyfikatora interfejsu. Używaj tylko wtedy, gdy jeden wdrożony interfejs wymaga bardziej restrykcyjnej obsługi cichych odpowiedzi niż domyślna obsługa agenta.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Zasady cichych odpowiedzi interfejsu dostarczania`},help:{"v1-12zgc3n-60":`Nadpisuje zasady cichych odpowiedzi dla jednego ustalonego interfejsu dostarczania. Nieustawione pola dziedziczą wartości z agents.defaults.silentReply; używaj identyfikatorów interfejsów o wąskim zakresie, aby zachowanie wewnętrzne lub specyficzne dla grupy nie wpływało na inne miejsca docelowe.`}},talk:{label:{"v1-15ukbjj-4":`Rozmowa`},help:{"v1-1gx10xa-5g":`Ustawienia syntezy mowy w trybie Talk obejmujące tożsamość głosu, wybór modelu, format wyjściowy i zachowanie przy przerywaniu. Ta sekcja pozwala dostosować obsługę głosową do potrzeb użytkowników, a jednocześnie kontrolować opóźnienia i koszty.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Agent trybu Talk`},help:{"v1-iee5l9-2b":`Agent będący właścicielem sesji Talk utworzonych bez jawnego klucza sesji przypisanego do agenta.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Tryb szybki konsultacji Talk`},help:{"v1-syf3xk-2o":`Pozwala ustawić tryb szybki na true lub false dla standardowego uruchomienia agenta obsługującego konsultacje Talk w czasie rzeczywistym.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Poziom rozumowania konsultacji Talk`},help:{"v1-1ft5njw-2o":`Pozwala nadpisać poziom rozumowania dla standardowego uruchomienia agenta obsługującego konsultacje Talk w czasie rzeczywistym.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Przerywanie przy wykryciu mowy w trybie Talk`},help:{"v1-8n9q4o-3l":`Jeśli ustawiono true (domyślnie), wypowiedź asystenta zostaje zatrzymana, gdy użytkownik zaczyna mówić w trybie Talk. Pozostaw tę opcję włączoną, aby umożliwić naprzemienne zabieranie głosu.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Aktywny dostawca trybu Talk`},help:{"v1-wgnxhg-1g":`Identyfikator aktywnego dostawcy trybu Talk (na przykład "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Ustawienia dostawców trybu Talk`},help:{"v1-oh0yuv-30":`Ustawienia trybu Talk specyficzne dla dostawcy, z identyfikatorem dostawcy jako kluczem. Podczas migracji używaj ich zamiast starszych kluczy talk.*.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Konfiguracja dostawcy trybu Talk`},help:{"v1-36pblg-1r":`Pola konfiguracji trybu Talk zarządzane przez dostawcę o odpowiadającym identyfikatorze.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Klucz API dostawcy trybu Talk`},help:{"v1-1a1p9wp-v":`Klucz API dostawcy dla trybu Talk.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Talk w czasie rzeczywistym`},help:{"v1-c2re7j-3z":`Dostawca, model, głos, tryb, transport i strategia rozumowania funkcji Talk w czasie rzeczywistym. Konfigurację dostawcy mowy/TTS przechowuj w talk.provider i talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Rozumowanie funkcji Talk w czasie rzeczywistym`},help:{"v1-opsatw-37":`Strategia rozumowania funkcji Talk: agent-consult dla pomocy agenta za pośrednictwem Gateway, direct-tools dla lokalnych wywołań narzędzi lub none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Routing konsultacji funkcji Talk w czasie rzeczywistym`},help:{"v1-10qjcvk-5f":`Awaryjne przekazywanie końcowych transkrypcji wypowiedzi użytkownika przez Gateway, gdy dostawca działający w czasie rzeczywistym pomija openclaw_agent_consult. provider-direct zachowuje odpowiedzi dostawcy; force-agent-consult kieruje je przez OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Instrukcje funkcji Talk w czasie rzeczywistym`},help:{"v1-1jaaj84-5p":`Dodatkowe instrukcje systemowe dołączane do wbudowanego promptu funkcji Talk w czasie rzeczywistym w OpenClaw. Użyj ich do określenia stylu głosu, tonu i innych zachowań dostawcy w czasie rzeczywistym, pozostawiając wytyczne agent-consult bez zmian.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Tryb funkcji Talk w czasie rzeczywistym`},help:{"v1-1u2xui1-1l":`Tryb działania funkcji Talk: realtime, stt-tts lub transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Model funkcji Talk w czasie rzeczywistym`},help:{"v1-amou5a-27":`Zastąpienie identyfikatora modelu dostawcy działającego w czasie rzeczywistym dla sesji Talk w przeglądarce lub zarządzanych przez Gateway.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Bufor poprzedzający mowę w funkcji Talk w czasie rzeczywistym (ms)`},help:{"v1-1cwg07n-22":`Liczba milisekund dźwięku zachowywanego przed wykryciem aktywności głosowej w czasie rzeczywistym.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Dostawca funkcji Talk w czasie rzeczywistym`},help:{"v1-wwsmpt-1o":`Identyfikator aktywnego dostawcy głosu w czasie rzeczywistym, np. openai lub google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Ustawienia dostawców Talk w czasie rzeczywistym`},help:{"v1-ruagcu-1r":`Ustawienia głosu w czasie rzeczywistym specyficzne dla dostawców, przypisane do ich identyfikatorów.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Konfiguracja dostawcy Talk w czasie rzeczywistym`},help:{"v1-edfpxm-1u":`Konfiguracja głosu w czasie rzeczywistym należąca do dostawcy o danym identyfikatorze.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Klucz API dostawcy Talk w czasie rzeczywistym`},help:{"v1-1fbmgpx-z":`Klucz API dostawcy dla Talk w czasie rzeczywistym.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Poziom wysiłku rozumowania Talk w czasie rzeczywistym`},help:{"v1-157xd3e-2t":`Poziom wysiłku rozumowania specyficzny dla dostawcy podczas sesji Talk w czasie rzeczywistym, np. minimal, low, medium lub high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Czas ciszy Talk w czasie rzeczywistym (ms)`},help:{"v1-1grnu06-1y":`Liczba milisekund ciszy przed zatwierdzeniem wypowiedzi użytkownika w Talk w czasie rzeczywistym.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Głos mówcy Talk w czasie rzeczywistym`},help:{"v1-1kgb166-2h":`Nadpisanie nazwy głosu mówcy u dostawcy działającego w czasie rzeczywistym dla sesji Talk w przeglądarce lub zarządzanych przez Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Identyfikator głosu mówcy Talk w czasie rzeczywistym`},help:{"v1-1k8w6vk-2f":`Nadpisanie identyfikatora głosu mówcy u dostawcy działającego w czasie rzeczywistym dla sesji Talk w przeglądarce lub zarządzanych przez Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Transport Talk w czasie rzeczywistym`},help:{"v1-2otjgn-2g":`Transport bajtów/sesji w Talk: webrtc, provider-websocket, gateway-relay lub managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Próg VAD w czasie rzeczywistym w Talk`},help:{"v1-nf5l2t-2j":`Próg wykrywania aktywności głosowej w czasie rzeczywistym od 0 (największa czułość) do 1 (najmniejsza czułość).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Limit czasu ciszy w Talk (ms)`},help:{"v1-1kim32f-59":`Czas ciszy użytkownika w milisekundach, po którym tryb Talk kończy i wysyła bieżącą transkrypcję. Pozostaw bez ustawienia, aby zachować domyślny czas pauzy dla danej platformy (700 ms w macOS i Android, 900 ms w iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Ustawienia regionalne mowy w Talk`},help:{"v1-1un3x4l-4c":`Identyfikator ustawień regionalnych BCP 47 używany do rozpoznawania mowy w Talk na węzłach urządzeń oraz do zapasowego głosu systemowego w iOS, na przykład "ru-RU". Pozostaw bez ustawienia, aby używać ustawień domyślnych każdego urządzenia.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetria`},help:{"v1-1o5tru3-55":`Wyraźna zgoda na anonimowe statystyki korzystania z funkcji dołączane do codziennego sprawdzania aktualizacji. Statystyki korzystania z funkcji są domyślnie wyłączone i nigdy nie zawierają wiadomości, danych uwierzytelniających ani identyfikatorów.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Znacznik czasu zgody na statystyki korzystania z funkcji`},help:{"v1-1t051az-3t":`Znacznik czasu w formacie ISO określający, kiedy operator wyraził zgodę na anonimowe statystyki korzystania z funkcji lub jej odmówił. Zapobiega ponownemu wyświetlaniu pytania przez kreator konfiguracji.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Anonimowe statystyki korzystania z funkcji`},help:{"v1-1ptrwuq-4r":`Udostępnia nazwy włączonych kanałów i dostawców, liczbę wtyczek oraz liczbę ostatnich sesji podczas codziennego sprawdzania aktualizacji. Domyślnie wyłączone i zawsze wyłączone, gdy DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Narzędzia`},help:{"v1-1el54kl-5h":`Infrastruktura narzędzi i ustawienia domyślne komunikacji między agentami. Równorzędne sekcje na poziomie głównym odpowiadają za infrastrukturę i ustawienia domyślne komunikacji między agentami; agents.defaults odpowiada za zachowanie pętli agenta; wpisy poszczególnych agentów mogą nadpisywać oba rodzaje ustawień tam, gdzie jest to obsługiwane.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Dostęp do narzędzi między agentami`},help:{"v1-1ynpa5f-cf":`Zasady wywoływania narzędzi sesji między agentami: wysyłanie, wyświetlanie listy, odczyt historii, wyszukiwanie i odczyt statusu (domyślnie: włączone). Użyj allow, aby ograniczyć dozwolone pary agentów; enabled=false blokuje zwykły dostęp między agentami. Sesje natywnych podagentów i sesje potomne ACP należące do agenta żądającego pozostają dostępne przy widoczności tree lub all. Aby zapewnić ścisłą separację, ustaw tools.sessions.visibility na agent lub self (tree nadal dopuszcza sesje potomne natywnych podagentów i ACP należące do agenta żądającego) lub użyj oddzielnych bram.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Lista dozwolonych agentów docelowych`},help:{"v1-1jt2ari-76":`Identyfikatory agentów lub wzorce z symbolem *, które mogą uczestniczyć w wywołaniach między agentami; zarówno agent żądający, jak i docelowy muszą pasować do listy. Dostęp między agentami jest domyślnie włączony, a pominięte lub puste allow dopuszcza każdą parę. Ustaw jawną listę, aby ograniczyć dostęp; puste wpisy odmawiają dostępu.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Włącz narzędzie komunikacji między agentami`},help:{"v1-w950oq-ba":`Włącza dostęp do narzędzi sesji między agentami (domyślnie: true); pominięte lub puste allow dopuszcza każdą parę agentów. Ustaw false, aby zablokować zwykły dostęp między agentami; sesje natywnych podagentów i sesje potomne ACP należące do agenta żądającego pozostają dostępne przy widoczności tree lub all. Aby zapewnić ścisłą separację, ustaw tools.sessions.visibility na agent lub self (tree nadal dopuszcza sesje potomne natywnych podagentów i ACP należące do agenta żądającego) lub użyj oddzielnych bram.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Lista dozwolonych narzędzi`},help:{"v1-1is3eaq-4v":`Bezwzględna lista dozwolonych narzędzi, która zastępuje ustawienia domyślne wynikające z profilu w środowiskach o rygorystycznych wymaganiach. Używaj jej tylko wtedy, gdy celowo udostępniasz ściśle wybrany podzbiór możliwości narzędzi.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Dodatkowe dozwolone narzędzia`},help:{"v1-1xw9zp8-57":`Dodatkowe wpisy listy dozwolonych narzędzi, dołączane do wybranego profilu narzędzi i domyślnej polityki. Lista powinna być krótka i jednoznaczna, aby podczas audytów można było szybko zidentyfikować celowe wyjątki od polityki.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Polityka narzędzi według dostawcy`},help:{"v1-1ecljob-4y":`Nadpisania reguł zezwalania na narzędzia i ich blokowania dla poszczególnych dostawców, przypisane do identyfikatorów kanałów lub dostawców w celu dostosowania możliwości do danego interfejsu. Używaj ich, gdy jeden z dostawców wymaga bardziej rygorystycznych ograniczeń niż globalna polityka narzędzi.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Tryb kodu`},help:{"v1-1ecc39k-6k":'Ogólny tryb kodu OpenClaw. Jeśli pominięto go globalnie, domyślną wartością jest `"auto"`; jawnie zdefiniowany obiekt bez `enabled` pozostaje wyłączony. Uruchomienia agenta z włączonym trybem udostępniają modelowi tylko `exec` i `wait`, a dostęp do zwykłych narzędzi uzyskują przez most katalogu.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Włącz tryb kodu`},help:{"v1-rgstxz-aj":'Globalna aktywacja trybu kodu OpenClaw. Całkowity brak ustawienia globalnego oznacza domyślną wartość `"auto"`; jawnie zdefiniowany obiekt bez `enabled` pozostaje wyłączony. `"auto"` włącza tryb dla modeli preferujących katalog, natomiast `true` włącza go dla uruchomień obsługujących narzędzia. Nadpisania aktywacji na poziomie agenta i modelu mają pierwszeństwo. Jeśli środowisko wykonawcze jest niedostępne, uruchomienie z włączonym trybem kończy się błędem ze względów bezpieczeństwa, zamiast udostępniać pełną listę narzędzi.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Silnik wykonawczy trybu kodu`},help:{"v1-l8nlk2-6x":`Silnik wykonawczy JavaScript: "node" (domyślny) używa Node vm do wykonywania zaufanego kodu i nie stanowi bezpiecznego środowiska izolowanego; "quickjs" używa dołączonej wtyczki QuickJS WASM do wykonywania kodu gościa ze wzmocnionymi zabezpieczeniami. Uprawnienia narzędzi obowiązują w obu przypadkach. Jeśli wybrany silnik jest niedostępny, wykonanie zostaje zablokowane.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Limit danych wyjściowych trybu kodu`},help:{"v1-1hmij9q-1n":`Maksymalna liczba bajtów po serializacji zwracanych w danych wyjściowych trybu kodu.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Limit oczekujących wywołań narzędzi w trybie kodu`},help:{"v1-3b5tyd-2i":`Maksymalna liczba równoczesnych zagnieżdżonych wywołań narzędzi, które maszyna wirtualna w trybie kodu może uruchomić, zanim konieczne będzie jej późniejsze wznowienie.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Maksymalna liczba wyników wyszukiwania w trybie kodu`},help:{"v1-1gpue5r-28":`Maksymalna liczba wyników wyszukiwania w ukrytym katalogu, o które może poprosić program w trybie kodu.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Limit migawki w trybie kodu`},help:{"v1-1mmgkqy-1x":`Maksymalna liczba bajtów przechowywanych po serializacji dla jednej migawki zawieszonej maszyny QuickJS.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Limit pamięci w trybie kodu`},help:{"v1-xetora-6n":`Limit sterty gościa QuickJS lub orientacyjny budżet sterty V8 procesu roboczego Node w bajtach. Narzut środowiska uruchomieniowego Node i minimalne alokacje silnika wpływają na efektywny budżet; bufory zewnętrzne i pamięć RSS procesu nie są uwzględniane. Nie stanowi to gwarancji bezpieczeństwa.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Interfejs trybu kodu`},help:{"v1-dsp2b9-2x":'Interfejs dostępny dla modelu. Obsługiwana jest tylko wartość "only": udostępnia `exec` i `wait` w trybie kodu oraz ukrywa standardowe narzędzia.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Domyślna liczba wyników wyszukiwania w trybie kodu`},help:{"v1-1io42lu-2m":"Domyślna liczba wyników wyszukiwania w ukrytym katalogu zwracanych przez `catalog.search` w trybie kodu."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`Czas życia migawki w trybie kodu`},help:{"v1-1nxfczz-28":"Czas, przez który można wznowić zawieszone wykonania Code Mode za pomocą `wait`, zanim wygasną."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Limit czasu trybu kodu`},help:{"v1-8csycm-1p":"Maksymalny czas w milisekundach dla pojedynczego wywołania `exec` lub `wait` w trybie kodu."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Lista zablokowanych narzędzi`},help:{"v1-wilr1b-4p":`Globalna lista blokująca wymienione narzędzia, nawet gdy reguły profilu lub dostawcy na nie zezwalają. Używaj reguł blokowania do awaryjnego odcinania dostępu i długoterminowej ochrony wielowarstwowej.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Dostęp do narzędzi z podwyższonymi uprawnieniami`},help:{"v1-ehcm0r-5a":`Ustawienia kontroli dostępu do narzędzi z podwyższonymi uprawnieniami dla interfejsów poleceń uprzywilejowanych, które powinny być dostępne wyłącznie dla zaufanych nadawców. Pozostaw wyłączone, chyba że procesy operatora wyraźnie wymagają działań z podwyższonymi uprawnieniami.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Reguły zezwalania na narzędzia z podwyższonymi uprawnieniami`},help:{"v1-1u9bhih-54":`Reguły zezwalające nadawcom na korzystanie z narzędzi z podwyższonymi uprawnieniami, zwykle oparte na formatach identyfikatorów kanału lub dostawcy. Używaj ściśle określonych, jednoznacznych identyfikatorów, aby niepowołani użytkownicy nie mogli uruchamiać poleceń z podwyższonymi uprawnieniami.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Włącz dostęp do narzędzi z podwyższonymi uprawnieniami`},help:{"v1-1n8oyal-4l":`Włącza wykonywanie narzędzi z podwyższonymi uprawnieniami po pomyślnej weryfikacji nadawcy i zasad. Pozostaw wyłączone w kanałach publicznych lub współdzielonych i włączaj wyłącznie w zaufanych środowiskach obsługiwanych przez właściciela.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Narzędzie exec`},help:{"v1-p5piic-56":`Grupa zasad narzędzia exec dotyczących hosta wykonywania poleceń powłoki, trybu zabezpieczeń, sposobu zatwierdzania i powiązań środowiska uruchomieniowego. W środowisku produkcyjnym zachowaj ostrożne ustawienia domyślne i zaostrz ograniczenia wykonywania z podwyższonymi uprawnieniami.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Lista dozwolonych modeli dla apply_patch`},help:{"v1-4q5ovf-1x":`Opcjonalna lista dozwolonych identyfikatorów modeli (np. "gpt-5.4" lub "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`Włącz apply_patch`},help:{"v1-1erkir4-31":`Włącz lub wyłącz apply_patch dla modeli OpenAI i OpenAI Codex, jeśli zezwala na to polityka narzędzi (domyślnie: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch tylko w obszarze roboczym`},help:{"v1-x2z207-3o":`Ogranicz ścieżki apply_patch do katalogu obszaru roboczego (domyślnie: true). Ustaw false, aby zezwolić na zapis poza obszarem roboczym (niebezpieczne).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Opóźnienie powiadomienia o wykonywaniu po zatwierdzeniu exec (ms)`},help:{"v1-1gwwann-4z":`Opóźnienie w milisekundach przed wyświetleniem powiadomienia o trwającym wykonywaniu po zatwierdzeniu exec. Zwiększ je, aby ograniczyć migotanie przy szybkich poleceniach, lub zmniejsz, aby szybciej informować operatora.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Pytanie o zgodę na exec`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Wyróżnianie poleceń exec`},help:{"v1-kyxd4o-4n":`Pokazuj wyróżnienia poleceń na podstawie analizy składniowej w monitach o zatwierdzenie exec (domyślnie: false). Włącz tę opcję, aby wyświetlać wyróżniony tekst polecenia bez zmiany polityki zatwierdzania exec.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Okres ważności stałego zezwolenia (dni)`},help:{"v1-5uxe2j-6r":`Domyślny okres ważności w dniach (1-3650) stałych zezwoleń tworzonych przez allow-always podczas zatwierdzania automatyzacji. Jeśli nie ustawiono wartości, zezwolenia pozostają ważne do ich cofnięcia lub zmiany powiązanej automatyzacji. Warunki są ustalane w chwili utworzenia, więc zmiana tej wartości wpływa tylko na przyszłe zezwolenia.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Docelowe środowisko exec`},help:{"v1-rno1mf-5q":`Wybiera strategię określania miejsca wykonywania poleceń powłoki. Użyj "auto", aby dostosować działanie do środowiska uruchomieniowego (sandbox, gdy jest dostępny, w przeciwnym razie gateway), lub jawnie ustaw sandbox/gateway/node, gdy potrzebujesz stałego środowiska.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Tryb wykonywania`},help:{"v1-1wi6t4l-5q":`Selektor ujednoliconej polityki wykonywania. Użyj "auto", aby przypadki bez zatwierdzenia oceniał klasyfikator, "ask", aby oceniał je człowiek, "allowlist", aby dopuszczać wyłącznie polecenia uznane za bezpieczne według deterministycznych reguł, lub "full" do zaufanego działania lokalnego.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Powiązanie wykonywania z węzłem`},help:{"v1-rfnz54-4s":`Konfiguracja powiązania z węzłem dla narzędzi wykonywania, gdy wykonywanie poleceń jest delegowane do połączonych węzłów. Używaj jawnego powiązania z węzłem tylko wtedy, gdy wymagane jest kierowanie poleceń między wieloma węzłami.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Powiadamianie o zakończeniu wykonywania`},help:{"v1-1ounlvx-3q":`Gdy ustawiono true (domyślnie), zakończenie sesji wykonywania w tle oraz zdarzenia cyklu życia wykonywania na węzłach dodają zdarzenie systemowe do kolejki i żądają sygnału aktywności.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Powiadamianie o powodzeniu bez danych wyjściowych`},help:{"v1-1wx4xxd-3d":`Gdy ustawiono true, pomyślne zakończenie wykonywania w tle bez danych wyjściowych również dodaje do kolejki systemowe zdarzenie zakończenia (domyślnie: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Dodawanie katalogów na początku PATH`},help:{"v1-s1aimc-1r":`Katalogi dodawane na początku PATH podczas wykonywania poleceń (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Recenzent wykonywania`},help:{"v1-12y548k-4x":`Mechanizm oceny exec oparty na modelu, używany w trybie automatycznym przed przejściem do zatwierdzania przez człowieka. Ustaw tutaj osobny model do tego zadania, jeśli chcesz oddzielić ocenę exec od głównego modelu agenta.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Tryb szybki recenzenta wykonywania poleceń`},help:{"v1-175bx14-8u":`Opcjonalny tryb szybki oceny próśb o zatwierdzenie w OpenClaw: true żąda przetwarzania priorytetowego na obsługiwanych trasach OpenAI Responses i ChatGPT/OAuth; false żąda przetwarzania standardowego. Pomiń, aby zachować domyślne ustawienia dostawcy. Tryb szybki może kosztować więcej, a jego dostępność zależy od dostawcy. Nie konfiguruje natywnego Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Model oceniający exec`},help:{"v1-1lltiy5-3i":`Opcjonalne ustawienie dostawcy/modelu dla agenta oceniającego exec. Pomiń, aby użyć skonfigurowanego modelu głównego agenta docelowego.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Rozumowanie recenzenta wykonywania poleceń`},help:{"v1-yg2gby-6u":`Opcjonalny poziom wysiłku rozumowania przy ocenie próśb o zatwierdzenie przez model w OpenClaw: minimal, low, medium, high, xhigh lub max. Pomiń, aby zachować domyślne ustawienia dostawcy. Obsługiwane poziomy są normalizowane dla wybranego modelu. Nie konfiguruje natywnego Codex Guardian.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Limit czasu oceny exec (ms)`},help:{"v1-1o30chi-3w":`Limit czasu oceny exec w milisekundach dla każdego etapu przygotowania modelu i generowania odpowiedzi przed przejściem do zatwierdzania przez człowieka (domyślnie: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Profile bezpiecznych plików wykonywalnych exec`},help:{"v1-4cdcwe-29":`Opcjonalne profile bezpieczeństwa dla poszczególnych plików wykonywalnych (ograniczenia argumentów pozycyjnych + dozwolone/zabronione flagi).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Bezpieczne pliki wykonywalne exec`},help:{"v1-1of1m2s-21":`Zezwalaj na uruchamianie bezpiecznych plików wykonywalnych korzystających wyłącznie ze standardowego wejścia bez jawnych wpisów na liście dozwolonych.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Zaufane katalogi bezpiecznych plików wykonywalnych exec`},help:{"v1-zljbcn-2v":`Dodatkowe, jawnie wskazane katalogi uznawane za zaufane podczas sprawdzania ścieżek bezpiecznych plików wykonywalnych (wpisy PATH nigdy nie są automatycznie uznawane za zaufane).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Zabezpieczenia exec`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Wymagaj zatwierdzenia wykonywania kodu w wierszu poleceń`},help:{"v1-jkmgo7-5z":"Wymagaj jawnego zatwierdzenia wywołań interpretera wykonujących kod podany w wierszu poleceń, takich jak `python -c`, `node -e`, `ruby -e` lub `osascript -e`. Zapobiega to ponownemu użyciu listy dozwolonych bez pytania i zastępuje stałą zgodę pytaniem przy każdym takim wywołaniu."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Limit czasu wykonania (sekundy)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Narzędzia systemu plików tylko dla obszaru roboczego`},help:{"v1-1mhuvka-2s":`Ogranicz narzędzia systemu plików (read/write/edit/apply_patch) do katalogu obszaru roboczego (domyślnie: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`Tożsamość GitHub CLI i autor Git`},help:{"v1-1fl77im-5s":`Zarządzany lokalny profil GitHub CLI i opcjonalny autor Git dla narzędzi agenta. Pomiń ten obiekt, aby zachować własne konto i dane autora użytkownika, który uruchamia Gateway; poświadczenia dostępu do zdalnego repozytorium nigdy nie są nadpisywane.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Adres e-mail autora Git`},help:{"v1-kol5g6-1i":`Opcjonalny adres e-mail autora i osoby zatwierdzającej zmiany w Git, obowiązujący tylko w bieżącym procesie.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Nazwa autora Git`},help:{"v1-z5bl1f-1h":`Opcjonalna nazwa autora i osoby zatwierdzającej zmiany w Git, obowiązująca tylko w bieżącym procesie.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Typ poświadczeń GitHub`},help:{"v1-qi3qun-3q":`Oznacza zarządzany profil OAuth, którego rotacyjne poświadczenie odświeżania należy do Gateway. Profile bez tego oznaczenia używają osobistego tokenu dostępu.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`Wersja profilu GitHub`},help:{"v1-4lzl0-27":`Wygenerowany, nieinterpretowany identyfikator wersji profilu, używany do atomowego przełączania zarządzanych poświadczeń.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Włącz analizę linków`},help:{"v1-23t2io-59":`Włącz automatyczną analizę linków na etapie przetwarzania wstępnego, aby umożliwić podsumowanie treści pod adresami URL przed rozpoczęciem rozumowania agenta. Pozostaw włączone, aby zapewnić bogatszy kontekst, lub wyłącz, gdy wymagane jest ścisłe ograniczenie przetwarzania do minimum.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Maksymalna liczba linków do analizy`},help:{"v1-ksxmcv-52":`Maksymalna liczba linków rozwijanych w jednej turze podczas analizy linków. Używaj niższych wartości, aby ograniczyć opóźnienia i koszty w wątkach z dużą liczbą wiadomości, a wyższych, gdy kluczowy jest kontekst z wielu linków.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Modele do analizy linków`},help:{"v1-6j3mnw-5a":`Lista preferowanych modeli do zadań analizy linków, sprawdzanych po kolei jako opcje zapasowe, jeśli jest to obsługiwane. Do rutynowego podsumowywania używaj najpierw lekkich modeli, a bardziej wymagających tylko w razie potrzeby.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Zakres analizy linków`},help:{"v1-183cwpa-55":`Określa, kiedy uruchamiana jest analiza linków w zależności od kontekstu rozmowy i typu wiadomości. Ustaw wąski zakres, aby uniknąć zbędnego pobierania treści w przypadku wiadomości, w których linki nie wymagają przetwarzania.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Limit czasu analizy linków (s)`},help:{"v1-61v30o-4p":`Limit czasu analizy pojedynczego linku w sekundach, po którym nierozpoznane linki są pomijane. Ustaw ograniczony czas, aby uniknąć długich przestojów, gdy witryny zewnętrzne działają wolno lub są niedostępne.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Wykrywanie pętli wywołań narzędzi`},help:{"v1-1e3rls8-5g":`Steruje wykrywaniem pętli wywołań narzędzi na podstawie przesuwnego okna historii oraz ochroną po kompaktowaniu. Pomiń to ustawienie, aby pozostawić wykrywanie w oknie historii wyłączone, a ochronę po kompaktowaniu włączoną. Ustaw true, aby włączyć obie funkcje, lub false, aby obie wyłączyć.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Zasady przetwarzania załączników do analizy dźwięku`},help:{"v1-1s3t9s5-3o":`Wybierz, które pasujące załączniki audio mają być przetwarzane. Przetwarzaj tylko pierwszy załącznik, chyba że zamierzasz transkrybować wiele załączników.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Format wyświetlania transkrypcji`},help:{"v1-glpdzh-3i":`Sformatuj transkrypcję wysyłaną do czatu, używając znacznika {transcript}. Zachowaj znacznik bez zmian, aby wysłana wiadomość zawierała transkrypcję.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Wysyłaj transkrypcję do czatu`},help:{"v1-1dedp8c-3r":`Wysyłaj transkrypcję nagrania do czatu źródłowego przed przetworzeniem przez agenta. Włącz tę opcję, gdy użytkownicy potrzebują sprawdzić, co usłyszał system.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Włącz rozumienie dźwięku`},help:{"v1-1v0x7te-2m":`Włącz rozumienie dźwięku, aby wiadomości głosowe i nagrania dźwiękowe mogły być transkrybowane na potrzeby kontekstu agenta.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Język rozumienia dźwięku`},help:{"v1-1ruqt97-3z":`Domyślna wskazówka dotycząca języka dla dostawców transkrypcji dźwięku. Ustaw ją, gdy główny język mówiony jest znany, a jego wykrywanie przez dostawcę jest zawodne.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Maksymalna liczba bajtów dla rozumienia dźwięku`},help:{"v1-1mcckc8-43":`Domyślny limit rozmiaru wejściowych danych dźwiękowych dla skonfigurowanych i automatycznie wykrytych modeli. Ustaw go na rozmiar największego nagrania, jakie powinni przyjmować Twoi dostawcy i Twoja sieć.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Maksymalna liczba znaków dla rozumienia dźwięku`},help:{"v1-eo1dp-43":`Domyślna maksymalna długość transkrypcji dla skonfigurowanych i automatycznie wykrytych modeli. Użyj niższej wartości, aby długie wiadomości głosowe nie zwiększały nadmiernie kontekstu agenta.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Preferowany model rozumienia dźwięku`},help:{"v1-1n5zya1-3c":`Preferuj jeden wpis tools.media.models oznaczony obsługiwaną funkcją transkrypcji dźwięku przed pozostałymi zgodnymi opcjami zapasowymi.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Prompt analizy dźwięku`},help:{"v1-1v5jtay-4b":`Domyślny prompt transkrypcji dźwięku, gdy wpis modelu go nie nadpisuje. Zachowaj niezmienną instrukcję, jeśli dalsze procesy zależą od stylu transkrypcji.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Zakres analizy dźwięku`},help:{"v1-1pptfg0-3w":`Ogranicz analizę dźwięku według kanału, typu czatu lub klucza źródła. Zawęź ten zakres tam, gdzie automatyczna transkrypcja dotyczy wrażliwych treści lub jest kosztowna.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Limit czasu analizy dźwięku (s)`},help:{"v1-n8wc6c-3b":`Domyślny limit czasu żądań analizy dźwięku. Zwiększ go dla długich nagrań lub wolniejszych lokalnych modeli transkrypcji.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Równoległość analizy multimediów`},help:{"v1-13kr9np-58":`Maksymalna liczba równoczesnych operacji analizy multimediów na turę, łącznie dla zadań dotyczących obrazów, dźwięku i wideo. Zmniejsz tę wartość we wdrożeniach o ograniczonych zasobach, aby zapobiec przeciążeniu procesora lub sieci.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Zasady obsługi załączników w analizie obrazów`},help:{"v1-11hofbw-3e":`Wybierz, które pasujące załączniki graficzne mają być przetwarzane. Przetwarzaj tylko pierwszy załącznik, chyba że analiza wielu obrazów jest zamierzona.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Włącz analizę obrazów`},help:{"v1-1b2zw34-50":`Włącz analizę obrazów, aby załączone lub wskazane obrazy mogły być interpretowane jako kontekst tekstowy. Wyłącz tę opcję, jeśli potrzebujesz obsługi wyłącznie tekstu lub chcesz uniknąć kosztów przetwarzania obrazów.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Maksymalna liczba bajtów dla analizy obrazów`},help:{"v1-jwwpd1-3v":`Domyślny limit rozmiaru obrazu wejściowego dla skonfigurowanych i automatycznie wykrytych modeli. Dostosuj tę wartość do limitów rozmiaru danych u dostawcy i przepustowości sieci w środowisku wdrożenia.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Maksymalna liczba znaków dla analizy obrazów`},help:{"v1-ebnxhk-3q":`Domyślna maksymalna długość opisu obrazu. Użyj niższej wartości, aby uzyskać zwięzły kontekst, lub wyższej, aby uzyskać szczegółowe wyniki OCR i analizy sceny.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Preferowany model analizy obrazów`},help:{"v1-1o2uwo6-3c":`Nadaj pierwszeństwo jednemu wpisowi tools.media.models oznaczonemu odpowiednią funkcją analizy obrazów przed pozostałymi zgodnymi opcjami zapasowymi.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Prompt analizy obrazów`},help:{"v1-1jdcu8b-3u":`Domyślny prompt analizy obrazów używany, gdy wpis go nie zastępuje. Zadbaj o jego deterministyczność, jeśli systemy korzystające z wyników wymagają spójnych opisów.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Zakres analizy obrazów`},help:{"v1-tievo1-3s":`Ogranicz analizę obrazów według kanału, typu czatu lub klucza źródła. W kanałach o dużym ruchu lub niezaufanych stosuj wąski zakres, aby kontrolować przetwarzanie.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Limit czasu analizy obrazów (s)`},help:{"v1-1wcm84x-31":`Domyślny limit czasu żądań analizy obrazów. Zwiększ go w przypadku dużych obrazów lub wolniejszych lokalnych modeli wizyjnych.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Wspólne modele analizy multimediów`},help:{"v1-f34u65-47":`Kanoniczna lista modeli analizy multimediów. Przy każdym wpisie używaj tagów możliwości image, audio lub video, aby każdy potok wybierał tylko zgodne modele zapasowe.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Zasady przetwarzania załączników do analizy wideo`},help:{"v1-1qm1qrc-3e":`Wybierz, które pasujące załączniki wideo będą przetwarzane. Przetwarzaj tylko pierwszy załącznik, chyba że celowo chcesz analizować wiele nagrań.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Włącz analizę wideo`},help:{"v1-1ltx5gl-58":`Włącz analizę wideo, aby tworzyć tekstowe podsumowania klipów na potrzeby dalszego wnioskowania i udzielania odpowiedzi. Wyłącz ją, jeśli przetwarzanie wideo jest niezgodne z zasadami lub zbyt kosztowne w Twoim wdrożeniu.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Maksymalna liczba bajtów do analizy wideo`},help:{"v1-2mp77v-3v":`Domyślny limit rozmiaru wejściowego wideo dla modeli skonfigurowanych i wykrywanych automatycznie. Dostosuj go do limitów rozmiaru danych dostawcy i przepustowości dostępnej w danym wdrożeniu.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Maksymalna liczba znaków opisu wideo`},help:{"v1-1j0x40b-3j":`Domyślna maksymalna długość opisu wideo. Użyj niższej wartości, aby uzyskać zwięzły kontekst, lub wyższej, aby uzyskać szczegółowe podsumowania scen.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Preferowany model analizy wideo`},help:{"v1-1cygq5k-3c":`Preferuj jeden wpis tools.media.models oznaczony odpowiednią funkcjonalnością do analizy wideo przed pozostałymi zgodnymi opcjami rezerwowymi.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Prompt do analizy wideo`},help:{"v1-ul2jx4-3r":`Domyślny prompt do analizy wideo, gdy wpis nie definiuje własnego. Zachowaj jego deterministyczny charakter, jeśli odbiorcy polegają na spójnych podsumowaniach.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Zakres analizy wideo`},help:{"v1-7gfrx3-3s":`Ogranicz analizę wideo według kanału, typu czatu lub klucza źródła. Na kanałach o dużym ruchu lub niezaufanych ustaw wąski zakres, aby kontrolować przetwarzanie.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Limit czasu analizy wideo (s)`},help:{"v1-e8rzsy-33":`Domyślny limit czasu żądań analizy wideo. Zwiększ go dla dłuższych klipów lub wolniejszych lokalnych modeli analizy.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Lista dozwolonych akcji wiadomości`},help:{"v1-1iceqwa-5c":`Globalna lista dozwolonych akcji wiadomości dla narzędzia message. Używaj jej tylko wtedy, gdy całe środowisko uruchomieniowe ma udostępniać i akceptować ograniczony zestaw akcji; w przypadku agentów publicznych lub działających w piaskownicy preferuj listy dozwolonych akcji dla poszczególnych agentów.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Włącz rozsyłanie wiadomości`},help:{"v1-1ms74z7-14":`Włącz akcję broadcast (domyślnie: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Zezwalaj na wysyłanie między kontekstami (u różnych dostawców)`},help:{"v1-276qxo-2s":`Zezwalaj na wysyłanie między różnymi dostawcami (domyślnie: true). Ustaw false, aby zablokować wysyłanie wiadomości między dostawcami.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Zezwalaj na wysyłanie między kontekstami (ten sam dostawca)`},help:{"v1-1sg4x49-1z":`Zezwalaj na wysyłanie do innych kanałów u tego samego dostawcy (domyślnie: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Znacznik wysyłania między kontekstami`},help:{"v1-1fg6jrp-1z":`Dodawaj widoczny znacznik pochodzenia podczas wysyłania między kontekstami (domyślnie: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Prefiks znacznika wysyłania między kontekstami`},help:{"v1-eblsru-1p":`Prefiks tekstowy znaczników wysyłania między kontekstami (obsługuje "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Sufiks znacznika wysyłania między kontekstami`},help:{"v1-1nk0jub-1p":`Sufiks tekstowy znaczników wysyłania między kontekstami (obsługuje "{channel}").`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Profil narzędzi`},help:{"v1-h6k98q-5k":`Nazwa globalnego profilu narzędzi używanego do wyboru wstępnie zdefiniowanej bazowej polityki narzędzi przed zastosowaniem nadpisań zezwoleń i odmów. Używaj go, aby zachować spójne zasady środowiska dla wszystkich agentów, i nie zmieniaj nazw profili.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Polityka narzędzi w piaskownicy`},help:{"v1-ea7awo-4k":`Warstwa polityki narzędzi dla wykonań agentów w piaskownicy, umożliwiająca określenie odrębnych granic ich możliwości. Używaj jej, aby wymuszać silniejsze zabezpieczenia w kontekstach piaskownicy.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Polityka zezwoleń i odmów dla narzędzi w piaskownicy`},help:{"v1-ub701o-4t":`Polityka zezwoleń i odmów dotycząca narzędzi, stosowana podczas działania agentów w środowiskach wykonawczych piaskownicy. Ograniczaj uprawnienia do minimum, aby zadania w piaskownicy nie mogły prowadzić do niepotrzebnych działań zewnętrznych.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Widoczność sesji dla narzędzi`},help:{"v1-1vtq2rh-c5":`Określa, do których sesji mogą odwoływać się sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all" — domyślnie: dowolna sesja w Gateway, w tym sesje innych agentów i użytkowników; "agent" = dowolna sesja o identyfikatorze bieżącego agenta; "self" = tylko bieżąca sesja; "tree" = bieżąca sesja + sesje uruchomionych subagentów). Dostęp między agentami jest domyślnie włączony, a jego zakres określa tools.agentToAgent; użyj węższego zakresu widoczności, aby ograniczyć dostęp.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Zasady dostępu subagentów do narzędzi`},help:{"v1-1xoug01-4z":`Zestaw zasad dostępu do narzędzi dla uruchamianych subagentów, który ogranicza lub rozszerza dostępność narzędzi względem domyślnych ustawień agenta nadrzędnego. Użyj go, aby możliwości delegowanych agentów odpowiadały celowi zadania.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Zasady zezwalania i blokowania narzędzi subagentów`},help:{"v1-7vxsbf-5d":`Zasady zezwalania i blokowania narzędzi stosowane w środowiskach uruchomieniowych subagentów. Zakres uprawnień powinien być węższy niż zakres agenta nadrzędnego. Narzędzia należące do agenta nadrzędnego, takie jak progress_card, są zawsze zablokowane, również przy użyciu allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Rój`},help:{"v1-1q96vvs-45":`Orkiestracja subagentów w trybie zbierania wyników. Domyślnie włączona; ustaw false, aby ją wyłączyć. Uprawnienia do narzędzi nadal obowiązują dla agents_wait i opcji uruchamiania roju.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Domyślny agent roju`},help:{"v1-p4alpg-2m":`Domyślny agent docelowy dla uruchomień w roju, w których pominięto agentId. Lista dozwolonych subagentów nadal obowiązuje.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Włącz rój`},help:{"v1-1nnnrq9-2e":`Włącza subagentów w trybie zbierania wyników oraz agents_wait. Domyślnie włączone; ustaw false, aby wyłączyć.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Aktywne procesy potomne na grupę roju`},help:{"v1-kfx6qp-1c":`Maksymalna liczba aktywnych procesów potomnych zbierających dane na grupę roju.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`Równoległe procesy potomne roju`},help:{"v1-1d46jtm-1s":`Maksymalna liczba równolegle działających procesów potomnych zbierających dane na grupę roju.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Łączna liczba procesów potomnych na grupę roju`},help:{"v1-1gc9vl1-1e":`Maksymalna liczba uruchomień procesów zbierających dane w całym okresie istnienia grupy roju.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Maksymalny limit czasu oczekiwania roju`},help:{"v1-bog18y-1g":`Maksymalny limit czasu akceptowany przez agents_wait, w sekundach.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Wyszukiwanie narzędzi`},help:{"v1-s0kx04-7y":`Zmniejsz rozmiar dużych katalogów narzędzi OpenClaw, MCP i klienta. Gdy opcja nie jest ustawiona, środowiska wykonawcze OpenClaw automatycznie używają ustrukturyzowanego wyszukiwania narzędzi; włączony tryb kodu ma pierwszeństwo, a Codex korzysta z własnego mechanizmu wyszukiwania. Ustaw false, aby wyłączyć tę funkcję, true, aby użyć mostka kodu, lub użyj formy obiektowej, aby wybrać tryb.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`Limit czasu wykonania kodu wyszukiwania narzędzi`},help:{"v1-105r499-34":"Maksymalny czas pojedynczego wykonania `tool_search_code` w milisekundach. Środowisko wykonawcze ogranicza wartości do obsługiwanego zakresu od 1 do 60 sekund."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Włącz wyszukiwanie narzędzi`},help:{"v1-1vm3hfr-4h":"Włącza wyszukiwanie narzędzi. Gdy opcja jest włączona, podczas pracy we wbudowanym środowisku wykonawczym OpenClaw ukrywa duże katalogi narzędzi za `tool_search_code` lub strukturalnymi narzędziami do wyszukiwania, opisywania i wywoływania."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Maksymalna liczba wyników wyszukiwania narzędzi`},help:{"v1-7du4kh-32":`Maksymalna liczba wyników wyszukiwania narzędzi, o którą może poprosić model. Środowisko wykonawcze ogranicza wartości do obsługiwanego zakresu 1..50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Interfejs wyszukiwania narzędzi`},help:{"v1-jybcbe-7x":'Wybierz interfejs dostępny dla modelu: "code" udostępnia `tool_search_code`; "tools" udostępnia ustrukturyzowane narzędzia rezerwowe do wyszukiwania, opisywania i wywoływania; "directory" utrzymuje widoczny katalog narzędzi o ograniczonym rozmiarze, udostępnia ograniczony zestaw prawdopodobnie potrzebnych lub wymaganych schematów, a pozostałe udostępnia dopiero przez wyszukiwanie, opisywanie i wywoływanie.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Domyślna liczba wyników wyszukiwania narzędzi`},help:{"v1-1uchq7t-39":"Domyślna liczba wyników wyszukiwania narzędzi zwracanych, gdy model nie poda limitu. Środowisko wykonawcze ogranicza tę wartość do `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Włącz narzędzie do tworzenia ustrukturyzowanych planów`},help:{"v1-1xgegme-4o":"Ujednolicone narzędzie statusu `progress_card` do trwałych planów i notatek opisowych w sesjach nadrzędnych. Domyślnie włączone; ustaw false, aby je wyłączyć. Nigdy nie jest dostępne dla podagentów."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Narzędzia internetowe`},help:{"v1-fpsy5-4y":`Grupa ustawień zasad narzędzi internetowych obejmująca dostawców wyszukiwania i pobierania, limity oraz konfigurację działania awaryjnego. Utrzymuj włączone ustawienia w zgodzie z dostępnością kluczy API i zasadami wychodzącego ruchu sieciowego.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`TTL pamięci podręcznej pobierania stron (min)`},help:{"v1-1hk89qp-17":`TTL pamięci podręcznej wyników web_fetch w minutach.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Włącz narzędzie do pobierania stron`},help:{"v1-yrswld-1f":`Włącz narzędzie web_fetch (lekkie pobieranie przez HTTP).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Nagłówki żądań pobierania z sieci`},help:{"v1-16bjkv5-me":"Dodatkowe nagłówki wysyłane z bezpośrednimi żądaniami web_fetch, na przykład nagłówki routingu bramy lub uwierzytelniania. Każda skonfigurowana wartość jest traktowana jako poufna i ukrywana w udostępnianej konfiguracji oraz zapisach debugowania. Wartości są zwykłymi ciągami znaków, obsługują podstawianie ${VAR} i globalną sekwencję $${VAR} pozwalającą zachować zapis dosłowny, a także są wysyłane pod adresy URL wybrane przez model. Wpisy są sprawdzane podczas tworzenia żądania, a nie podczas wczytywania konfiguracji, więc nieprawidłowa nazwa lub wartość, której nie można wysłać, jest pomijana i odnotowywana w dzienniku zamiast wyłączać funkcję; pomijane są również Accept, Accept-Language, User-Agent i nagłówki określające ramkowanie, takie jak Transfer-Encoding. Aby zmienić agenta użytkownika, użyj tools.web.fetch.userAgent. Przy przekierowaniach między różnymi źródłami zachowywane są wyłącznie nagłówki z listy bezpiecznych nagłówków dozwolonych przez guarded-fetch, a zmiana faktycznie wysyłanych nagłówków powoduje wydzielenie osobnej części pamięci podręcznej pobierania."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Maksymalna liczba znaków przy pobieraniu z sieci`},help:{"v1-12d1fw7-1d":`Maksymalna liczba znaków zwracanych przez web_fetch (nadmiar jest obcinany).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Bezwzględny limit liczby znaków przy pobieraniu z sieci`},help:{"v1-cl2mf1-1v":`Bezwzględny limit wartości maxChars dla web_fetch (dotyczy konfiguracji i wywołań narzędzia).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Maksymalna liczba przekierowań przy pobieraniu z sieci`},help:{"v1-t6eak9-1h":`Maksymalna liczba przekierowań dozwolonych dla web_fetch (domyślnie: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Maksymalny rozmiar danych pobieranych z sieci (bajty)`},help:{"v1-q6ld9c-10":`Maksymalny rozmiar pobieranych danych przed obcięciem.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Dostawca pobierania z sieci`},help:{"v1-6pb3nv-v":`Identyfikator zapasowego dostawcy pobierania treści z sieci.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Wyodrębnianie treści przez Readability przy pobieraniu z sieci`},help:{"v1-19exqzx-2c":`Używaj Readability do wyodrębniania głównej treści z HTML (z podstawowym oczyszczaniem HTML jako metodą zapasową).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Polityka SSRF przy pobieraniu z sieci`},help:{"v1-qtn7zx-3c":`Nadpisania polityki SSRF o ograniczonym zakresie dla web_fetch. Ogranicz je do minimum i włączaj tylko w znanych środowiskach z serwerem proxy w sieci lokalnej.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Dozwolone nazwy hostów przy pobieraniu z sieci`},help:{"v1-1j9ctya-35":`Dokładne nazwy hostów lub dosłowne adresy IP dozwolone dla web_fetch, w tym cele, które w przeciwnym razie byłyby blokowane. Ogranicz listę do minimum.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Zezwalaj na zakres unikalnych adresów lokalnych IPv6 przy pobieraniu z sieci`},help:{"v1-1eyz55i-3b":`Zezwalaj na unikalne adresy lokalne IPv6 (fc00::/7), aby zapewnić zgodność z zaufanymi serwerami proxy typu fake-IP, takimi jak sing-box, Clash lub Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Zezwalaj na zakres testowy RFC 2544 przy pobieraniu z sieci`},help:{"v1-u5asdb-2y":`Zezwalaj na adresy IP z zakresu testowego RFC 2544 (198.18.0.0/15), aby zapewnić zgodność z serwerami proxy typu fake-IP, takimi jak Clash lub Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Blokowane nazwy hostów przy pobieraniu z sieci`},help:{"v1-1164vvk-66":`Wzorce nazw hostów blokowanych przed rozwiązywaniem DNS i sprawdzaniem reguł zezwalających przy każdym przekierowaniu web_fetch. Obsługuje dokładne nazwy hostów oraz "*.example.com" wyłącznie dla subdomen; dodaj osobno "example.com", aby zablokować domenę główną. Pusta lub nieustawiona wartość nie dodaje żadnych blokad.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Pobieranie z sieci — niebezpieczne zezwolenie na dostęp do sieci prywatnej`},help:{"v1-2s6mv7-3t":`Zezwala web_fetch na dostęp do zasobów w sieciach prywatnych i wewnętrznych. Pozostaw wyłączone, chyba że adresy URL wybierane przez model są zaufane w tym wdrożeniu.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Limit czasu pobierania z sieci (s)`},help:{"v1-1c3yfr4-16":`Limit czasu żądań web_fetch w sekundach.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent pobierania z sieci`},help:{"v1-s7pe8j-1e":`Zastępuje nagłówek User-Agent w żądaniach web_fetch.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Zaufany serwer proxy ze zmiennych środowiskowych dla pobierania z sieci`},help:{"v1-1ypkqj7-54":`Kieruje web_fetch przez zaufany serwer proxy HTTP(S) skonfigurowany w zmiennych środowiskowych i pozwala mu rozwiązywać nazwy DNS. Włącz tylko wtedy, gdy ten serwer proxy jest kontrolowany przez operatora i egzekwuje zasady ruchu wychodzącego po rozwiązaniu nazw DNS.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`TTL pamięci podręcznej wyszukiwania w sieci (min)`},help:{"v1-6trzlf-18":`Czas przechowywania wyników web_search w pamięci podręcznej (TTL) w minutach.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Włącz narzędzie wyszukiwania w sieci`},help:{"v1-n1cm4y-27":`Włącza zarządzane narzędzie web_search oraz opcjonalne natywne wyszukiwanie Codex dla obsługiwanych modeli.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Maksymalna liczba wyników wyszukiwania w sieci`},help:{"v1-mrw7mi-z":`Liczba zwracanych wyników (1–10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Dozwolone domeny Codex`},help:{"v1-1cv4y44-43":`Lista dozwolonych domen dla natywnego narzędzia web_search w Codex. W turach korzystających z natywnego wyszukiwania hostowanego ogranicza również zarządzane narzędzie web_fetch; tury korzystające z zarządzanego dostawcy pozostają bez zmian.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Rozmiar kontekstu wyszukiwania Codex`},help:{"v1-antack-1u":`Wskazówka dotycząca rozmiaru kontekstu natywnego wyszukiwania Codex: "low", "medium" lub "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Włącz natywne wyszukiwanie w sieci w Codex`},help:{"v1-ek2jzd-1k":`Włącz natywne wyszukiwanie w sieci w Codex dla modeli obsługujących Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Tryb wyszukiwania w sieci w Codex`},help:{"v1-1ahyq9f-32":`Preferowany tryb natywnego wyszukiwania w sieci w Codex: "cached" (domyślny; w turach Codex bez ograniczeń używany jest zamiast niego tryb "live") lub "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Miasto użytkownika Codex`},help:{"v1-1y95orp-1d":`Przybliżona lokalizacja na poziomie miasta przekazywana do natywnego wyszukiwania w sieci w Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Kraj użytkownika Codex`},help:{"v1-1xkm5ms-1g":`Przybliżona lokalizacja na poziomie kraju przekazywana do natywnego wyszukiwania w sieci w Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Region użytkownika Codex`},help:{"v1-lhar02-1l":`Przybliżony region lub stan przesyłany do natywnego wyszukiwania w sieci Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Strefa czasowa użytkownika Codex`},help:{"v1-fgv9fh-1h":`Przybliżona strefa czasowa przesyłana do natywnego wyszukiwania w sieci Codex.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Dostawca wyszukiwania w sieci`},help:{"v1-10omglr-1x":`Identyfikator dostawcy wyszukiwania. Jeśli zostanie pominięty, jest wykrywany automatycznie na podstawie dostępnych kluczy API.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Limit czasu wyszukiwania w sieci (s)`},help:{"v1-i0egvw-17":`Limit czasu w sekundach dla żądań web_search.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transkrypcje`},help:{"v1-1i0sc09-66":`Podstawowe ustawienia rejestrowania transkrypcji dla notatek ze spotkań, narzędzi agenta z funkcją nagrywania i skonfigurowanych źródeł automatycznego uruchamiania transkrypcji spotkań na żywo. Wtyczki spotkań domyślnie zapisują trwałe notatki; ustaw enabled na false, aby wyłączyć tę funkcję globalnie.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Źródła automatycznego uruchamiania transkrypcji`},help:{"v1-1mzsl79-5s":`Źródła transkrypcji na żywo zarządzane automatycznie od uruchomienia Gateway. Każdy wpis jest aktywny dzięki samej obecności na liście; usuń wpis, aby wyłączyć dane źródło. Źródła rejestrują w sposób ciągły, chyba że włączono whenOccupied.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`Identyfikator konta transkrypcji`},help:{"v1-6g2kjj-4b":`Opcjonalny identyfikator konta dostawcy lub obszaru roboczego dla źródeł transkrypcji wymagających jednoznacznego wskazania konta. Użyj formatu identyfikatora konta opisanego w dokumentacji dostawcy.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`Identyfikator kanału transkrypcji`},help:{"v1-1lk9d5o-4u":`Identyfikator kanału u dostawcy będącego źródłem transkrypcji na żywo, na przykład kanału głosowego Discord lub kanału spotkań Slack. Przed włączeniem automatycznego uruchamiania sprawdź znaczenie identyfikatorów u danego dostawcy.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`Identyfikator serwera Discord`},help:{"v1-fyfgnk-4l":`Opcjonalny identyfikator serwera Discord dla źródeł transkrypcji głosowych Discord. Skonfiguruj go wraz z odpowiednim channelId, gdy dostawca wymaga wyszukiwania kanału głosowego w obrębie serwera.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`Adres URL spotkania do transkrypcji`},help:{"v1-1xtt9ci-4f":`Opcjonalny adres URL spotkania dla dostawców, którzy dołączają przez adres URL zamiast identyfikatora kanału. Używaj tylko zaufanych linków do spotkań, ponieważ automatyczne uruchamianie może spowodować dołączenie do spotkania i jego rejestrowanie.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`Identyfikator dostawcy źródła transkrypcji`},help:{"v1-1uur06p-3s":`Identyfikator dostawcy źródła transkrypcji, na przykład dostawcy obsługującego kanały głosowe Discord lub przyszłego dostawcy obsługującego spotkania Slack. Użyj dokładnego identyfikatora udostępnianego przez wtyczkę dostawcy.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`Identyfikator sesji transkrypcji`},help:{"v1-xyo4x5-5o":`Opcjonalny stały identyfikator sesji transkrypcji dla tego automatycznie uruchamianego źródła. Ignorowany, gdy whenOccupied ma wartość true. Pozostaw nieustawiony, aby identyfikatory były generowane automatycznie, chyba że potrzebujesz stałego selektora dziennego i możesz uniknąć kolizji w obrębie tego samego dnia.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Tytuł transkrypcji`},help:{"v1-ycjnmp-5y":`Opcjonalny tytuł przyszłych sesji rejestrowania transkrypcji. Zmiana samych tytułów nie przerywa bieżących sesji ani nie zmienia ich pierwotnie przypisanego tytułu lub zapisanych notatek. Inne zmiany źródła podlegają standardowym zasadom ponownego uruchamiania.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Rejestrowanie transkrypcji przy obecności uczestników`},help:{"v1-34jid4-78":`Rozpoczynaj nową sesję transkrypcji za każdym razem, gdy w źródle pojawią się ludzie, i kończ ją (generując notatki) po opuszczeniu źródła przez ostatnią osobę. Wymaga dostawcy, który zgłasza obecność uczestników, takiego jak discord-voice. Domyślnie: false (ciągłe rejestrowanie od uruchomienia Gateway).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transkrypcje włączone`},help:{"v1-fyqqr0-6d":`Włącza trwałe zapisywanie automatycznych notatek ze spotkań, narzędzie agenta transcripts oraz skonfigurowane źródła uruchamiane automatycznie. Domyślnie: true. Ustaw false, aby wyłączyć trwałe zapisywanie i narzędzie; jawnie wybrany tryb transkrypcji spotkania zachowuje ograniczony podgląd najnowszej treści na żywo.`}},tts:{label:{"v1-bmxkk9-e":`Zamiana tekstu na mowę`},help:{"v1-1o27tk2-4n":`Zasady zamiany tekstu na mowę służące do odczytywania odpowiedzi agenta na głos w obsługiwanych interfejsach głosowych lub audio. Pozostaw wyłączone, chyba że odtwarzanie głosu jest częścią sposobu pracy operatora lub użytkownika.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`Persona TTS`},help:{"v1-1r0opcb-29":`Identyfikator domyślnej persony TTS. Lokalne preferencje persony TTS mogą zastąpić tę wartość na poszczególnych hostach.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`Persony TTS`},help:{"v1-19aybhl-2l":`Nazwane persony TTS, które definiują stałą tożsamość głosową oraz powiązania syntezy mowy właściwe dla dostawcy.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`Persona TTS`},help:{"v1-10s52ah-2l":`Pojedyncza persona TTS. Używaj powiązań właściwych dla dostawcy, aby wskazać konkretne głosy, modele i szablony promptów.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Powiązania persony TTS z dostawcami`},help:{"v1-993jop-3e":`Powiązania persony TTS specyficzne dla dostawcy, indeksowane według identyfikatora dostawcy mowy. Są scalane z tts.providers dla aktywnej persony i mają pierwszeństwo przed jego ustawieniami.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Ustawienia dostawców TTS`},help:{"v1-1k80nl4-4y":`Ustawienia TTS specyficzne dla dostawcy, indeksowane według identyfikatora dostawcy mowy. Używaj ich zamiast wbudowanych kluczy najwyższego poziomu specyficznych dla dostawcy, aby wtyczki mowy pozostały niezależne od podstawowego schematu konfiguracji.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Konfiguracja dostawcy TTS`},help:{"v1-dwapva-3d":`Konfiguracja TTS specyficzna dla jednego identyfikatora dostawcy mowy. Ogranicz pola do zakresu wtyczki obsługującej tego dostawcę.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`Klucz API dostawcy TTS`},help:{"v1-1m2fj0i-2o":`Klucz API używany przez tego dostawcę mowy, gdy jego wtyczka wymaga uwierzytelnionego dostępu do TTS.`}},tui:{label:{"v1-c8hus1-b":`Interfejs terminalowy`},help:{"v1-1fg9vw2-3s":`Ustawienia wyświetlania interfejsu terminalowego. Używaj tej sekcji do ustawiania preferencji prezentacji tylko w terminalu, bez zmiany działania Gateway ani innych interfejsów.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Stopka interfejsu terminalowego`},help:{"v1-6e12l3-3k":`Ustawienia wyświetlania stopki interfejsu terminalowego. Zachowaj zwięzłą formę opcjonalnego kontekstu, aby informacje o sesji, modelu, celu i tokenach pozostały czytelne.`}},ui:{label:{"v1-ye4dff-2":`Interfejs użytkownika`},help:{"v1-dt1924-42":`Ustawienia wyglądu interfejsu dotyczące akcentów i preferencji wyświetlania operatora. Używaj ich do dostosowania czytelności bez zmiany działania w czasie wykonywania.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Kolor akcentu użytkownika`},help:{"v1-16klzws-4z":`Kolor akcentu Control UI: #RRGGBB dla koloru niestandardowego lub 'theme' dla palety wybranego motywu. Zastępuje ui.seamColor; wyczyść tę wartość, aby odziedziczyć skonfigurowany kolor łączenia lub domyślny kolor motywu.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Kolor akcentu`},help:{"v1-14q3r4h-4g":`Główny kolor akcentu używany w interfejsie do wyróżnień, plakietek i elementów identyfikacji wizualnej. Używaj kolorów o wysokim kontraście, które pozostają czytelne zarówno w jasnych, jak i ciemnych motywach.`}},update:{label:{"v1-k12u1x-7":`Aktualizacje`},help:{"v1-11c5k8v-5c":`Ustawienia kanału aktualizacji i sprawdzania przy uruchomieniu, które zapewniają aktualność środowiska wykonawczego OpenClaw. W środowiskach produkcyjnych używaj zachowawczych kanałów, a bardziej eksperymentalnych tylko w kontrolowanych środowiskach.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Automatyczne aktualizacje włączone`},help:{"v1-49xs2h-3c":`Włącz automatyczne aktualizacje w tle dla instalacji pakietowych z kanałów stable i beta; aktualizacje extended-stable nigdy nie są stosowane automatycznie (domyślnie: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Kanał aktualizacji`},help:{"v1-lqtdvf-5b":`Kanał aktualizacji dla instalacji git + npm ("stable", "extended-stable", "beta" lub "dev"). Kanał extended-stable jest dostępny tylko dla instalacji pakietowych: instalacja odbywa się wyłącznie na pierwszym planie, z opcjonalnymi wskazówkami przy uruchomieniu, które nie wprowadzają zmian.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Sprawdzanie aktualizacji przy uruchomieniu`},help:{"v1-qy3q9g-5v":`Sprawdza dostępność aktualizacji przy uruchamianiu Gateway, w tym wskazówek dotyczących extended-stable przeznaczonych tylko do odczytu (domyślnie: true). Ustaw false, aby wyłączyć automatyczne sprawdzanie i stosowanie aktualizacji Gateway oraz węzłów bez interfejsu graficznego, a także anonimowe sygnały sprawdzania aktualizacji.`}},voicewake:{label:{"v1-txt1wb-a":`Wybudzanie głosem`}},web:{label:{"v1-1ae9z56-b":`Kanał internetowy`}},wizard:{label:{"v1-28jonk-h":`Preferencje konfiguracji`},help:{"v1-14jh6rm-3b":`Preferencje konfiguracji należące do użytkownika. Historia kreatora i stan potwierdzeń należące do urządzenia są przechowywane we współdzielonej bazie danych stanu.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Dostęp do wykrywania podczas konfiguracji`},help:{"v1-1nqxt0w-38":`Zgoda na wykrywanie podczas konfiguracji z przewodnikiem: "full" skanuje bez pytania, a "guarded" pyta przed sprawdzeniem lokalnych aplikacji.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Rekomendacje aplikacji podczas konfiguracji`},help:{"v1-ub8uoi-30":`Określa, czy konfiguracja z przewodnikiem może używać nazw zainstalowanych aplikacji do rekomendowania odpowiednich wtyczek i umiejętności.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Znacznik czasu ostatniego uruchomienia kreatora`},help:{"v1-1y0fbk-1k":`Znacznik czasu ostatniego uruchomienia kreatora, którego wyniki pomyślnie zapisano.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Polecenie ostatniego uruchomienia kreatora`},help:{"v1-x2pfkk-15":`Polecenie, które wywołało ostatnie uruchomienie kreatora.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit ostatniego uruchomienia kreatora`},help:{"v1-h0jkmt-1i":`Commit kodu źródłowego użyty podczas ostatniego uruchomienia kreatora w wersji deweloperskiej.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Tryb ostatniego uruchomienia kreatora`},help:{"v1-16508qy-1r":`Określa, czy ostatnie uruchomienie kreatora dotyczyło konfiguracji "local", czy "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Wersja ostatniego uruchomienia kreatora`},help:{"v1-1tr4z9d-19":`Wersja OpenClaw użyta podczas ostatniego uruchomienia kreatora.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Znacznik czasu potwierdzenia zasad bezpieczeństwa w kreatorze`},help:{"v1-86i182-2a":`Znacznik czasu potwierdzenia zasad bezpieczeństwa podczas konfiguracji, zapisany wraz z konfiguracją docelową.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Przyspieszanie tworzenia drzew roboczych`},help:{"v1-9es3gc-4r":`Używaj przyspieszania operacji systemu plików dla nowych zarządzanych drzew roboczych, jeśli jest obsługiwane (domyślnie: true). Ustaw false, aby używać standardowego pobierania plików z Git i ich kopiowania. Dotyczy tylko nowych drzew roboczych.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Katalog główny drzew roboczych`},help:{"v1-1tgti9j-5d":`Globalny katalog dla nowych zarządzanych drzew roboczych. Użyj ścieżki bezwzględnej lub ~ dla katalogu domowego; domyślnie <state-dir>/worktrees. Po zmianie tego ustawienia istniejące drzewa robocze zachowują swoje zapisane ścieżki.`}}}}})))()}export{t as n,n as t};